
--#SET TERMINATOR @
BEGIN
IF NOT EXISTS (SELECT bpname FROM syscat.bufferpools WHERE UPPER(LTRIM(RTRIM(bpname))) = 'BPDATA32K') THEN
EXECUTE IMMEDIATE 
'CREATE BUFFERPOOL BPDATA32K IMMEDIATE SIZE AUTOMATIC PAGESIZE 32K';
END IF;
END@
BEGIN
IF NOT EXISTS (SELECT bpname FROM syscat.bufferpools WHERE UPPER(LTRIM(RTRIM(bpname))) = 'BPIDX32K') THEN
EXECUTE IMMEDIATE 
'CREATE BUFFERPOOL BPIDX32K  IMMEDIATE SIZE AUTOMATIC PAGESIZE 32K';
END IF;
END@
BEGIN
IF NOT EXISTS (SELECT bpname FROM syscat.bufferpools WHERE UPPER(LTRIM(RTRIM(bpname))) = 'BPTEMP32K') THEN
EXECUTE IMMEDIATE 
'CREATE BUFFERPOOL BPTEMP32K IMMEDIATE SIZE AUTOMATIC PAGESIZE 32K';
END IF;
END@

BEGIN
IF NOT EXISTS (SELECT tbspace FROM syscat.tablespaces WHERE UPPER(LTRIM(RTRIM(tbspace))) = 'TS_DATA') THEN
EXECUTE IMMEDIATE 
'CREATE REGULAR TABLESPACE TS_DATA IN DATABASE PARTITION GROUP IBMDEFAULTGROUP PAGESIZE 32K MANAGED BY AUTOMATIC STORAGE AUTORESIZE YES BUFFERPOOL BPDATA32K PREFETCHSIZE AUTOMATIC USING STOGROUP IBMSTOGROUP INCREASESIZE 50 M MAXSIZE NONE';
END IF;
END@
BEGIN
IF NOT EXISTS (SELECT tbspace FROM syscat.tablespaces WHERE UPPER(LTRIM(RTRIM(tbspace))) = 'TS_IDX') THEN
EXECUTE IMMEDIATE 
'CREATE REGULAR TABLESPACE TS_IDX IN DATABASE PARTITION GROUP IBMDEFAULTGROUP PAGESIZE 32K MANAGED BY AUTOMATIC STORAGE AUTORESIZE YES BUFFERPOOL BPIDX32K PREFETCHSIZE AUTOMATIC USING STOGROUP IBMSTOGROUP INCREASESIZE 50 M MAXSIZE NONE';
END IF;
END@
BEGIN
IF NOT EXISTS (SELECT tbspace FROM syscat.tablespaces WHERE UPPER(LTRIM(RTRIM(tbspace))) = 'TS_TMP') THEN
EXECUTE IMMEDIATE 
'CREATE USER TEMPORARY TABLESPACE TS_TMP IN DATABASE PARTITION GROUP IBMDEFAULTGROUP PAGESIZE 32K MANAGED BY AUTOMATIC STORAGE BUFFERPOOL BPTEMP32K USING STOGROUP IBMSTOGROUP';
END IF;
END@
BEGIN
IF NOT EXISTS (SELECT tbspace FROM syscat.tablespaces WHERE UPPER(LTRIM(RTRIM(tbspace))) = 'SYSTOOLSPACE') THEN
EXECUTE IMMEDIATE 
'CREATE TABLESPACE SYSTOOLSPACE IN IBMCATGROUP MANAGED BY AUTOMATIC STORAGE USING STOGROUP IBMSTOGROUP EXTENTSIZE 4';
END IF;
END@

