CREATE OR REPLACE TRIGGER AAUTONETWORKJOBS_ONDELETE_T1 AFTER DELETE ON AAUTONETWORKJOBS REFERENCING OLD TABLE AS DELETED FOR EACH STATEMENT MODE DB2SQL BEGIN ATOMIC DELETE FROM AAUTONETWORKJOBSDEPENDENCIES A WHERE EXISTS ( SELECT 1 FROM DELETED D WHERE D.NETWORKJOBSID = A.PREVIOUSJOBID ); END @
CREATE OR REPLACE TRIGGER AAUTONETWORKS_ONDELETE_T1 AFTER DELETE ON AAUTONETWORKS REFERENCING OLD TABLE AS DELETED FOR EACH STATEMENT MODE DB2SQL BEGIN ATOMIC DELETE FROM AAUTONETWORKDEPENDENCIES A WHERE EXISTS ( SELECT 1 FROM DELETED D WHERE D.NETWORKID = A.PRECEEDINGNETWORKID ); END @
