CREATE OR REPLACE VIEW CA7_GRAPH_JOBSVSJOBSDEPENDENCIES_V AS SELECT * FROM ( SELECT CJDJ.JOBID, CJDJ.DEPENDENTON_JOBID, CJDJ.SCHID AS INSCHID, CJDJ.SCHID AS OUTSCHID, CJDJ.SCHID AS INDEPENDENTON_SCHID, CJDJ.SCHID AS OUTDEPENDENTON_SCHID, CDT.TYPEID, CDT.TYPENAME AS DEPENDENCYTYPE, CJDJ.VRSN, CJDJ.LEADTM, 2 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, CL.ROOTID FROM CA7_JOBSDEPENDENTONJOBS CJDJ INNER JOIN CA7_JOBS CJ ON CJDJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_DEPENDENCYTYPE CDT ON CJDJ.DEPENDENCYTYPEID = CDT.TYPEID UNION SELECT CJDJ.JOBID, CJDJ.DEPENDENTON_JOBID, CJDJ.SCHID AS INSCHID, CJTJ2.INSCHID AS OUTSCHID, CJTJ1.INSCHID AS INDEPENDENTON_SCHID, CJDJ.SCHID AS OUTDEPENDENTON_SCHID, CDT.TYPEID, CDT.TYPENAME AS DEPENDENCYTYPE, CJDJ.VRSN, CJDJ.LEADTM, 2 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, CL.ROOTID FROM CA7_JOBSDEPENDENTONJOBS CJDJ INNER JOIN CA7_JOBS CJ ON CJDJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_DEPENDENCYTYPE CDT ON CJDJ.DEPENDENCYTYPEID = CDT.TYPEID INNER JOIN CA7_JOBSTRIGGEREDBYJOBS CJTJ1 ON CJDJ.DEPENDENTON_JOBID = CJTJ1.JOBID INNER JOIN CA7_JOBSTRIGGEREDBYJOBS CJTJ2 ON CJDJ.JOBID = CJTJ2.TRIGGEREDBY_JOBID UNION SELECT CJDJ.JOBID, CJDJ.DEPENDENTON_JOBID, CJDJ.SCHID AS INSCHID, CJTJ2.INSCHID AS OUTSCHID, CJDJ.SCHID AS INDEPENDENTON_SCHID, CJDJ.SCHID AS OUTDEPENDENTON_SCHID, CDT.TYPEID, CDT.TYPENAME AS DEPENDENCYTYPE, CJDJ.VRSN, CJDJ.LEADTM, 2 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, CL.ROOTID FROM CA7_JOBSDEPENDENTONJOBS CJDJ INNER JOIN CA7_JOBS CJ ON CJDJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_DEPENDENCYTYPE CDT ON CJDJ.DEPENDENCYTYPEID = CDT.TYPEID INNER JOIN CA7_JOBSTRIGGEREDBYJOBS CJTJ2 ON CJDJ.JOBID = CJTJ2.TRIGGEREDBY_JOBID UNION SELECT CJDJ.JOBID, CJDJ.DEPENDENTON_JOBID, CJDJ.SCHID AS INSCHID, CJDJ.SCHID AS OUTSCHID, CJTJ1.INSCHID AS INDEPENDENTON_SCHID, CJDJ.SCHID AS OUTDEPENDENTON_SCHID, CDT.TYPEID, CDT.TYPENAME AS DEPENDENCYTYPE, CJDJ.VRSN, CJDJ.LEADTM, 2 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, CL.ROOTID FROM CA7_JOBSDEPENDENTONJOBS CJDJ INNER JOIN CA7_JOBS CJ ON CJDJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_DEPENDENCYTYPE CDT ON CJDJ.DEPENDENCYTYPEID = CDT.TYPEID INNER JOIN CA7_JOBSTRIGGEREDBYJOBS CJTJ1 ON CJDJ.DEPENDENTON_JOBID = CJTJ1.JOBID )SRC@
