CREATE OR REPLACE VIEW GETADSPROCESSESNEEDEDFORBUILD AS SELECT PTH.PATHSTR FROM ADSPROCESSMAPPING APM INNER JOIN PROGRAMS PGM ON APM.PROGRAMID = PGM.PROGRAMID INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE APM.NEEDSTOBEBUILT = 'YES'@
CREATE OR REPLACE VIEW GETALLADSMAPPEDPROCESSES AS SELECT PTH.PATHSTR FROM ADSPROCESSMAPPING APM INNER JOIN PROGRAMS PGM ON APM.PROGRAMID = PGM.PROGRAMID INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID@
