CREATE OR REPLACE VIEW GETJCLSTATEMENTS10 AS SELECT SID, TID, STATEMENTTYPE, STARTROW, ENDROW, STARTCOL, ENDCOL, PATHSTR, OCCURID FROM ( SELECT IUE.PROGID AS SID, SR.RESOURCEID AS TID, SR.STATEMENTTYPE, OS.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, PTH.PATHSTR, OS.OCCURID FROM INNUNIONEDGES IUE INNER JOIN OCCURRENCESSTMT OS ON IUE.PROGID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN PATHS PTH ON OS.PATHID = PTH.PATHID WHERE SR.RESOURCETYPE = 5 AND IUE.EDGETYPE <> -1 UNION SELECT IUE.PROGID AS SID, PGM.PROGRAMID AS TID, SR.STATEMENTTYPE, OS.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, PTH.PATHSTR, OS.OCCURID FROM INNUNIONEDGES IUE INNER JOIN OCCURRENCESSTMT OS ON IUE.PROGID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON SR.OCCURID = OS.OCCURID INNER JOIN RESOURCES RES ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN PROGRAMALIASES PGM ON RES.PROGNAME = PGM.ALIASNAME INNER JOIN PATHS PTH ON OS.PATHID = PTH.PATHID WHERE RES.PROGNAME IS NOT NULL AND SR.RESOURCETYPE = 14 AND IUE.EDGETYPE <> -1 ) SRC@
