CREATE OR REPLACE VIEW GETPRINTERFILES AS SELECT F.LOGICALNAME, ST.DESCRIPTION, OS.STARTROW AS STARTROW0, OS.STARTCOL AS STARTCOL0, OS.ENDROW AS ENDROW0, OS.ENDCOL AS ENDCOL0, PTH.PATHSTR, PRG.PROGRAMNAME, F.NAME, F.PROGID AS PROGID FROM PROGRAMS PRG INNER JOIN OCCURRENCESSTMT OS ON PRG.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON SR.OCCURID = OS.OCCURID INNER JOIN STATEMENTS ST ON ST.STATEMENTTYPE = OS.STATEMENTTYPE INNER JOIN FILES F ON SR.RESOURCEID = F.FILEID INNER JOIN PATHS PTH ON OS.PATHID = PTH.PATHID WHERE F.PROGID = 0 AND (F.TYPECODE IS NULL OR F.TYPECODE = 32) AND SR.RESOURCETYPE = 9 AND PRG.PROGRAMTYPEID = 1 UNION SELECT F.LOGICALNAME, ST.DESCRIPTION, OS.STARTROW AS STARTROW0, OS.STARTCOL AS STARTCOL0, OS.ENDROW AS ENDROW0, OS.ENDCOL AS ENDCOL0, PTH.PATHSTR, PRG.PROGRAMNAME, F.NAME, F.PROGID AS PROGID FROM PROGRAMS PRG INNER JOIN FILES F ON PRG.PROGRAMID = F.PROGID INNER JOIN STATEMENTREFERENCE SR ON SR.RESOURCEID = F.FILEID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID INNER JOIN STATEMENTS ST ON ST.STATEMENTTYPE = OS.STATEMENTTYPE INNER JOIN PATHS PTH ON OS.PATHID = PTH.PATHID WHERE (F.TYPECODE IS NULL OR F.TYPECODE = 32) AND SR.RESOURCETYPE = 9 AND PRG.PROGRAMTYPEID = 1@
