CREATE OR REPLACE VIEW GETTS_ADSMAPSFULL AS SELECT PTH.PATHSTR, AM.ETIMESTAMP FROM ADSMAPS AM INNER JOIN OCCURRENCES OCC ON AM.MAPID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 95@
