CREATE OR REPLACE VIEW GETTS_NATURALDDMFULL AS SELECT PTH.PATHSTR, ND.ETIMESTAMP FROM NATURALDDM ND INNER JOIN OCCURRENCES OCC ON ND.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 192@
