CREATE OR REPLACE VIEW GETTS_SMARTDEFFILESFULL AS SELECT PTH.PATHSTR, SR.ETIMESTAMP FROM PATHS PTH INNER JOIN SMARTRESOURCES SR ON PTH.PATHID = SR.PATHID@
CREATE OR REPLACE VIEW GETTS_SMARTDELETEREPORTSFULL AS SELECT PATHSTR, ETIMESTAMP FROM DELETEREPORTS@
CREATE OR REPLACE VIEW GETTS_SMARTPRINTERFILESFULL AS SELECT PTH.PATHSTR, PF.ETIMESTAMP FROM PRINTERFILEDDS PF INNER JOIN OCCURRENCES OCC ON PF.ID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 70@
CREATE OR REPLACE VIEW GETTS_SMARTSCREENSFULL AS SELECT PTH.PATHSTR, SD.ETIMESTAMP FROM SCREENDDS SD INNER JOIN OCCURRENCES OCC ON SD.ID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 69@
CREATE OR REPLACE VIEW GETTSBMSFULL AS SELECT PTH.PATHSTR, B.ETIMESTAMP FROM BMS B INNER JOIN OCCURRENCES OCC ON B.BMSID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 6@
CREATE OR REPLACE VIEW GETTSINCLGROUPFULL AS SELECT JP.RESOURCEFILEPATH, JIG.ETIMESTAMP FROM JCLPOSITION JP INNER JOIN JCLINCLUDEGROUP JIG ON JP.POSITIONID = JIG.POSITIONID WHERE JP.RESOURCETYPE = 33 @
CREATE OR REPLACE VIEW GETTSJOBFULL AS SELECT JP.RESOURCEFILEPATH, JJ.ETIMESTAMP FROM JCLJOB JJ INNER JOIN JCLPOSITION JP ON JJ.POSITIONID = JP.POSITIONID WHERE JP.RESOURCETYPE = 22 @
CREATE OR REPLACE VIEW GETTSPROCFULL AS SELECT JP.RESOURCEFILEPATH, JPROC.ETIMESTAMP FROM JCLPOSITION JP INNER JOIN JCLPROC JPROC ON JP.POSITIONID = JPROC.POSITIONID WHERE JP.RESOURCETYPE = 25 @
CREATE OR REPLACE VIEW GETTSPROGFULL AS SELECT PTH.PATHSTR, PGM.ETIMESTAMP FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 5 @
CREATE OR REPLACE VIEW GETTSRESFULL AS SELECT PTH.PATHSTR, RES.ETIMESTAMP FROM RESOURCES RES INNER JOIN OCCURRENCES OCC ON RES.RESOURCEID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE IN (13, 67, 60, 57, 94, 99)@
CREATE OR REPLACE VIEW VME_AM_IDMSX_TAB_SCHEMA_DEFINITION AS SELECT DISTINCT '' AS SUBSCHEMA, NAME AS SCHEMA, -1 AS SUBSCHEMAOCCURID, SOURCEINFO AS SCHEMAOCCURID FROM DDCLELEMENT WHERE DDSTYPEID = 6@
CREATE OR REPLACE VIEW IDMSTAB_GETPL1PROGRAMS_CACHE AS SELECT * FROM TMPIDMS4@
CREATE OR REPLACE VIEW IDMSTAB_GETSCHEMASUBSCHEMAPATHS AS SELECT * FROM ( SELECT DISTINCT ISC.ID AS SCHEMAID, ISC.SCHEMANAME, OCC.STARTROW, OCC.STARTCOL, OCC.ENDROW, OCC.ENDCOL, PTH.PATHSTR AS SCHEMAPATH, ISS.ID AS SUBSCHEMAID, ISS.SUBSCHEMANAME, OCCURRENCES_1.STARTROW AS SUBSCHSR, OCCURRENCES_1.STARTCOL AS SUBSCHSC, OCCURRENCES_1.ENDROW AS SUBSCHER, OCCURRENCES_1.ENDCOL AS SUBSCHEC, PATHS_1.PATHSTR AS SUBSCHEMAPATH FROM IDMSSUBSCHEMA ISS LEFT OUTER JOIN IDMSSCHEMA ISC ON ISS.SCHEMAID = ISC.ID LEFT OUTER JOIN OCCURRENCES OCC ON ISC.OCCURID = OCC.OCCURID LEFT OUTER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID LEFT OUTER JOIN OCCURRENCES AS OCCURRENCES_1 ON ISS.OCCURID = OCCURRENCES_1.OCCURID LEFT OUTER JOIN PATHS AS PATHS_1 ON OCCURRENCES_1.PATHID = PATHS_1.PATHID UNION ALL SELECT DISTINCT 0 AS SCHEMAID, VAI.SCHEMA AS SCHEMANAME, VAST.STARTROW, VAST.STARTCOL, VAST.ENDROW, VAST.ENDCOL, CAST(VAST.PATHSTR AS VARCHAR(30000)) AS SCHEMAPATH, 0 AS SUBSCHEMAID, VAI.SUBSCHEMA AS SUBSCHEMANAME, - 1 AS SUBSCHSR, - 1 AS SUBSCHSC, - 1 AS SUBSCHER, - 1 AS SUBSCHEC, '""' AS SUBSCHEMAPATH FROM VME_AM_IDMSX_TAB_SCHEMA_DEFINITION VAI INNER JOIN VME_AM_SOURCEPOSITION_TMP VAST ON VAI.SCHEMAOCCURID = VAST.SOURCEINFOID )SRC@
CREATE OR REPLACE VIEW NPROGS10 AS SELECT * FROM ( SELECT SR.RESOURCEID AS ID FROM NPROGS NP INNER JOIN OCCURRENCESSTMT OS ON NP.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID WHERE SR.RESOURCETYPE = 5 UNION SELECT PGM.PROGRAMID AS ID FROM NPROGS NP INNER JOIN OCCURRENCESSTMT OS ON NP.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON SR.OCCURID = OS.OCCURID INNER JOIN RESOURCES RES ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN PROGRAMS PGM ON RES.PROGNAME = PGM.PROGRAMNAME WHERE RES.PROGNAME IS NOT NULL AND SR.RESOURCETYPE = 14 )SRC@
CREATE OR REPLACE VIEW NPROGS10B AS SELECT * FROM ( SELECT OS.PROGID AS ID FROM NPROGS NP INNER JOIN STATEMENTREFERENCE SR ON NP.PROGRAMID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID WHERE SR.RESOURCETYPE = 5 UNION SELECT OS.PROGID AS ID FROM NPROGS NP INNER JOIN PROGRAMS PGM ON NP.PROGRAMID = PGM.PROGRAMID INNER JOIN RESOURCES RES ON RES.PROGNAME = PGM.PROGRAMNAME INNER JOIN STATEMENTREFERENCE SR ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID WHERE RES.PROGNAME IS NOT NULL AND PGM.PROGRAMTYPEID > 0 AND SR.RESOURCETYPE = 14 )SRC@
CREATE OR REPLACE VIEW NPROGS10BCENTRICGRAPH AS SELECT NPB.ID AS ID, PGM.PROGRAMTYPEID AS PGTYPE FROM PROGRAMS PGM INNER JOIN NPROGS10B NPB ON PGM.PROGRAMID = NPB.ID@
CREATE OR REPLACE VIEW NPROGS10BF AS SELECT * FROM ( SELECT OS.PROGID AS ID FROM NPROGS NP INNER JOIN STATEMENTREFERENCE SR ON NP.PROGRAMID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID WHERE SR.RESOURCETYPE = 5 AND SR.RESOURCEID >= 0 UNION SELECT OS.PROGID AS ID FROM NPROGS NP INNER JOIN PROGRAMS PGM ON NP.PROGRAMID = PGM.PROGRAMID INNER JOIN RESOURCES RES ON RES.PROGNAME = PGM.PROGRAMNAME INNER JOIN STATEMENTREFERENCE SR ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID WHERE RES.PROGNAME IS NOT NULL AND PGM.PROGRAMTYPEID > 0 AND SR.RESOURCETYPE = 14 UNION SELECT SR.RESOURCEID AS ID FROM NPROGS NP INNER JOIN OCCURRENCESSTMT OS ON NP.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID WHERE SR.RESOURCETYPE = 5 AND SR.RESOURCEID >= 0 UNION SELECT PGM.PROGRAMID AS ID FROM NPROGS NP INNER JOIN OCCURRENCESSTMT OS ON NP.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON SR.OCCURID = OS.OCCURID INNER JOIN RESOURCES RES ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN PROGRAMS PGM ON RES.PROGNAME = PGM.PROGRAMNAME WHERE RES.PROGNAME IS NOT NULL AND PGM.PROGRAMTYPEID > 0 AND SR.RESOURCETYPE = 14 )SRC@
CREATE OR REPLACE VIEW NPROGS10CENTRICGRAPH AS SELECT N.ID AS ID, P.PROGRAMTYPEID AS PGTYPE FROM NPROGS10 N INNER JOIN PROGRAMS P ON N.ID = P.PROGRAMID@
CREATE OR REPLACE VIEW NPROGS2 AS SELECT PGM.PROGRAMNAME FROM NPROGS NP INNER JOIN PROGRAMS PGM ON NP.PROGRAMID = PGM.PROGRAMID@
CREATE OR REPLACE VIEW PROCJOBREPORT AS SELECT DISTINCT JJ.JOBNAME, JPROC.PROCNAME, JPH.DATASETNAME FROM UNIONDESTNODES UDN INNER JOIN JCLPHYSICALDATASET JPH ON UDN.RESOURCEFILENAME = JPH.DATASETNAME INNER JOIN JCLDDREF JREF ON JREF.DATASETID = JPH.DATASETID INNER JOIN JCLJOB JJ ON JREF.JOBID = JJ.JOBID INNER JOIN JCLPROC JPROC ON JREF.PROCID = JPROC.PROCID INNER JOIN INNUNIONEDGES IUE ON JPROC.PROCNAME = IUE.EDGEFILENAME WHERE JPROC.PROCID > 0@
CREATE OR REPLACE VIEW QINNSOURCENODES AS SELECT CAST( LENGTH( CAST(PAR.PARAID AS VARCHAR(20)) ) AS VARCHAR(20)) || CAST(PAR.PARAID AS VARCHAR(20)) || CAST(2 AS VARCHAR(20)) AS SOURCEIDNODE, CAST( LENGTH( CAST(OCC.RESOURCEID AS VARCHAR(20)) ) AS VARCHAR(20)) || CAST(OCC.RESOURCEID AS VARCHAR(20)) || CAST(9 AS VARCHAR(20)) AS TARGETID, 2 AS SOURCETYPE, PAR.PARANAME AS SOURCENAME, PTH.PATHSTR AS SOURCEFILENAME, OCC.STARTROW AS SOURCESTARTROW, OCC.ENDROW AS SOURCEENDROW, OCC.STARTCOL AS SOURCESTARTCOL, OCC.ENDCOL AS SOURCEENDCOL, ORDINALNUM AS SOURCEORDINALNUM, PAR.PROGRAMID AS PROGID FROM PARAGRAPHS PAR INNER JOIN OCCURRENCES OCC ON PAR.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID INNER JOIN NPROGS N ON PAR.PROGRAMID = N.PROGRAMID@
CREATE OR REPLACE VIEW QPROGSUMMARYSQLTABLE AS SELECT DISTINCT 'Table' AS TYPE, ST.TABLENAME AS NAME, PGM.PROGRAMNAME FROM PROGRAMS PGM INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN SQLTABLES ST ON ST.SQLTABLEID = SR.RESOURCEID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 1 AND PGM.OCCURID <> 0@
CREATE OR REPLACE VIEW QPROGSUMMARYFILE AS SELECT DISTINCT 'File' AS TYPE, F.LOGICALNAME AS NAME, PGM.PROGRAMNAME FROM INNUNIONEDGES IUE INNER JOIN PROGRAMS PGM ON IUE.EDGEFILENAME = PGM.PROGRAMNAME INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN FILES F ON F.FILEID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 9 AND PGM.OCCURID <> 0@
CREATE OR REPLACE VIEW QPROGSUMMARYCOPY AS SELECT DISTINCT 'Copy' AS TYPE, RES.NAME AS NAME, PGM.PROGRAMNAME FROM PROGRAMS PGM INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN RESOURCES RES ON RES.RESOURCEID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 13 AND PGM.OCCURID <> 0@
CREATE OR REPLACE VIEW QPROGSUMMARYBMS AS SELECT DISTINCT 'Bms' AS TYPE, B.BMSNAME AS NAME, PGM.PROGRAMNAME FROM PROGRAMS PGM INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN BMS B ON B.BMSID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 6 AND PGM.OCCURID <> 0@
CREATE OR REPLACE VIEW QJCLMINIMIZEDDIRECTCALLPROGRAMEDGES AS SELECT DISTINCT JJ.JOBID, JPGM.PGMNAME, MIN(JCLPOSITION_1.STARTROW) AS STARTROW, MIN(JCLPOSITION_1.ENDROW) AS ENDROW, MIN(JCLPOSITION_1.STARTCOL) AS STARTCOL, MIN(JCLPOSITION_1.ENDCOL) AS ENDCOL, JPOS.RESOURCEFILEPATH, MIN(JCLPOSITION_1.POSITIONID) AS POSITIONID FROM JCLPOSITION AS JCLPOSITION_1 INNER JOIN JCLSTEP JS ON JCLPOSITION_1.POSITIONID = JS.POSITIONID INNER JOIN JCLPGM JPGM ON JPGM.PGMID = JS.CALLEDPGMID INNER JOIN JCLJOB JJ ON JJ.JOBID = JS.JOBID INNER JOIN JCLPOSITION JPOS ON JPOS.POSITIONID = JJ.POSITIONID GROUP BY JJ.JOBID, JPGM.PGMNAME, JPOS.RESOURCEFILEPATH, JS.CALLEDPGMID, JS.CALLINGSTEPID, JPOS.RESOURCETYPE HAVING JS.CALLEDPGMID > 0 AND JS.CALLINGSTEPID = 0 AND JPOS.RESOURCETYPE = 22@
CREATE OR REPLACE VIEW QJCLMINIMIZEDINDIRECTCALLPROGRAMEDGES AS SELECT DISTINCT JJ.JOBID, JPGM.PGMNAME, MIN(JCLPOSITION_1.STARTROW) AS STARTROW, MIN(JCLPOSITION_1.ENDROW) AS ENDROW, MIN(JCLPOSITION_1.STARTCOL) AS STARTCOL, MIN(JCLPOSITION_1.ENDCOL) AS ENDCOL, JCLPOSITION_1.RESOURCEFILEPATH, MIN(JCLPOSITION_1.POSITIONID) AS POSITIONID, JPOS.RESOURCEFILEPATH AS JOBRESOURCEFILEPATH FROM JCLPOSITION JPOS INNER JOIN JCLJOB JJ ON JPOS.POSITIONID = JJ.POSITIONID INNER JOIN JCLSTEP JS ON JJ.JOBID = JS.JOBID INNER JOIN JCLSTEP AS JCLSTEP_1 ON JS.STEPID = JCLSTEP_1.CALLINGSTEPID INNER JOIN JCLPGM JPGM ON JPGM.PGMID = JCLSTEP_1.CALLEDPGMID INNER JOIN JCLPOSITION AS JCLPOSITION_1 ON JCLPOSITION_1.POSITIONID = JCLSTEP_1.POSITIONID GROUP BY JJ.JOBID, JPGM.PGMNAME, JCLPOSITION_1.RESOURCEFILEPATH, JPOS.RESOURCEFILEPATH, JS.CALLEDPGMID, JS.CALLEDPROCID, JCLSTEP_1.CALLEDPGMID HAVING JS.CALLEDPGMID = 0 AND JS.CALLEDPROCID <> 0 AND JCLSTEP_1.CALLEDPGMID <> 0@
CREATE OR REPLACE VIEW QINNMINIMIZEDADABASFILEEDGES AS SELECT * FROM ( SELECT SOURCEID, TARGETID, EDGETYPE, EDGECONDITIONALINFO, MIN(OCCURID) AS EDGEID, TARGETTYPE, RESOURCEID, BREAD FROM( SELECT CAST( LENGTH( CAST(OS.PARAID AS VARCHAR(20)) ) AS VARCHAR(20)) || CAST(OS.PARAID AS VARCHAR(20)) || CAST(2 AS VARCHAR(20)) AS SOURCEID, CAST( LENGTH( CAST(SR.RESOURCEID AS VARCHAR(20)) ) AS VARCHAR(20)) || CAST(SR.RESOURCEID AS VARCHAR(20)) || CAST(62 AS VARCHAR(20)) AS TARGETID, OS.STATEMENTTYPE AS EDGETYPE, OS.STMTINFO AS EDGECONDITIONALINFO, OS.OCCURID, SR.RESOURCETYPE AS TARGETTYPE, SR.RESOURCEID, SR.BREAD, OS.PROGID FROM NPROGS NP INNER JOIN OCCURRENCESSTMT OS ON NP.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID WHERE OS.STATEMENTTYPE IN (256, 261, 262, 263, 264, 268, 270, 271, 272, 273, 277, 281, 309, 319, 322, 325, 347, 368, 372) AND SR.RESOURCETYPE = 62 )SRC1 GROUP BY SOURCEID, TARGETID, EDGETYPE, EDGECONDITIONALINFO, TARGETTYPE, RESOURCEID, BREAD, PROGID UNION SELECT SOURCEID, TARGETID, EDGETYPE, EDGECONDITIONALINFO, MIN(OCCURID) AS EDGEID, TARGETTYPE, RESOURCEID, BREAD FROM( SELECT CAST( LENGTH( CAST(OS.PARAID AS VARCHAR(20)) ) AS VARCHAR(20)) || CAST(OS.PARAID AS VARCHAR(20)) || CAST(2 AS VARCHAR(20)) AS SOURCEID, CAST( LENGTH( CAST(SR.RESOURCEID AS VARCHAR(20)) ) AS VARCHAR(20)) || CAST(SR.RESOURCEID AS VARCHAR(20)) || CAST(192 AS VARCHAR(20)) AS TARGETID, OS.STATEMENTTYPE AS EDGETYPE, OS.STMTINFO AS EDGECONDITIONALINFO, OS.OCCURID, SR.RESOURCETYPE AS TARGETTYPE, SR.RESOURCEID, SR.BREAD, OS.PROGID FROM NPROGS NP INNER JOIN OCCURRENCESSTMT OS ON NP.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID WHERE OS.STATEMENTTYPE IN(256, 261, 262, 263, 264, 268, 270, 271, 272, 273, 277, 281, 309, 319, 322, 325, 347, 368, 372) AND SR.RESOURCETYPE = 192 )SRC2 GROUP BY SOURCEID, TARGETID, EDGETYPE, EDGECONDITIONALINFO, TARGETTYPE, RESOURCEID, BREAD, PROGID )SRC @
CREATE OR REPLACE VIEW QHEURISTIC1 AS SELECT P.PROGRAMID FROM PROGRAMS P INNER JOIN INNUNIONEDGES I ON P.PROGRAMID = I.PROGID WHERE P.OCCURID <> 0@
CREATE OR REPLACE VIEW QHEURISTICSQLSTATEMENT AS SELECT QH.PROGRAMID, COUNT(*) AS SQLSTATEMENT FROM QHEURISTIC1 QH INNER JOIN OCCURRENCESSTMT OS ON QH.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE > 185 AND OS.STATEMENTTYPE < 227 GROUP BY QH.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICASSIGNMENTSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS ASSIGNMENTSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE IN (7, 13, 27,36) GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICCALLXCTLLINKSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS CALLXCTLLINKSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE IN (10, 138, 142, 390, 391, 392) GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICCICSSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS CICSSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE > 55 AND OS.STATEMENTTYPE < 186 GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICCONDITIONALSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS CONDITIONALSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE IN (18, 23) GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICDECLAREDRECORDS AS SELECT H1.PROGRAMID, COUNT(*) AS DECLAREDRECORDS FROM QHEURISTIC1 H1 INNER JOIN VARIABLES V ON H1.PROGRAMID = V.PROGIDREFERENCE WHERE V.ISCOPY = 0 AND V.ILEVEL = 1 GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICDECLAREDRECORDSFROMCOPIES AS SELECT H1.PROGRAMID, COUNT(*) AS DECLAREDRECORDSFROMCOPIES FROM QHEURISTIC1 H1 INNER JOIN VARIABLES V ON H1.PROGRAMID = V.PROGIDREFERENCE WHERE V.ISCOPY <> 0 AND V.ILEVEL = 1 GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICGOTOSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS GOTOSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE = 22 GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICIOSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS IOSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE IN (12, 15, 29, 31, 32, 34, 35, 37, 38, 43) GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICPERFORMSTATEMENT AS SELECT H1.PROGRAMID, COUNT(*) AS PERFORMSTATEMENT FROM QHEURISTIC1 H1 INNER JOIN OCCURRENCESSTMT OS ON H1.PROGRAMID = OS.PROGID WHERE OS.STATEMENTTYPE = 30 GROUP BY H1.PROGRAMID@
CREATE OR REPLACE VIEW QHEURISTICSTATEMENTSEZREPORTS AS SELECT OS.PROGID, OS.STATEMENTTYPE, COUNT(*) AS STATEMENTSCOUNT FROM OCCURRENCESSTMT OS GROUP BY OS.PROGID, OS.STATEMENTTYPE@
CREATE OR REPLACE VIEW QHALSTEAD21 AS SELECT P.PROGRAMID, COUNT(*) AS CNT FROM PROGRAMS P INNER JOIN OCCURRENCESSTMT OS ON P.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON P.PROGRAMID = IUE.PROGID INNER JOIN UNIONDESTNODES UDN ON OS.STATEMENTTYPE = UDN.RESOURCETYPE GROUP BY P.PROGRAMID, OS.STATEMENTTYPE@
CREATE OR REPLACE VIEW QHALSTEAD22 AS SELECT QH21.PROGRAMID, COUNT(QH21.CNT) AS COUNTER FROM QHALSTEAD21 QH21 GROUP BY QH21.PROGRAMID@
CREATE OR REPLACE VIEW QHALSTEAD31 AS SELECT P.PROGRAMID AS PROGRAMID, V.VARNAME AS CNT FROM INNUNIONEDGES IUE INNER JOIN PROGRAMS P ON IUE.PROGID = P.PROGRAMID INNER JOIN OCCURRENCESSTMT OS ON P.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN VARIABLES V ON V.VARID = SR.RESOURCEID INNER JOIN UNIONDESTNODES UDN ON OS.STATEMENTTYPE = UDN.RESOURCETYPE WHERE SR.RESOURCETYPE = 4@
CREATE OR REPLACE VIEW QHALSTEAD32 AS SELECT QH31.PROGRAMID, COUNT(QH31.CNT) AS COUNTER FROM QHALSTEAD31 QH31 GROUP BY QH31.PROGRAMID@
CREATE OR REPLACE VIEW QHALSTEAD41 AS SELECT DISTINCT P.PROGRAMID AS PROGRAMID, V.VARNAME AS CNT FROM INNUNIONEDGES IUE INNER JOIN PROGRAMS P ON IUE.PROGID = P.PROGRAMID INNER JOIN OCCURRENCESSTMT OS ON P.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN VARIABLES V ON V.VARID = SR.RESOURCEID INNER JOIN UNIONDESTNODES UDN ON OS.STATEMENTTYPE = UDN.RESOURCETYPE WHERE SR.RESOURCETYPE = 4@
CREATE OR REPLACE VIEW QHALSTEAD42 AS SELECT QH41.PROGRAMID, COUNT(QH41.CNT) AS COUNTER FROM QHALSTEAD41 QH41 GROUP BY QH41.PROGRAMID@
CREATE OR REPLACE VIEW QBMSFROMSTATEMENTREFERENCE AS SELECT DISTINCT SR.RESOURCEID AS BMSID FROM STATEMENTREFERENCE SR WHERE SR.RESOURCETYPE = 6@
CREATE OR REPLACE VIEW QBMS_UNUSEDRES AS SELECT 'BMS' AS RESOURCETYPE, B.BMSNAME AS RES_NAME, REPEAT(' ', 250) AS DECLARED_IN FROM BMS B LEFT OUTER JOIN QBMSFROMSTATEMENTREFERENCE Q ON B.BMSID = Q.BMSID WHERE B.ISMAPSET = 0 AND Q.BMSID IS NULL@
CREATE OR REPLACE VIEW QVARSFROMPROGRAMS_USEDCHILDREN AS SELECT DISTINCT V.ANCESTOR AS VARID FROM VARIABLES V INNER JOIN STATEMENTREFERENCE SR ON V.VARID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 4 AND V.ILEVEL > 1 AND V.ILEVEL < 77 AND V.ISCOPY = 0@
CREATE OR REPLACE VIEW QVARSFROMPROGRAMS_USEDRECORDS AS SELECT DISTINCT V.VARID FROM VARIABLES V INNER JOIN STATEMENTREFERENCE SR ON V.VARID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 4 AND V.ILEVEL = 1 AND V.ISCOPY = 0@
CREATE OR REPLACE VIEW QVARSFROMPROGRAMS_USEDUNION AS SELECT VARID FROM ( SELECT VARID FROM QVARSFROMPROGRAMS_USEDRECORDS UNION SELECT VARID FROM QVARSFROMPROGRAMS_USEDCHILDREN )SRC@
CREATE OR REPLACE VIEW QVARSFROMPROGRAMS_UNUSEDRES AS SELECT 'Record' AS RESOURCETYPE, V.VARNAME AS RESOURCENAME, P.PROGRAMNAME AS DECLARED_IN FROM PROGRAMS P INNER JOIN VARIABLES V ON P.PROGRAMID = V.PROGIDREFERENCE LEFT OUTER JOIN QVARSFROMPROGRAMS_USEDUNION QVFP ON V.VARID = QVFP.VARID WHERE V.ILEVEL = 1 AND V.ISCOPY = 0 AND QVFP.VARID IS NULL@
CREATE OR REPLACE VIEW QFILESFROMSTATEMENTREFERENCE AS SELECT DISTINCT F.FILEID FROM FILES F INNER JOIN STATEMENTREFERENCE SR ON F.FILEID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 9@
CREATE OR REPLACE VIEW QFILES_UNUSEDRES AS SELECT 'File' AS RESOURCETYPE, F.LOGICALNAME AS RES_NAME, REPEAT(' ', 250) AS DECLARED_IN FROM FILES F LEFT OUTER JOIN QFILESFROMSTATEMENTREFERENCE Q ON F.FILEID = Q.FILEID WHERE Q.FILEID IS NULL@
CREATE OR REPLACE VIEW QSQLTABLESFROMSTATEMENTREFERENCE AS SELECT DISTINCT SR.RESOURCEID AS SQLTABLEID FROM STATEMENTREFERENCE SR WHERE SR.RESOURCETYPE = 1@
CREATE OR REPLACE VIEW QSQLTABLES_UNUSEDRES AS SELECT 'Table' AS RESOURCETYPE, ST.TABLENAME AS RES_NAME, REPEAT(' ', 250) AS DECLARED_IN FROM SQLTABLES ST LEFT OUTER JOIN QSQLTABLESFROMSTATEMENTREFERENCE Q ON ST.SQLTABLEID = Q.SQLTABLEID WHERE Q.SQLTABLEID IS NULL@
CREATE OR REPLACE VIEW QNEXTDECISIONSKEY AS SELECT MAX(DECISIONID) + 1 AS MAXDECISIONID FROM DECISIONS@
CREATE OR REPLACE VIEW QRECORDSTRUCTURE1ANCESTORID AS SELECT V.VARID AS ID, COUNT(*) AS CNT FROM OCCURRENCESSTMT OS INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN VARIABLES V ON V.VARID = SR.RESOURCEID INNER JOIN NPROGS N ON N.PROGRAMID = V.VARID WHERE SR.RESOURCETYPE = 4 AND V.ILEVEL = 1 GROUP BY V.VARID@
CREATE OR REPLACE VIEW QRECORDSTRUCTURE1VARID AS SELECT V.ANCESTOR AS ID, COUNT(*) AS CNT FROM OCCURRENCESSTMT OS INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN VARIABLES V ON V.VARID = SR.RESOURCEID INNER JOIN NPROGS N ON N.PROGRAMID = V.ANCESTOR WHERE SR.RESOURCETYPE = 4 AND V.ILEVEL <> 1 GROUP BY V.ANCESTOR@
CREATE OR REPLACE VIEW QRECORDSTRUCTURE1UNION AS SELECT * FROM QRECORDSTRUCTURE1ANCESTORID UNION SELECT * FROM QRECORDSTRUCTURE1VARID@
CREATE OR REPLACE VIEW RECORDSTRUCTREPORT1 AS SELECT ID, SUM(CNT) AS RECSUMMARY FROM QRECORDSTRUCTURE1UNION GROUP BY ID@
CREATE OR REPLACE VIEW REPORTS_UNUSEDRES AS SELECT RESOURCETYPE, RESOURCENAME, DECLARED_IN FROM ( SELECT RESOURCETYPE, RESOURCENAME, DECLARED_IN FROM QVARSFROMPROGRAMS_UNUSEDRES UNION SELECT RESOURCETYPE, RES_NAME AS RESOURCENAME, DECLARED_IN FROM QBMS_UNUSEDRES UNION SELECT RESOURCETYPE, RES_NAME AS RESOURCENAME, DECLARED_IN FROM QFILES_UNUSEDRES UNION SELECT RESOURCETYPE, RES_NAME AS RESOURCENAME, DECLARED_IN FROM QSQLTABLES_UNUSEDRES ) SRC @
CREATE OR REPLACE VIEW UCMDB_GETASSOCIATEDJCLJOBS AS SELECT COM.COMPONENTID, JJ.JOBID, COM.RESOURCEPATH FROM JCLJOB JJ INNER JOIN JCLPOSITION JP ON JJ.POSITIONID = JP.POSITIONID INNER JOIN COMPONENTS COM ON JP.RESOURCEFILEPATH = COM.RESOURCEPATH WHERE COM.RESOURCETYPE = 22 AND JP.STARTROW = 1@
CREATE OR REPLACE VIEW UCMDB_GETASSOCIATEDPROGRAMS AS SELECT COM.COMPONENTID, PRG.PROGRAMID, COM.RESOURCEPATH FROM OCCURRENCES O INNER JOIN PROGRAMS PRG ON O.OCCURID = PRG.OCCURID INNER JOIN PATHS PTH ON O.PATHID = PTH.PATHID INNER JOIN COMPONENTS COM ON PTH.PATHSTR = COM.RESOURCEPATH WHERE COM.RESOURCETYPE = 5@
CREATE OR REPLACE VIEW VME_AM_SOURCEPOSITION_V AS SELECT DSI.ID AS SOURCEINFOID, PTH.PATHSTR, DSI.STARTROW, DSI.STARTCOL, DSI.ENDROW, DSI.ENDCOL FROM DDCLSOURCEINFO DSI INNER JOIN PROGRAMS PRG ON DSI.PROGRAMID = PRG.PROGRAMID INNER JOIN OCCURRENCES O ON PRG.OCCURID = O.OCCURID INNER JOIN PATHS PTH ON O.PATHID = PTH.PATHID@
CREATE OR REPLACE VIEW GETTSPSBFULL AS SELECT PTH.PATHSTR, PSB.ETIMESTAMP FROM PSBINFO PSB INNER JOIN OCCURRENCES OCC ON PSB.PSBID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 217@
CREATE OR REPLACE VIEW GETTSAPIDEPENDENCYFULL AS SELECT DISTINCT PTH.PATHSTR, APIDEP.ETIMESTAMP FROM APIDEPENDENCYDEF APIDEP INNER JOIN (OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID) ON APIDEP.OCCURID = OCC.OCCURID WHERE (OCC.RESOURCETYPE=218)@
CREATE OR REPLACE VIEW GETTS_IMSDBFULL AS SELECT PTH.PATHSTR, TMSTMP.ETIMESTAMP FROM IMSDBINFO IMSDB INNER JOIN OCCURRENCES OCC ON IMSDB.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID INNER JOIN ARTEFACTSTIMESTAMPS TMSTMP ON IMSDB.DBID = TMSTMP.RESID WHERE(TMSTMP.RESTYPE = 18) AND (OCC.RESOURCETYPE = 18)@
CREATE OR REPLACE VIEW GETTS_CTRLM AS SELECT PTH.PATHSTR, CTMXML.ETIMESTAMP FROM CTM_XMLDATASOURCES CTMXML INNER JOIN OCCURRENCES OCC ON CTMXML.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE=224@
CREATE OR REPLACE VIEW GETTS_CSDCONFIGFILESFULL AS SELECT PTH.PATHSTR, MFCL.ETIMESTAMP FROM MFCICSLIST MFCL INNER JOIN OCCURRENCES OCC ON MFCL.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE=216@
CREATE OR REPLACE VIEW COMP_PROGRAMSALIASES AS SELECT PROG.PROGRAMID, PROGALIAS.ALIASNAME, PROG.PROGRAMTYPEID FROM PROGRAMS PROG INNER JOIN PROGRAMALIASES PROGALIAS ON PROG.PROGRAMID = PROGALIAS.PROGRAMID@
CREATE OR REPLACE FUNCTION GETOBJECTDESCRIPTION ( P_TYPE INTEGER ) RETURNS TABLE (OBJECTID VARCHAR(250) , DESCRIPTION VARCHAR(250) ) LANGUAGE SQL READS SQL DATA NO EXTERNAL ACTION DETERMINISTIC BEGIN ATOMIC RETURN SELECT OBJECTID, DESCRIPTION FROM SMARTOBJECTDESCRIPTION WHERE OBJECTTYPE = P_TYPE ; END @
CREATE OR REPLACE FUNCTION FCA7_GRAPH_RELATIONS_INTERNAL ( P_ROOTID INTEGER ) RETURNS TABLE ( JOBID INTEGER, TRIGGEREDBY_JOBID INTEGER, INSCHID INTEGER, OUTSCHID INTEGER, INTRIGGEREDBY_SCHID INTEGER, OUTTRIGGEREDBY_SCHID INTEGER, TYPEID INTEGER, DEPENDENCYTYPE VARCHAR(260), VRSN VARCHAR(260), LEADTM VARCHAR(260), RELATIONTYPE INTEGER, DSN VARCHAR(260), QTM VARCHAR(260), DOTM VARCHAR(260), SUBMTM VARCHAR(260), ROOTID INTEGER ) LANGUAGE SQL BEGIN ATOMIC RETURN WITH CTE0 (MAX_JOBID) AS ( SELECT MAX(JOBID) AS MAX_JOBID FROM CA7_JOBS ), CTE1 (ID, DSNX) AS ( SELECT ROW_NUMBER() OVER(ORDER BY DSNX) + (SELECT MAX_JOBID FROM CTE0) AS ID, DSNX FROM ( SELECT DISTINCT DSN AS DSNX FROM CA7_JOBSTRIGGEREDBYDATASETS ) SRC ), CTE2 (JOBID, TRIGGEREDBY_JOBID, INSCHID, OUTSCHID, INTRIGGEREDBY_SCHID, OUTTRIGGEREDBY_SCHID, TYPEID, DEPENDENCYTYPE, VRSN, LEADTM, RELATIONTYPE, DSN, QTM, DOTM, SUBMTM, ROOTID) AS ( SELECT JTJ1.JOBID, JTJ1.TRIGGEREDBY_JOBID, JTJ1.INSCHID, JTJ1.OUTSCHID, JTJ2.INSCHID AS INTRIGGEREDBY_SCHID, JTJ2.OUTSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, P_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ1 INNER JOIN CA7_JOBS CJ ON JTJ1.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYJOBS JTJ2 ON JTJ1.TRIGGEREDBY_JOBID = JTJ2.JOBID AND (JTJ2.OUTSCHID = JTJ1.INSCHID OR JTJ1.INSCHID = 0) WHERE CL.ROOTID = P_ROOTID UNION SELECT JTJ.JOBID, JTJ.TRIGGEREDBY_JOBID, JTJ.INSCHID, JTJ.OUTSCHID, CSPJ.SCHID AS INTRIGGEREDBY_SCHID, CSPJ.SCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, P_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ INNER JOIN CA7_JOBS CJ ON JTJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_SCHEDULESPERJOB CSPJ ON JTJ.TRIGGEREDBY_JOBID = CSPJ.JOBID AND (JTJ.INSCHID = CSPJ.SCHID OR JTJ.INSCHID = 0) WHERE CL.ROOTID = P_ROOTID UNION SELECT JTJ.JOBID, JTJ.TRIGGEREDBY_JOBID, JTJ.INSCHID, JTJ.OUTSCHID, JTJ.INSCHID AS INTRIGGEREDBY_SCHID, JTJ.INSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, P_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ INNER JOIN CA7_JOBS CJ ON JTJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID WHERE CL.ROOTID = P_ROOTID AND NOT EXISTS ( SELECT T.JOBID FROM CA7_JOBSTRIGGEREDBYJOBS T INNER JOIN CA7_JOBS CJ1 ON JTJ.JOBID = CJ1.JOBID INNER JOIN CA7_LIBRARIES CL1 ON CJ1.LIBID = CL1.LIBID WHERE CL.ROOTID = P_ROOTID AND T.JOBID = JTJ.TRIGGEREDBY_JOBID AND T.INSCHID <> 0 ) UNION SELECT CGJV.JOBID, CGJV.DEPENDENTON_JOBID AS TRIGGEREDBY_JOBID, CGJV.INSCHID, CGJV.OUTSCHID, CGJV.INDEPENDENTON_SCHID AS INTRIGGEREDBY_SCHID, CGJV.OUTDEPENDENTON_SCHID AS OUTTRIGGEREDBY_SCHID, CGJV.TYPEID, CGJV.DEPENDENCYTYPE, CGJV.VRSN, CGJV.LEADTM, CGJV.RELATIONTYPE, CGJV.DSN, CGJV.QTM, CGJV.DOTM, CGJV.SUBMTM, P_ROOTID AS ROOTID FROM CA7_GRAPH_JOBSVSJOBSDEPENDENCIES_V CGJV WHERE CGJV.ROOTID = P_ROOTID UNION SELECT JTJ.JOBID, JTJ.TRIGGEREDBY_JOBID, JTJ.INSCHID, JTJ.OUTSCHID, CJTD.INSCHID AS INTRIGGEREDBY_SCHID, CJTD.OUTSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, P_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ INNER JOIN CA7_JOBS CJ ON JTJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYDATASETS CJTD ON JTJ.TRIGGEREDBY_JOBID = CJTD.JOBID AND (CJTD.OUTSCHID = JTJ.INSCHID OR JTJ.INSCHID = 0) WHERE CL.ROOTID = P_ROOTID UNION SELECT CJTD.JOBID, G.ID AS TRIGGEREDBY_JOBID, CJTD.INSCHID, CJTD.OUTSCHID, CJTD.INSCHID AS INTRIGGEREDBY_SCHID, CJTD.INSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, CJTD.LEADTM, 3 AS RELATIONTYPE, CJTD.DSN, CJTD.QTM, CJTD.DOTM, CJTD.SUBMTM, P_ROOTID AS ROOTID FROM CA7_LIBRARIES CL INNER JOIN CA7_JOBS CJ ON CL.LIBID = CJ.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYDATASETS CJTD ON CJ.JOBID = CJTD.JOBID AND CJTD.INSCHID <> 0 INNER JOIN CTE1 G ON G.DSNX = CJTD.DSN WHERE CL.ROOTID = P_ROOTID UNION SELECT CJTD.JOBID, G.ID AS TRIGGEREDBY_JOBID, CJTD.INSCHID, CJTD.OUTSCHID, CJTD.OUTSCHID AS INTRIGGEREDBY_SCHID, CJTD.OUTSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, CJTD.LEADTM, 3 AS RELATIONTYPE, CJTD.DSN, CJTD.QTM, CJTD.DOTM, CJTD.SUBMTM, P_ROOTID AS ROOTID FROM CA7_LIBRARIES CL INNER JOIN CA7_JOBS CJ ON CL.LIBID = CJ.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYDATASETS CJTD ON CJ.JOBID = CJTD.JOBID AND CJTD.INSCHID = 0 INNER JOIN CTE1 G ON G.DSNX = CJTD.DSN WHERE CL.ROOTID = P_ROOTID ) SELECT * FROM CTE2 WHERE 1 = CASE WHEN EXISTS(SELECT MAX_JOBID FROM CTE0 WHERE MAX_JOBID IS NOT NULL) THEN 1 ELSE 0 END ; END @
GRANT SELECT ON SYSCAT.ROUTINES TO PUBLIC @
DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMPTABLE (MVSCONN VARCHAR(100), LIBNAME VARCHAR(100), MEMBERNAME VARCHAR(100), PORT INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED @
DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMP_UNRESOLVEDVARS (STMTOCCURID INTEGER, VARID INTEGER, PROGID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED@
DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMP_UNRESOLVEDVARS2 (STMTOCCURID INTEGER, VARID INTEGER, PROGID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED@
CREATE OR REPLACE PROCEDURE AA_ADABAS_VIEWS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT ST.STATEMENTTYPE, CAST(AF.FILENUMBER AS VARCHAR(10)) AS FILENUMBER, ST.DESCRIPTION, PGM.PROGRAMNAME, OS.STARTROW, OS.STARTCOL, OS.ENDROW, OS.ENDCOL, PTH.PATHSTR, OS.OCCURID, AW.VIEWNAME FROM STATEMENTREFERENCE AS STATEMENTREFERENCE_1 INNER JOIN STATEMENTREFERENCE SR ON STATEMENTREFERENCE_1.OCCURID = SR.OCCURID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM.PROGRAMID INNER JOIN ADABASFILES AF ON SR.RESOURCEID = AF.FILEID INNER JOIN PATHS PTH ON OS.PATHID = PTH.PATHID INNER JOIN STATEMENTS ST ON OS.STATEMENTTYPE = ST.STATEMENTTYPE INNER JOIN ADABASVIEW AW ON STATEMENTREFERENCE_1.RESOURCEID = AW.VIEWID WHERE SR.RESOURCETYPE = 56 AND SR.STATEMENTTYPE IN (270, 271, 272, 273, 262, 263, 281, 261, 268, 319, 347, 325, 322, 368, 372, 309) AND STATEMENTREFERENCE_1.RESOURCETYPE = 62 ORDER BY AF.FILENUMBER, ST.DESCRIPTION, PGM.PROGRAMID, OS.STARTROW, OS.STARTCOL; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE CA7_GRAPH_RELATIONS_INTERNAL ( P_ROOTID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_ROOTID INTEGER; DECLARE V_SEED INTEGER; DECLARE GLOBAL TEMPORARY TABLE SESSION.GOGU ( ID INTEGER, DSNX VARCHAR(255) )WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; DECLARE GLOBAL TEMPORARY TABLE SESSION.X ( JOBID INTEGER, TRIGGEREDBY_JOBID INTEGER, INSCHID INTEGER, OUTSCHID INTEGER, INTRIGGEREDBY_SCHID INTEGER, OUTTRIGGEREDBY_SCHID INTEGER, TYPEID INTEGER, DEPENDENCYTYPE VARCHAR(260), VRSN VARCHAR(260), LEADTM VARCHAR(260), RELATIONTYPE INTEGER, DSN VARCHAR(260), QTM VARCHAR(260), DOTM VARCHAR(260), SUBMTM VARCHAR(260), ROOTID INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; SET V_ROOTID = P_ROOTID; SET V_SEED = (SELECT MAX(CJ.JOBID) FROM CA7_JOBS CJ); IF (V_SEED IS NOT NULL) THEN INSERT INTO SESSION.GOGU(ID, DSNX) SELECT ROW_NUMBER() OVER(ORDER BY DSNX) + V_SEED AS ID, DSNX FROM ( SELECT DISTINCT DSN AS DSNX FROM CA7_JOBSTRIGGEREDBYDATASETS ) SRC; INSERT INTO SESSION.X (JOBID, TRIGGEREDBY_JOBID, INSCHID, OUTSCHID, INTRIGGEREDBY_SCHID, OUTTRIGGEREDBY_SCHID, TYPEID, DEPENDENCYTYPE, VRSN, LEADTM, RELATIONTYPE, DSN, QTM, DOTM, SUBMTM, ROOTID) SELECT JOBID, TRIGGEREDBY_JOBID, INSCHID, OUTSCHID, INTRIGGEREDBY_SCHID, OUTTRIGGEREDBY_SCHID, TYPEID, DEPENDENCYTYPE, VRSN, LEADTM, RELATIONTYPE, DSN, QTM, DOTM, SUBMTM, ROOTID FROM ( SELECT CJTD.JOBID, G.ID AS TRIGGEREDBY_JOBID, CJTD.INSCHID, CJTD.OUTSCHID, CJTD.INSCHID AS INTRIGGEREDBY_SCHID, CJTD.INSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, CJTD.LEADTM, 3 AS RELATIONTYPE, CJTD.DSN, CJTD.QTM, CJTD.DOTM, CJTD.SUBMTM, V_ROOTID AS ROOTID FROM CA7_LIBRARIES CL INNER JOIN CA7_JOBS CJ ON CL.LIBID = CJ.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYDATASETS CJTD ON CJ.JOBID = CJTD.JOBID AND CJTD.INSCHID <> 0 INNER JOIN SESSION.GOGU G ON G.DSNX = CJTD.DSN WHERE CL.ROOTID = V_ROOTID UNION SELECT CJTD.JOBID, G.ID AS TRIGGEREDBY_JOBID, CJTD.INSCHID, CJTD.OUTSCHID, CJTD.OUTSCHID AS INTRIGGEREDBY_SCHID, CJTD.OUTSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, CJTD.LEADTM, 3 AS RELATIONTYPE, CJTD.DSN, CJTD.QTM, CJTD.DOTM, CJTD.SUBMTM, V_ROOTID AS ROOTID FROM CA7_LIBRARIES CL INNER JOIN CA7_JOBS CJ ON CL.LIBID = CJ.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYDATASETS CJTD ON CJ.JOBID = CJTD.JOBID AND CJTD.INSCHID = 0 INNER JOIN SESSION.GOGU G ON G.DSNX = CJTD.DSN WHERE CL.ROOTID = V_ROOTID UNION SELECT JTJ1.JOBID, JTJ1.TRIGGEREDBY_JOBID, JTJ1.INSCHID, JTJ1.OUTSCHID, JTJ2.INSCHID AS INTRIGGEREDBY_SCHID, JTJ2.OUTSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, V_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ1 INNER JOIN CA7_JOBS CJ ON JTJ1.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYJOBS JTJ2 ON JTJ1.TRIGGEREDBY_JOBID = JTJ2.JOBID AND (JTJ2.OUTSCHID = JTJ1.INSCHID OR JTJ1.INSCHID = 0) WHERE CL.ROOTID = V_ROOTID UNION SELECT JTJ.JOBID, JTJ.TRIGGEREDBY_JOBID, JTJ.INSCHID, JTJ.OUTSCHID, CSPJ.SCHID AS INTRIGGEREDBY_SCHID, CSPJ.SCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, V_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ INNER JOIN CA7_JOBS CJ ON JTJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_SCHEDULESPERJOB CSPJ ON JTJ.TRIGGEREDBY_JOBID = CSPJ.JOBID AND (JTJ.INSCHID = CSPJ.SCHID OR JTJ.INSCHID = 0) WHERE CL.ROOTID = V_ROOTID UNION SELECT JTJ.JOBID, JTJ.TRIGGEREDBY_JOBID, JTJ.INSCHID, JTJ.OUTSCHID, JTJ.INSCHID AS INTRIGGEREDBY_SCHID, JTJ.INSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, V_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ INNER JOIN CA7_JOBS CJ ON JTJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID WHERE CL.ROOTID = V_ROOTID AND NOT EXISTS ( SELECT T.JOBID FROM CA7_JOBSTRIGGEREDBYJOBS T INNER JOIN CA7_JOBS CJ1 ON JTJ.JOBID = CJ1.JOBID INNER JOIN CA7_LIBRARIES CL1 ON CJ1.LIBID = CL1.LIBID WHERE CL.ROOTID = V_ROOTID AND T.JOBID = JTJ.TRIGGEREDBY_JOBID AND T.INSCHID <> 0 ) UNION SELECT CGJV.JOBID, CGJV.DEPENDENTON_JOBID AS TRIGGEREDBY_JOBID, CGJV.INSCHID, CGJV.OUTSCHID, CGJV.INDEPENDENTON_SCHID AS INTRIGGEREDBY_SCHID, CGJV.OUTDEPENDENTON_SCHID AS OUTTRIGGEREDBY_SCHID, CGJV.TYPEID, CGJV.DEPENDENCYTYPE, CGJV.VRSN, CGJV.LEADTM, CGJV.RELATIONTYPE, CGJV.DSN, CGJV.QTM, CGJV.DOTM, CGJV.SUBMTM, V_ROOTID AS ROOTID FROM CA7_GRAPH_JOBSVSJOBSDEPENDENCIES_V CGJV WHERE CGJV.ROOTID = V_ROOTID UNION SELECT JTJ.JOBID, JTJ.TRIGGEREDBY_JOBID, JTJ.INSCHID, JTJ.OUTSCHID, CJTD.INSCHID AS INTRIGGEREDBY_SCHID, CJTD.OUTSCHID AS OUTTRIGGEREDBY_SCHID, 0 AS TYPEID, '' AS DEPENDENCYTYPE, '' AS VRSN, '' AS LEADTM, 1 AS RELATIONTYPE, '' AS DSN, '' AS QTM, '' AS DOTM, '' AS SUBMTM, V_ROOTID AS ROOTID FROM CA7_JOBSTRIGGEREDBYJOBS JTJ INNER JOIN CA7_JOBS CJ ON JTJ.JOBID = CJ.JOBID INNER JOIN CA7_LIBRARIES CL ON CJ.LIBID = CL.LIBID INNER JOIN CA7_JOBSTRIGGEREDBYDATASETS CJTD ON JTJ.TRIGGEREDBY_JOBID = CJTD.JOBID AND (CJTD.OUTSCHID = JTJ.INSCHID OR JTJ.INSCHID = 0) WHERE CL.ROOTID = V_ROOTID )SRC; BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM SESSION.X; OPEN CRS; END; END IF; END @
CREATE OR REPLACE PROCEDURE CLEANIDMSRECORDSTRUCTURE( ) LANGUAGE SQL BEGIN DELETE FROM IDMSRECORDSTRUCTURE WHERE PARENTID NOT IN ( SELECT ID FROM IDMSRECORDSTRUCTURE ) AND PARENTID <> -1; END @
CREATE OR REPLACE PROCEDURE COMP_ADABASDATABASES() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT AD.ADABASDBID, AD.DBNUMBER, AD.DBNAME, AD.OCCURID FROM ADABASDATABASES AD; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_ADABASFILES() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT AF.FILEID, CAST(AF.FILENUMBER AS VARCHAR(10)) AS FILENUMBER, AF.OCCURID, AD.DBNUMBER, AF.ADABASDBID FROM ADABASDATABASES AD INNER JOIN ADABASFILES AF ON AD.ADABASDBID = AF.ADABASDBID; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_CURSORS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT C.CURSORID, C.CURSORNAME FROM CURSORS C; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_MAXIDMSRECORDSTRUCTURE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MAX(ID) AS MAXID FROM IDMSRECORDSTRUCTURE; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_MAXIDMSSETMEMBERS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MAX(ID) AS MAXID FROM IDMSSETMEMBERS; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_MAXSMARTOBJECTS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MAX(ID) AS MAXID FROM SMARTOBJECTDESCRIPTION; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_MAXSMARTRESOURCEFIELDS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MAX(ID) AS MAXRESOURCEID FROM SMARTRESOURCEFIELDS; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_MAXSMARTRESOURCES() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MAX(ID) AS MAXRESOURCEID FROM SMARTRESOURCES; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_NATURALDDM() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT N.DDM_ID, N.DDMNAME, N.REFERENCERESOURCEID, N.RESOURCETYPE, N.OCCURID, N.ETIMESTAMP FROM NATURALDDM N; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE COMP_RULES ( IN P_X VARCHAR(256), IN P_Y VARCHAR(256), IN P_Z VARCHAR(256) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_X VARCHAR(256); DECLARE V_Y VARCHAR(256); DECLARE V_Z VARCHAR(256); DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT DISTINCT R.TYPE, R.INPUTPATTERN, R.OUTPUTPATTERN FROM DECISIONS D INNER JOIN DECISIONPROJECT DP ON D.DECISIONID = DP.DECISIONID INNER JOIN RULES R ON D.DECISIONID = R.DECISIONID WHERE DP.PROJECTNAME = V_X UNION SELECT DISTINCT R.TYPE, R.INPUTPATTERN, R.OUTPUTPATTERN FROM DECISIONS D INNER JOIN RULES R ON D.DECISIONID = R.DECISIONID INNER JOIN DECISIONFOLDER DF ON D.DECISIONID = DF.DECISIONID WHERE DF.FOLDERNAME = V_Y UNION SELECT DISTINCT R.TYPE, R.INPUTPATTERN, R.OUTPUTPATTERN FROM DECISIONS D INNER JOIN RULES R ON D.DECISIONID = R.DECISIONID INNER JOIN DECISIONFILES DF ON D.DECISIONID = DF.DECISIONID WHERE DF.FILENAME = V_Z )SRC; SET V_X = P_X; SET V_Y = P_Y; SET V_Z = P_Z; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE CREATESEQUENCE ( IN P_NAME VARGRAPHIC(255), IN P_SEED INTEGER, IN P_INCREMENT INTEGER ) CALLED ON NULL INPUT PARAMETER CCSID UNICODE DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE SQLSTATE CHAR(5) DEFAULT '00000'; DECLARE SQLCODE INT DEFAULT 0; DECLARE V_NAME VARGRAPHIC(255); DECLARE V_SEED, V_INCREMENT, V_CURRVAL INTEGER; DECLARE SEQUENCE_DUPLICATE CONDITION FOR SQLSTATE '23001'; DECLARE EXIT HANDLER FOR SQLEXCEPTION RESIGNAL; SET V_NAME = P_NAME; SET V_SEED = COALESCE(P_SEED, 0); SET V_INCREMENT = COALESCE(P_INCREMENT, 1); SET V_CURRVAL = V_SEED; IF ( EXISTS ( SELECT 1 FROM SEQUENCES WHERE NAME = V_NAME ) ) THEN SIGNAL SEQUENCE_DUPLICATE SET MESSAGE_TEXT = 'Sequence already exists.' ; ELSE INSERT INTO SEQUENCES (NAME, SEED, INCREMENT, CURRVAL) VALUES (V_NAME, V_SEED, V_INCREMENT, V_CURRVAL ); END IF; END @
CREATE OR REPLACE PROCEDURE CUSTOM2_SETASMTYPE_FORPROGSWITHOUTSOURCE( ) DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN UPDATE PROGRAMS SET PROGRAMTYPEID = 8 WHERE PROGRAMID IN ( SELECT P.PROGRAMID FROM TEMPTBL T INNER JOIN PROGRAMS P ON T.TYPE = P.PROGRAMNAME WHERE P.OCCURID = 0 ); END @
