CREATE OR REPLACE PROCEDURE ENDEVORGETMODIFIEDMEMBERS( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT MPI.MVSCONNECTIONNAME, ML.LIBRARYNAME, MM.MEMBERNAME, MPI.IPADDRESS, TT.PORT, MM.RETREIVEDATE, MM.RETRIEVEDVERSION, MM.RETRIEVEDMODIFICATIONNUMBER, MM.MEMBERID FROM MFLPARINFO MPI INNER JOIN SESSION.TEMPTABLE TT ON MPI.MVSCONNECTIONNAME = TT.MVSCONN INNER JOIN MFLIBRARIES ML ON TT.LIBNAME = ML.LIBRARYNAME AND MPI.LPARID = ML.LPARCONNID INNER JOIN MFMEMBERS MM ON MM.MEMBERNAME = TT.MEMBERNAME AND ML.LIBRARYID = MM.LIBRARYID WHERE ( MM.RETRIEVEDVERSION != MM.VERSION OR MM.RETRIEVEDMODIFICATIONNUMBER <> MM.MODIFICATIONNUMBER ) ORDER BY MM.MEMBERID; OPEN CRS; END; END @
CREATE OR REPLACE PROCEDURE FILESVSPROGREPORT() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT F.LOGICALNAME AS NAME, PGM.PROGRAMNAME AS S_NAME FROM STATEMENTREFERENCE SR INNER JOIN FILES F ON SR.RESOURCEID = F.FILEID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM.PROGRAMID INNER JOIN INNUNIONEDGES IUE ON F.LOGICALNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 9 AND PGM.OCCURID <> 0 ORDER BY F.LOGICALNAME, PGM.PROGRAMNAME; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETDDMMAINFRMLIBRARIESPROC( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFLB.LIBID, MFLB.LIBRARYNAME, MFPI.MVSCONNECTIONNAME, MFPI.IPADDRESS, 6 AS LIBTYPE FROM(MFLPARINFO MFPI LEFT OUTER JOIN INNUNIONEDGES IUE ON MFPI.LPARID = IUE.EDGETYPE) INNER JOIN MFNATURALLIBRARIES MFLB ON MFPI.LPARID = MFLB.LPARID INNER JOIN MFNATURALMEMBERS MFNM ON MFLB.LIBID = MFNM.NATLIBID WHERE MFPI.VALIDENTRY = 1 AND MFNM.MFMEMBERTYPE = 23; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETJCLPROCPATHS( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT JPOS.RESOURCEFILEPATH FROM JCLPOSITION JPOS INNER JOIN JCLPROC JPROC ON JPOS.POSITIONID = JPROC.POSITIONID WHERE JPOS.RESOURCETYPE = 25; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETLIBRARIANMAINFRAMELIBRARIES( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFLIB.LIBRARYID, MFLIB.LIBRARYNAME, MFPI.MVSCONNECTIONNAME, MFPI.IPADDRESS, MFLIB.LIBTYPE FROM MFLIBRARIES MFLIB INNER JOIN MFLPARINFO MFPI ON MFLIB.LPARCONNID = MFPI.LPARID INNER JOIN MFLIBRARIANMEMBERS MFLM ON MFLIB.LIBRARYID = MFLM.LIBID LEFT OUTER JOIN INNUNIONEDGES IUE ON MFPI.LPARID = IUE.EDGETYPE WHERE MFPI.VALIDENTRY = 1; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETLIBRARIANMAINFRAMEMEMBERS( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFLM.LIBRARIANMEMBERID, MFLM.LIBRARIANMEMBERNAME, MFLIB.LIBRARYID, MFLM.LANGUAGE FROM MFLIBRARIES MFLIB INNER JOIN MFLIBRARIANMEMBERS MFLM ON MFLIB.LIBRARYID = MFLM.LIBID INNER JOIN INNUNIONEDGES IUE ON MFLIB.LIBRARYID = IUE.EDGETYPE; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETMAINFRMMEMBERSPROC( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MM.MEMBERID, MM.MEMBERNAME, ML.LIBRARYID, MM.MEMBERTYPE FROM MFLIBRARIES ML INNER JOIN INNUNIONEDGES IUE ON ML.LIBRARYID = IUE.EDGETYPE INNER JOIN MFMEMBERS MM ON ML.LIBRARYID = MM.LIBRARYID; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETMAINFRMLIBRARIESPROC( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFLIB.LIBRARYID, MFLIB.LIBRARYNAME, MFPI.MVSCONNECTIONNAME, MFPI.IPADDRESS, MFLIB.LIBTYPE FROM MFLPARINFO MFPI LEFT OUTER JOIN INNUNIONEDGES IUE ON MFPI.LPARID = IUE.EDGETYPE INNER JOIN MFLIBRARIES MFLIB ON MFPI.LPARID = MFLIB.LPARCONNID INNER JOIN MFMEMBERS MM ON MFLIB.LIBRARYID = MM.LIBRARYID WHERE MFPI.VALIDENTRY = 1; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETNATURALMAINFRMMEMBERSPROC( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFNM.NATMEMBERID, MFNM.NATMEMBERNAME, MFLB.LIBID, MFNM.MEMBERTYPE FROM MFNATURALMEMBERS MFNM INNER JOIN MFNATURALLIBRARIES MFLB ON MFNM.NATLIBID = MFLB.LIBID INNER JOIN INNUNIONEDGES IUE ON MFLB.LIBID = IUE.EDGETYPE WHERE MFNM.S_C LIKE 'S%' AND MFNM.MFMEMBERTYPE = 3; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETNATURALDDMPATHS( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT PTH.PATHSTR FROM PATHS PTH INNER JOIN OCCURRENCES OCC ON PTH.PATHID = OCC.PATHID INNER JOIN NATURALDDM ND ON OCC.OCCURID = ND.OCCURID WHERE OCC.RESOURCETYPE = 192; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETNATURALMAINFRMLIBRARIESPROC( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFLB.LIBID, MFLB.LIBRARYNAME, MFPI.MVSCONNECTIONNAME, MFPI.IPADDRESS, 3 AS LIBTYPE FROM MFLPARINFO MFPI LEFT OUTER JOIN INNUNIONEDGES IUE ON MFPI.LPARID = IUE.EDGETYPE INNER JOIN MFNATURALLIBRARIES MFLB ON MFPI.LPARID = MFLB.LPARID INNER JOIN MFNATURALMEMBERS MFNM ON MFLB.LIBID = MFNM.NATLIBID WHERE MFPI.VALIDENTRY = 1 AND MFNM.MFMEMBERTYPE = 3; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETPROGSPATHSFROMNPROGS( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PGM.PROGRAMID, PTH.PATHSTR, OCC.STARTROW, OCC.ENDROW, OCC.STARTCOL, OCC.ENDCOL FROM(OCCURRENCES OCC LEFT OUTER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID) RIGHT JOIN (NPROGS NPRG INNER JOIN PROGRAMS PGM ON NPRG.PROGRAMID = PGM.PROGRAMID) ON OCC.OCCURID = PGM.OCCURID; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETBUILDFILETIMESTAMP ( IN P_FPATH VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_FPATH VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT MAX(BTS.ETIMESTAMP) AS MAXTIMESTAMP FROM BUILDTIMESTAMP BTS WHERE BTS.FILEPATH = V_FPATH GROUP BY BTS.FILEPATH; SET V_FPATH = P_FPATH; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETDATAAREAPATH ( IN P_FILEPATHPARAM VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_FILEPATHPARAM VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT DAC.DATAAREAPATH FROM DATAAREACORESP DAC WHERE DAC.DAPATH = V_FILEPATHPARAM; SET V_FILEPATHPARAM = P_FILEPATHPARAM; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETDATAAREATS ( IN P_FILEPATHPARAM VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_FILEPATHPARAM VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT DAC.ETIMESTAMP FROM DATAAREACORESP DAC WHERE DAC.DATAAREAPATH = V_FILEPATHPARAM; SET V_FILEPATHPARAM = P_FILEPATHPARAM; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETJCLJOBFILESPERJCLPROCFILE ( IN P_RESOURCEFILEPATHPARAM VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_RESOURCEFILEPATHPARAM VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT JCLPOSITION_1.RESOURCEFILEPATH FROM JCLPOSITION AS JCLPOSITION_1 INNER JOIN JCLJOB JJ ON JCLPOSITION_1.POSITIONID = JJ.POSITIONID INNER JOIN JCLSTEP JS ON JJ.JOBID = JS.JOBID INNER JOIN JCLPROC JPROC ON JPROC.PROCID = JS.CALLEDPROCID INNER JOIN JCLPOSITION JPOS ON JPOS.POSITIONID = JPROC.POSITIONID WHERE JPOS.RESOURCEFILEPATH = V_RESOURCEFILEPATHPARAM AND JPOS.RESOURCETYPE = 25 AND JCLPOSITION_1.RESOURCETYPE = 22; SET V_RESOURCEFILEPATHPARAM = P_RESOURCEFILEPATHPARAM; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETJCLJOBIDSBYPATH ( IN P_JCLJOBPATH VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_JCLJOBPATH VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT JJ.JOBID FROM JCLJOB JJ INNER JOIN JCLPOSITION JPOS ON JJ.POSITIONID = JPOS.POSITIONID WHERE JPOS.RESOURCEFILEPATH = V_JCLJOBPATH; SET V_JCLJOBPATH = P_JCLJOBPATH; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETPRINTERFILEIDBYNAME ( IN P_FILENAME VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_FILENAME VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT PFD.ID FROM PRINTERFILEDDS PFD WHERE PFD.PRINTERFILENAME = V_FILENAME; SET V_FILENAME = P_FILENAME; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETPROGFILESPERCOPYFILE ( IN P_PATHSTRPARAM VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_PATHSTRPARAM VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT PATHS_1.PATHSTR FROM PATHS AS PATHS_1 INNER JOIN OCCURRENCESSTMT OS ON PATHS_1.PATHID = OS.PATHID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN RESOURCES RES ON RES.RESOURCEID = SR.RESOURCEID INNER JOIN OCCURRENCES OCC ON RES.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON PTH.PATHID = OCC.PATHID WHERE PTH.PATHSTR = V_PATHSTRPARAM AND OCC.RESOURCETYPE IN (13, 67, 60, 57, 94, 99) AND SR.RESOURCETYPE IN (13, 67, 60, 57, 94, 99) AND SR.STATEMENTTYPE IN (44, 210, 329, 413, 650, 1669) AND OS.STATEMENTTYPE IN (44, 210, 329, 413, 650, 1669); SET V_PATHSTRPARAM = P_PATHSTRPARAM; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETPROGFILESPERNATURALDDMFILE ( IN P_PATHSTRPARAM VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_PATHSTRPARAM VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT PTH.PATHSTR AS PROGRAMPATH FROM PATHS PTH INNER JOIN OCCURRENCESSTMT OS ON PTH.PATHID = OS.PATHID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN NATURALDDM ND ON SR.RESOURCEID = ND.DDM_ID INNER JOIN OCCURRENCES OCC ON ND.OCCURID = OCC.OCCURID INNER JOIN PATHS AS PATHS_1 ON OCC.PATHID = PATHS_1.PATHID WHERE PATHS_1.PATHSTR = V_PATHSTRPARAM AND SR.RESOURCETYPE = '192'; SET V_PATHSTRPARAM = P_PATHSTRPARAM; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETSCREENIDBYNAME ( IN P_SCRNAME VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_SCRNAME VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT SD.ID FROM SCREENDDS SD WHERE SD.SCREENNAME = V_SCRNAME; SET V_SCRNAME = P_SCRNAME; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETSLICELOCATIONS ( IN P_VARSLICEID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARSLICEID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM SLICELOCATION S WHERE S.SLICEID = V_VARSLICEID; SET V_VARSLICEID = P_VARSLICEID; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETPATHSFROMRESOURCETYPE ( IN P_RESTYPE INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_RESTYPE INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT PATHSTR FROM ( SELECT PTH.PATHSTR FROM PATHS PTH INNER JOIN OCCURRENCES OCC ON PTH.PATHID = OCC.PATHID WHERE OCC.RESOURCETYPE = V_RESTYPE UNION SELECT JPOS.RESOURCEFILEPATH AS PATHSTR FROM JCLPOSITION JPOS WHERE JPOS.RESOURCETYPE = V_RESTYPE )SRC; SET V_RESTYPE = P_RESTYPE; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETDATAAREAPATHSFROMRESOURCETYPE ( IN P_RESTYPE INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_RESTYPE INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT PTH.PATHSTR FROM PATHS PTH INNER JOIN OCCURRENCES OCC ON PTH.PATHID = OCC.PATHID WHERE OCC.RESOURCETYPE = V_RESTYPE UNION SELECT DAC.DATAAREAPATH FROM DATAAREACORESP DAC )SRC; SET V_RESTYPE = P_RESTYPE; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETPATHIDBYNAME ( IN P_PATHX VARCHAR(256) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_PATHX VARCHAR(256); DECLARE CRS CURSOR WITH RETURN FOR SELECT PTH.PATHID FROM PATHS PTH WHERE PTH.PATHSTR = V_PATHX; SET V_PATHX = P_PATHX; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETCOBOLINNERPROGRAMSPATHS ( IN P_FILTERANCESTORPROGRAMPATH VARCHAR(250) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_FILTERANCESTORPROGRAMPATH VARCHAR(250); DECLARE V_RC INTEGER DEFAULT 1; DECLARE GLOBAL TEMPORARY TABLE SESSION.GICU ( PATHSTR VARCHAR(260) ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; SET V_FILTERANCESTORPROGRAMPATH = P_FILTERANCESTORPROGRAMPATH; INSERT INTO SESSION.GICU VALUES(V_FILTERANCESTORPROGRAMPATH); WHILE (V_RC > 0 ) DO INSERT INTO SESSION.GICU(PATHSTR) SELECT DISTINCT PTH.PATHSTR AS INNERPROGRAMPATH FROM PROGRAMS AS PROGRAMS_1 INNER JOIN PROGRAMS PGM ON PROGRAMS_1.ANCESTOR = PGM.PROGRAMNAME INNER JOIN OCCURRENCES OCC ON PROGRAMS_1.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON PTH.PATHID = OCC.PATHID INNER JOIN OCCURRENCES AS OCCURRENCES_1 ON PGM.OCCURID = OCCURRENCES_1.OCCURID INNER JOIN PATHS AS PATHS_1 ON OCCURRENCES_1.PATHID = PATHS_1.PATHID INNER JOIN SESSION.GICU G ON PATHS_1.PATHSTR = G.PATHSTR WHERE NOT EXISTS ( SELECT G1.PATHSTR FROM SESSION.GICU G1 WHERE G1.PATHSTR = PTH.PATHSTR ); GET DIAGNOSTICS V_RC = ROW_COUNT; END WHILE; DELETE FROM SESSION.GICU WHERE PATHSTR = V_FILTERANCESTORPROGRAMPATH ; BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM SESSION.GICU; OPEN CRS; END; END @
CREATE OR REPLACE PROCEDURE GETJCLSTATEMENTS01 ( IN P_JCLFILEPATH VARCHAR(255) ) DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE V_JCLFILEPATH VARCHAR(255); SET V_JCLFILEPATH = P_JCLFILEPATH; INSERT INTO INNUNIONEDGES (SOURCEIDNODE, TARGETIDNODE, EDGESTARTROW, EDGEENDROW, EDGESTARTCOL, EDGEENDCOL, EDGEFILENAME, EDGETYPE, PROGID, EDGEID, RESOURCEID) SELECT CAST(LENGTH(CAST(QDCP.JOBID AS VARCHAR(20))) AS VARCHAR(20)) || CAST(QDCP.JOBID AS VARCHAR(20)) || '22' AS RESOURCEID, CAST(LENGTH(CAST(JPGM.PGMID AS VARCHAR(20))) AS VARCHAR(20)) || CAST(JPGM.PGMID AS VARCHAR(20)) || '27' AS TARGETID, QDCP.STARTROW, QDCP.ENDROW, QDCP.STARTCOL, QDCP.ENDCOL, QDCP.RESOURCEFILEPATH, -1 AS STATEMENTTYPE, JPGM.PGMID, QDCP.JOBID, QDCP.POSITIONID FROM JCLPGM JPGM INNER JOIN(QJCLMINIMIZEDDIRECTCALLPROGRAMEDGES QDCP LEFT OUTER JOIN PROGRAMALIASES PGM ON QDCP.PGMNAME = PGM.ALIASNAME) ON JPGM.PGMNAME = QDCP.PGMNAME WHERE PGM.ALIASNAME IS NULL AND V_JCLFILEPATH = QDCP.RESOURCEFILEPATH; END @
CREATE OR REPLACE PROCEDURE GETJCLSTATEMENTS00 ( IN P_JCLFILEPATH VARCHAR(255) ) DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE V_JCLFILEPATH VARCHAR(255); SET V_JCLFILEPATH = P_JCLFILEPATH; INSERT INTO INNUNIONEDGES (SOURCEIDNODE, TARGETIDNODE, EDGESTARTROW, EDGEENDROW, EDGESTARTCOL, EDGEENDCOL, EDGEFILENAME, EDGETYPE, PROGID, EDGEID, RESOURCEID) SELECT CAST(LENGTH(CAST(QDCP.JOBID AS VARCHAR(20))) AS VARCHAR(20)) || CAST(QDCP.JOBID AS VARCHAR(20)) || '22' AS RESOURCEID, PGM.PROGRAMID, QDCP.STARTROW, QDCP.ENDROW, QDCP.STARTCOL, QDCP.ENDCOL, QDCP.RESOURCEFILEPATH, 0 AS STATEMENTTYPE, PGM.PROGRAMID, QDCP.JOBID, QDCP.POSITIONID FROM QJCLMINIMIZEDDIRECTCALLPROGRAMEDGES QDCP LEFT OUTER JOIN PROGRAMALIASES PGM ON QDCP.PGMNAME = PGM.ALIASNAME WHERE PGM.ALIASNAME IS NOT NULL AND V_JCLFILEPATH = QDCP.RESOURCEFILEPATH; END @
CREATE OR REPLACE PROCEDURE GETJCLSTATEMENTS02 ( IN P_JCLFILEPATH VARCHAR(255) ) DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE V_JCLFILEPATH VARCHAR(255); SET V_JCLFILEPATH = P_JCLFILEPATH; INSERT INTO INNUNIONEDGES (SOURCEIDNODE, TARGETIDNODE, EDGESTARTROW, EDGEENDROW, EDGESTARTCOL, EDGEENDCOL, EDGEFILENAME, EDGETYPE, PROGID, EDGEID, RESOURCEID) SELECT CAST(LENGTH(CAST(QMCPE.JOBID AS VARCHAR(20))) AS VARCHAR(20)) || CAST(QMCPE.JOBID AS VARCHAR(20)) || '22' AS RESOURCEID, PGM.PROGRAMID, QMCPE.STARTROW, QMCPE.ENDROW, QMCPE.STARTCOL, QMCPE.ENDCOL, QMCPE.RESOURCEFILEPATH, 0 AS STATEMENTTYPE, PGM.PROGRAMID, QMCPE.JOBID, QMCPE.POSITIONID FROM QJCLMINIMIZEDINDIRECTCALLPROGRAMEDGES QMCPE LEFT OUTER JOIN PROGRAMALIASES PGM ON QMCPE.PGMNAME = PGM.ALIASNAME WHERE PGM.ALIASNAME IS NOT NULL AND V_JCLFILEPATH = QMCPE.JOBRESOURCEFILEPATH; END @
CREATE OR REPLACE PROCEDURE GETJCLSTATEMENTS03 ( IN P_JCLFILEPATH VARCHAR(255) ) DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE V_JCLFILEPATH VARCHAR(255); SET V_JCLFILEPATH = P_JCLFILEPATH; INSERT INTO INNUNIONEDGES (SOURCEIDNODE, TARGETIDNODE, EDGESTARTROW, EDGEENDROW, EDGESTARTCOL, EDGEENDCOL, EDGEFILENAME, EDGETYPE, PROGID, EDGEID, RESOURCEID) SELECT CAST(LENGTH(CAST(QMCPE.JOBID AS VARCHAR(20))) AS VARCHAR(20)) || CAST(QMCPE.JOBID AS VARCHAR(20)) || '22' AS RESOURCEID, CAST(LENGTH(CAST(JPGM.PGMID AS VARCHAR(20))) AS VARCHAR(20)) || CAST(JPGM.PGMID AS VARCHAR(20)) || '27' AS TARGETID, QMCPE.STARTROW, QMCPE.ENDROW, QMCPE.STARTCOL, QMCPE.ENDCOL, QMCPE.RESOURCEFILEPATH, -1 AS STATEMENTTYPE, JPGM.PGMID, QMCPE.JOBID, QMCPE.POSITIONID FROM JCLPGM JPGM INNER JOIN QJCLMINIMIZEDINDIRECTCALLPROGRAMEDGES QMCPE ON JPGM.PGMNAME = QMCPE.PGMNAME LEFT OUTER JOIN PROGRAMALIASES PGM ON QMCPE.PGMNAME = PGM.ALIASNAME WHERE PGM.ALIASNAME IS NULL AND V_JCLFILEPATH = QMCPE.JOBRESOURCEFILEPATH; END @
CREATE OR REPLACE PROCEDURE GETJCLSTATEMENTS1() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO INNUNIONEDGES (SOURCEIDNODE, TARGETIDNODE, PROGID, EDGETYPE, EDGEFILENAME, EDGESTARTROW, EDGEENDROW, EDGESTARTCOL, EDGEENDCOL, RESOURCEID ) SELECT DISTINCT GS10.SID, GS10.TID, GS10.TID, GS10.STATEMENTTYPE, GS10.PATHSTR, GS10.STARTROW, GS10.ENDROW, GS10.STARTCOL, GS10.ENDCOL, GS10.OCCURID FROM GETJCLSTATEMENTS10 GS10 LEFT OUTER JOIN INNUNIONEDGES IUE ON GS10.SID = IUE.SOURCEIDNODE AND GS10.TID = IUE.TARGETIDNODE AND GS10.STARTROW = IUE.EDGESTARTROW AND GS10.ENDROW = IUE.EDGEENDROW WHERE IUE.SOURCEIDNODE IS NULL AND IUE.TARGETIDNODE IS NULL AND IUE.EDGESTARTROW IS NULL AND IUE.EDGEENDROW IS NULL; END @
CREATE OR REPLACE PROCEDURE GETCOPYPATHS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT PTH.PATHSTR FROM PATHS PTH INNER JOIN OCCURRENCES OCC ON PTH.PATHID = OCC.PATHID INNER JOIN RESOURCES RES ON RES.OCCURID = OCC.OCCURID WHERE RES.RESOURCETYPE IN (13, 67, 60, 57, 94, 99); OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETDDMMAINFRMMEMBERSPROC() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MFNM.NATMEMBERID, MFNM.NATMEMBERNAME, MFLB.LIBID, MFNM.MEMBERTYPE FROM MFNATURALMEMBERS MFNM INNER JOIN MFNATURALLIBRARIES MFLB ON MFNM.NATLIBID = MFLB.LIBID INNER JOIN INNUNIONEDGES IUE ON MFLB.LIBID = IUE.EDGETYPE WHERE MFNM.MFMEMBERTYPE = 23; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETINCLUDEEXTENSIONSBYTYPE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PFP.PROPVALUE, PFF.ID_FILETYPE, PF.NAME FROM PJ_FILETYPES PFT INNER JOIN PJFOLDERSVSFILETYPES PFF ON PFT.ID_FILETYPE = PFF.ID_FILETYPE INNER JOIN PJ_FOLDER PF ON PFF.ID_FOLDER = PF.ID_FOLDER INNER JOIN PJ_FOLDERPROP PFP ON PF.ID_FOLDER = PFP.ID_FOLDER WHERE PFF.ID_FILETYPE IN (2, 18, 20, 56, 64) AND PFP.ID_PROPTYPE = 38; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETINCLUDEPATHSBYTYPE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PPP.ID_PROPTYPE, PPP.PROPVALUE, PPT.PROPNAME FROM PJ_PROJECTPROP PPP INNER JOIN PJ_PROPTYPES PPT ON PPP.ID_PROPTYPE = PPT.ID_PROPTYPE WHERE PPP.ID_PROPTYPE IN (23, 24, 28, 32, 37); OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETINCLUDEPATHSMISSING() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PTH.PATHID, PTH.PATHSTR, RES.RESOURCETYPE, RES.RESOURCEID FROM RESOURCES RES INNER JOIN OCCURRENCES OCC ON RES.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE RES.RESOURCETYPE IN (13, 67, 60, 57, 94, 99) AND PTH.PATHSTR NOT LIKE '%\%'; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETPL1INCLUDEPROGRAMSPATHS ( IN P_FILTERANCESTORPROGRAMPATH VARCHAR(250) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL SS: BEGIN BEGIN DECLARE V_FILTERANCESTORPROGRAMPATH VARCHAR(250); DECLARE V_RC INTEGER DEFAULT 1; DECLARE GLOBAL TEMPORARY TABLE SESSION.GICU ( PATHSTR VARCHAR(260) ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; SET V_FILTERANCESTORPROGRAMPATH = P_FILTERANCESTORPROGRAMPATH; INSERT INTO SESSION.GICU VALUES(V_FILTERANCESTORPROGRAMPATH); WHILE (V_RC > 0 ) DO INSERT INTO SESSION.GICU(PATHSTR) SELECT DISTINCT PATHS_1.PATHSTR AS INCLUDEDFILEPATHWITHPROGRAMS FROM OCCURRENCES OCC INNER JOIN OCCURRENCESSTMT OS ON OCC.SOURCETYPE = OS.OCCURID AND OCC.RESOURCETYPE = 5 INNER JOIN PATHS PTH ON OS.PATHID = PTH.PATHID INNER JOIN PATHS AS PATHS_1 ON OCC.PATHID = PATHS_1.PATHID INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM.PROGRAMID AND PGM.PROGRAMTYPEID = 2 INNER JOIN SESSION.GICU G ON PTH.PATHSTR = G.PATHSTR WHERE NOT EXISTS ( SELECT G1.PATHSTR FROM SESSION.GICU G1 WHERE G1.PATHSTR = PATHS_1.PATHSTR ); GET DIAGNOSTICS V_RC = ROW_COUNT; END WHILE; DELETE FROM SESSION.GICU WHERE PATHSTR = V_FILTERANCESTORPROGRAMPATH; BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM SESSION.GICU; OPEN CRS; END; END; END @
CREATE OR REPLACE PROCEDURE JOBPROCREPORT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT JJ.JOBNAME, JPROC.PROCNAME FROM JCLDDREF JCREF INNER JOIN JCLJOB JJ ON JCREF.JOBID = JJ.JOBID INNER JOIN JCLPROC JPROC ON JCREF.PROCID = JPROC.PROCID INNER JOIN INNUNIONEDGES IUE ON JJ.JOBNAME = IUE.EDGEFILENAME LEFT OUTER JOIN JCLPHYSICALDATASET JPDS ON JCREF.DATASETID = JPDS.DATASETID WHERE JCREF.DATASETID > 0 AND JPROC.PROCID > 0 ORDER BY JJ.JOBNAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE MAPSVSPROGREPORT () DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT B.BMSNAME AS NAME, PGM.PROGRAMNAME AS S_NAME FROM STATEMENTREFERENCE SR INNER JOIN BMS B ON SR.RESOURCEID = B.BMSID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM .PROGRAMID INNER JOIN INNUNIONEDGES IUE ON B.BMSNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 6 AND PGM .OCCURID <> 0 ORDER BY B.BMSNAME, PGM .PROGRAMNAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE MFDDMMEMBERSGETUPDATEMAKEDATE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT MPI.MVSCONNECTIONNAME, MNL.LIBRARYNAME, MNM.NATMEMBERNAME, MPI.IPADDRESS, TT.PORT, MNM.UPDATEDATE, MNM.VERSION, 0 AS MODIFNUMBER FROM MFLPARINFO MPI INNER JOIN SESSION.TEMPTABLE TT ON MPI.MVSCONNECTIONNAME = TT.MVSCONN INNER JOIN MFNATURALLIBRARIES MNL ON MPI.LPARID = MNL.LPARID AND TT.LIBNAME = MNL.LIBRARYNAME INNER JOIN MFNATURALMEMBERS MNM ON MNL.LIBID = MNM.NATLIBID AND TT.MEMBERNAME = MNM.NATMEMBERNAME WHERE MNM.MFMEMBERTYPE = 23; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE MFLIBRARIANMEMBERSGETUPDATEMAKEDATE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT MPI.MVSCONNECTIONNAME, MFL.LIBRARYNAME, MLM.LIBRARIANMEMBERNAME, MPI.IPADDRESS, TT.PORT, MLM.UPDATEDATE, 0 AS VERSION, 0 AS MODIFNUMBER FROM MFLIBRARIANMEMBERS MLM INNER JOIN MFLIBRARIES MFL ON MLM.LIBID = MFL.LIBRARYID INNER JOIN MFLPARINFO MPI ON MFL.LPARCONNID = MPI.LPARID INNER JOIN SESSION.TEMPTABLE TT ON MPI.MVSCONNECTIONNAME = TT.MVSCONN AND MFL.LIBRARYNAME = TT.LIBNAME AND MLM.LIBRARIANMEMBERNAME = TT.MEMBERNAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE MFMEMBERSGETUPDATEMAKEDATE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT MPI.MVSCONNECTIONNAME, MFL.LIBRARYNAME, MFMB.MEMBERNAME, MPI.IPADDRESS, TT.PORT, MFMB.RETREIVEDATE, MFMB.VERSION, MFMB.MODIFICATIONNUMBER, MFMB.MEMBERID FROM MFLPARINFO MPI INNER JOIN SESSION.TEMPTABLE TT INNER JOIN MFLIBRARIES MFL ON TT.LIBNAME = MFL.LIBRARYNAME ON MPI.MVSCONNECTIONNAME = TT.MVSCONN AND MPI.LPARID = MFL.LPARCONNID INNER JOIN MFMEMBERS MFMB ON MFMB.MEMBERNAME = TT.MEMBERNAME AND MFL.LIBRARYID = MFMB.LIBRARYID ORDER BY MFMB.MEMBERID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE MFMEMBERSGETUPDATEMAKEINFO() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT MPI.MVSCONNECTIONNAME, MFL.LIBRARYNAME, MFMB.MEMBERNAME, MPI.IPADDRESS, TT.PORT, MFMB.RETREIVEDATE, MFMB.RETRIEVEDVERSION, MFMB.RETRIEVEDMODIFICATIONNUMBER, MFMB.MEMBERID FROM MFLPARINFO MPI INNER JOIN SESSION.TEMPTABLE TT INNER JOIN MFLIBRARIES MFL ON TT.LIBNAME = MFL.LIBRARYNAME ON MPI.MVSCONNECTIONNAME = TT.MVSCONN AND MPI.LPARID = MFL.LPARCONNID INNER JOIN MFMEMBERS MFMB ON MFMB.MEMBERNAME = TT.MEMBERNAME AND MFL.LIBRARYID = MFMB.LIBRARYID ORDER BY MFMB.MEMBERID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE MFNATURALMEMBERSGETUPDATEMAKEDATE() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT MPI.MVSCONNECTIONNAME, MNL.LIBRARYNAME, MNM.NATMEMBERNAME, MPI.IPADDRESS, TT.PORT, MNM.UPDATEDATE, MNM.VERSION, 0 AS MODIFNUMBER FROM MFLPARINFO MPI INNER JOIN SESSION.TEMPTABLE TT ON MPI.MVSCONNECTIONNAME = TT.MVSCONN INNER JOIN MFNATURALLIBRARIES MNL ON MPI.LPARID = MNL.LPARID AND TT.LIBNAME = MNL.LIBRARYNAME INNER JOIN MFNATURALMEMBERS MNM ON MNL.LIBID = MNM.NATLIBID AND TT.MEMBERNAME = MNM.NATMEMBERNAME WHERE MNM.MFMEMBERTYPE = 3; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE NPROGS0 ( IN P_ROOTPROGNAME VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_ROOTPROGNAME VARCHAR(256); SET V_ROOTPROGNAME = P_ROOTPROGNAME; INSERT INTO NPROGS(PROGRAMID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM WHERE PGM.PROGRAMNAME = V_ROOTPROGNAME; END@
CREATE OR REPLACE PROCEDURE NPROGS1() LANGUAGE SQL BEGIN INSERT INTO NPROGS(PROGRAMID) SELECT DISTINCT ID FROM NPROGS10 WHERE ID NOT IN ( SELECT PROGRAMID FROM NPROGS ); END@
CREATE OR REPLACE PROCEDURE NPROGS1B() LANGUAGE SQL BEGIN INSERT INTO NPROGS(PROGRAMID) SELECT DISTINCT ID FROM NPROGS10B WHERE ID NOT IN ( SELECT PROGRAMID FROM NPROGS ); END @
CREATE OR REPLACE PROCEDURE NPROGS1BF() LANGUAGE SQL BEGIN INSERT INTO NPROGS(PROGRAMID) SELECT DISTINCT ID FROM NPROGS10BF WHERE ID NOT IN ( SELECT PROGRAMID FROM NPROGS ); END@
CREATE OR REPLACE PROCEDURE NPROGS1BRESOURCECENTRICGRAPH() LANGUAGE SQL BEGIN INSERT INTO NPROGS(PROGRAMID) SELECT DISTINCT ID FROM NPROGS10BCENTRICGRAPH WHERE ID NOT IN ( SELECT PROGRAMID FROM NPROGS ) AND PGTYPE IN (4, 5, 6); END@
CREATE OR REPLACE PROCEDURE NPROGS1RESOURCECENTRICGRAPH() LANGUAGE SQL BEGIN INSERT INTO NPROGS(PROGRAMID) SELECT DISTINCT ID FROM NPROGS10CENTRICGRAPH WHERE ID NOT IN ( SELECT PROGRAMID FROM NPROGS ) AND PGTYPE IN (4, 5, 6); END@
CREATE OR REPLACE PROCEDURE NPROGSDEL() LANGUAGE SQL BEGIN DELETE FROM NPROGS WHERE 1= 1 ; END@
CREATE OR REPLACE PROCEDURE NPROGSINS ( IN P_PROGIDPARAM INTEGER ) LANGUAGE SQL BEGIN DECLARE V_PROGIDPARAM INTEGER; SET V_PROGIDPARAM = P_PROGIDPARAM; INSERT INTO NPROGS(PROGRAMID) SELECT V_PROGIDPARAM FROM SYSIBM.SYSDUMMY1; END@
CREATE OR REPLACE PROCEDURE PROGVSCALLEDREPORT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT CALLEDPROGS.PROGRAMNAME AS S_NAME, PGM.PROGRAMNAME AS NAME, SR.STATEMENTTYPE FROM OCCURRENCESSTMT OS INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM.PROGRAMID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS AS CALLEDPROGS ON SR.RESOURCEID = CALLEDPROGS.PROGRAMID INNER JOIN INNUNIONEDGES IUE ON CALLEDPROGS.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 5 ORDER BY CALLEDPROGS.PROGRAMNAME, PGM.PROGRAMNAME, SR.STATEMENTTYPE; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE PROGVSCALLINGREPORT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT PGM.PROGRAMNAME AS NAME, CALLEDPROGS.PROGRAMNAME AS S_NAME, SR.STATEMENTTYPE FROM OCCURRENCESSTMT OS INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM.PROGRAMID INNER JOIN PROGRAMS AS CALLEDPROGS ON SR.RESOURCEID = CALLEDPROGS.PROGRAMID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 5 ORDER BY PGM.PROGRAMNAME, CALLEDPROGS.PROGRAMNAME, SR.STATEMENTTYPE; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE PROGSUMMARYREPORT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT * FROM QPROGSUMMARYBMS UNION SELECT * FROM QPROGSUMMARYCOPY UNION SELECT * FROM QPROGSUMMARYFILE UNION SELECT * FROM QPROGSUMMARYSQLTABLE )SRC ORDER BY PROGRAMNAME, TYPE, NAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QADDBMSTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'BMS' AS TYPE, BM.BMSNAME AS NAME, PGM.PROGRAMNAME, 'Dummy' AS RESOURCENAME, -1 AS VARID, -1 AS ANCESTORID, SR.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM NPROGS NP INNER JOIN BMS BM ON NP.PROGRAMID = BM.BMSID INNER JOIN STATEMENTREFERENCE SR ON BM.BMSID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 6 AND PGM.OCCURID <> 0; END@
CREATE OR REPLACE PROCEDURE QADDCHILDVARSFROMCOPIESTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'RECORD' AS TYPE, V.VARNAME AS NAME, PGM.PROGRAMNAME, RES.NAME AS RESOURCENAME, V.VARID, V.ANCESTOR, OS.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM NPROGS NP INNER JOIN VARIABLES V ON NP.PROGRAMID = V.ANCESTOR INNER JOIN STATEMENTREFERENCE SR ON V.VARID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME INNER JOIN RESOURCES RES ON RES.RESOURCEID = V.PROGIDREFERENCE WHERE V.ANCESTOR <> 0 AND SR.RESOURCETYPE = 4 AND V.ISCOPY = 1; END	@
CREATE OR REPLACE PROCEDURE QADDCHILDVARSTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'RECORD' AS TYPE, V.VARNAME AS NAME, PGM.PROGRAMNAME, PROGRAMS_1.PROGRAMNAME, V.VARID, V.ANCESTOR, OS.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM PROGRAMS AS PROGRAMS_1 INNER JOIN VARIABLES V ON PROGRAMS_1.PROGRAMID = V.PROGIDREFERENCE INNER JOIN NPROGS NP ON NP.PROGRAMID = V.ANCESTOR INNER JOIN STATEMENTREFERENCE SR ON V.VARID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE V.ANCESTOR <> 0 AND SR.RESOURCETYPE = 4 AND V.ISCOPY = 0; END@
CREATE OR REPLACE PROCEDURE QADDCOPIESTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'COPY' AS TYPE, RES.NAME, PGM.PROGRAMNAME, 'Dummy' AS RESOURCENAME, -1 AS VARID, -1 AS ANCESTORID, SR.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM NPROGS NP INNER JOIN RESOURCES RES ON NP.PROGRAMID = RES.RESOURCEID INNER JOIN STATEMENTREFERENCE SR ON RES.RESOURCEID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 13 AND PGM.OCCURID <> 0; END@
CREATE OR REPLACE PROCEDURE QADDFILESTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'FILE' AS TYPE, F.LOGICALNAME AS NAME, PGM.PROGRAMNAME, 'Dummy' AS RESOURCENAME, -1 AS VARID, -1 AS ANCESTORID, SR.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM PROGRAMS PGM INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN FILES F ON F.FILEID = SR.RESOURCEID INNER JOIN NPROGS NP ON NP.PROGRAMID = F.FILEID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 9 AND PGM.OCCURID <> 0; END@
CREATE OR REPLACE PROCEDURE QADDRECVARSFROMCOPIESTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'RECORD' AS TYPE, V.VARNAME AS NAME, PGM.PROGRAMNAME, RES.NAME AS RESOURCENAME, V.VARID, V.ANCESTOR, OS.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM RESOURCES RES INNER JOIN VARIABLES V ON RES.RESOURCEID = V.PROGIDREFERENCE INNER JOIN NPROGS NP ON NP.PROGRAMID = V.VARID INNER JOIN STATEMENTREFERENCE SR ON V.VARID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE V.ANCESTOR = 0 AND SR.RESOURCETYPE = 4 AND V.ISCOPY = 1 ; END@
CREATE OR REPLACE PROCEDURE QADDRECVARSTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'RECORD' AS TYPE, V.VARNAME AS NAME, PGM.PROGRAMNAME, PROGRAMS_1.PROGRAMNAME, V.VARID, V.ANCESTOR, OS.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM PROGRAMS AS PROGRAMS_1 INNER JOIN VARIABLES V ON PROGRAMS_1.PROGRAMID = V.PROGIDREFERENCE INNER JOIN NPROGS NP ON NP.PROGRAMID = V.VARID INNER JOIN STATEMENTREFERENCE SR ON V.VARID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE V.ANCESTOR = 0 AND SR.RESOURCETYPE = 4 AND V.ISCOPY = 0; END@
CREATE OR REPLACE PROCEDURE QADDSQLTABLESTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'TABLE' AS TYPE, ST.TABLENAME AS NAME, PGM.PROGRAMNAME, 'Dummy' AS RESOURCENAME, -1 AS VARID, -1 AS ANCESTORID, SR.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM NPROGS NP INNER JOIN SQLTABLES ST ON NP.PROGRAMID = ST.SQLTABLEID INNER JOIN STATEMENTREFERENCE SR ON ST.SQLTABLEID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 1 AND PGM.OCCURID <> 0 ; END@
CREATE OR REPLACE PROCEDURE QADDTRANSACTIONSTOTEMPTBL() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO TEMPTBL(TYPE, NAME, PROGRAMNAME, RESOURCENAME, VARID, ANCESTORID, STARTROW, ENDROW, STARTCOL, ENDCOL, STATEMENTTYPE) SELECT 'TRANSACTION' AS TYPE, RES.NAME, PGM.PROGRAMNAME, 'Dummy' AS RESOURCENAME, -1 AS VARID, -1 AS ANCESTORID, SR.STARTROW, OS.ENDROW, OS.STARTCOL, OS.ENDCOL, OS.STATEMENTTYPE FROM NPROGS NP INNER JOIN RESOURCES RES ON NP.PROGRAMID = RES.RESOURCEID INNER JOIN STATEMENTREFERENCE SR ON RES.RESOURCEID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 14 AND PGM.OCCURID <> 0; END@
CREATE OR REPLACE PROCEDURE QANNINSUSER ( P_USERNAME VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_USERNAME VARCHAR(256); SET V_USERNAME = P_USERNAME; INSERT INTO USERS(USERNAME) VALUES(V_USERNAME); END@
CREATE OR REPLACE PROCEDURE QDECISIONS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM DECISIONS ORDER BY DECISIONID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QDECISIONSPFF() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT D.NAME, DP.SERIALNUM, DP.DECISIONID, DP.PROJECTNAME AS DECISIONPFFNAME, 1 AS UNIONTYPE FROM DECISIONS D INNER JOIN DECISIONPROJECT DP ON DP.DECISIONID = D.DECISIONID UNION SELECT D.NAME, DF.SERIALNUM, DF.DECISIONID, DF.FOLDERNAME AS DECISIONPFFNAME, 2 AS UNIONTYPE FROM DECISIONS D INNER JOIN DECISIONFOLDER DF ON DF.DECISIONID = D.DECISIONID UNION SELECT D.NAME, DF.SERIALNUM, DF.DECISIONID, DF.FILENAME AS DECISIONPFFNAME, 3 AS UNIONTYPE FROM DECISIONS D INNER JOIN DECISIONFILES DF ON DF.DECISIONID = D.DECISIONID ) SRC ORDER BY SRC.NAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QDECISIONSRULES() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT D.NAME, R.RULEID, R.TYPE, R.INPUTPATTERN, R.OUTPUTPATTERN, R.DECISIONID, RT.RULETYPEID, RT.DESCRIPTION FROM RULES R INNER JOIN DECISIONS D ON R.DECISIONID = D.DECISIONID LEFT OUTER JOIN RULETYPE RT ON R.TYPE = RT.RULETYPEID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QDELTEMPTBL() LANGUAGE SQL BEGIN DELETE FROM TEMPTBL WHERE 1 = 1 ; END@
CREATE OR REPLACE PROCEDURE QDELUNIONDESTNODES() LANGUAGE SQL BEGIN DELETE FROM UNIONDESTNODES WHERE 1 = 1 ; END@
CREATE OR REPLACE PROCEDURE QDELUNIONEDGES() LANGUAGE SQL BEGIN DELETE FROM INNUNIONEDGES WHERE 1 = 1 ; END@
CREATE OR REPLACE PROCEDURE QDETACHPARAGRAPHSFROMPROGID ( IN P_FPATH VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_FPATH VARCHAR(256); SET V_FPATH = P_FPATH; UPDATE PARAGRAPHS PAR SET PAR.PROGRAMID = 0 WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID INNER JOIN PROGRAMS PRG ON OCC.OCCURID = PRG.OCCURID WHERE PRG.PROGRAMID = PAR.PROGRAMID AND PTH.PATHSTR = V_FPATH ); END@
CREATE OR REPLACE PROCEDURE QHALSTEAD1() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PGM.PROGRAMID, COUNT(OS.STATEMENTTYPE) AS COUNTER FROM INNUNIONEDGES IUE INNER JOIN PROGRAMS PGM ON IUE.PROGID = PGM.PROGRAMID INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN UNIONDESTNODES UDN ON OS.STATEMENTTYPE = UDN.RESOURCETYPE GROUP BY PGM.PROGRAMID ORDER BY PGM.PROGRAMID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QHEURISTIC2() DYNAMIC RESULT SETS 1 LANGUAGE SQL SS: BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PGM.PROGRAMNAME, QHDR.DECLAREDRECORDS, QHDRFC.DECLAREDRECORDSFROMCOPIES, QHSS.SQLSTATEMENT, QHS.CICSSTATEMENT, QHCS.CONDITIONALSTATEMENT, QHIS.IOSTATEMENT, QHCLS.CALLXCTLLINKSTATEMENT, QHPS.PERFORMSTATEMENT, QHGS.GOTOSTATEMENT, QHAS.ASSIGNMENTSTATEMENT FROM PROGRAMS PGM LEFT OUTER JOIN QHEURISTICASSIGNMENTSTATEMENT QHAS ON PGM.PROGRAMID = QHAS.PROGRAMID LEFT OUTER JOIN QHEURISTICCALLXCTLLINKSTATEMENT QHCLS ON PGM.PROGRAMID = QHCLS.PROGRAMID LEFT OUTER JOIN QHEURISTICCICSSTATEMENT QHS ON PGM.PROGRAMID = QHS.PROGRAMID LEFT OUTER JOIN QHEURISTICCONDITIONALSTATEMENT QHCS ON PGM.PROGRAMID = QHCS.PROGRAMID LEFT OUTER JOIN QHEURISTICDECLAREDRECORDS QHDR ON PGM.PROGRAMID = QHDR.PROGRAMID LEFT OUTER JOIN QHEURISTICDECLAREDRECORDSFROMCOPIES QHDRFC ON PGM.PROGRAMID = QHDRFC.PROGRAMID LEFT OUTER JOIN QHEURISTICGOTOSTATEMENT QHGS ON PGM.PROGRAMID = QHGS.PROGRAMID LEFT OUTER JOIN QHEURISTICIOSTATEMENT QHIS ON PGM.PROGRAMID = QHIS.PROGRAMID LEFT OUTER JOIN QHEURISTICPERFORMSTATEMENT QHPS ON PGM.PROGRAMID = QHPS.PROGRAMID LEFT OUTER JOIN QHEURISTICSQLSTATEMENT QHSS ON PGM.PROGRAMID = QHSS.PROGRAMID INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMID = IUE.PROGID WHERE PGM.OCCURID <> 0 ORDER BY PGM.PROGRAMID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QHEURISTIC2EZREPORTS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PGM.PROGRAMID, QHRS.STATEMENTTYPE, QHRS.STATEMENTSCOUNT, QHDR.DECLAREDRECORDS, QHDRF.DECLAREDRECORDSFROMCOPIES FROM PROGRAMS PGM INNER JOIN INNUNIONEDGES IUE ON PGM.PROGRAMID = IUE.PROGID LEFT OUTER JOIN QHEURISTICDECLAREDRECORDS QHDR ON PGM.PROGRAMID = QHDR.PROGRAMID LEFT OUTER JOIN QHEURISTICDECLAREDRECORDSFROMCOPIES QHDRF ON PGM.PROGRAMID = QHDRF.PROGRAMID LEFT OUTER JOIN QHEURISTICSTATEMENTSEZREPORTS QHRS ON PGM.PROGRAMID = QHRS.PROGID WHERE PGM.OCCURID <> 0 ORDER BY PGM.PROGRAMID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE QINNADABASFILEEDGES() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN INSERT INTO INNUNIONEDGES (SOURCEIDNODE, TARGETIDNODE, EDGETYPE, EDGEFILENAME, EDGESTARTROW, EDGEENDROW, EDGESTARTCOL, EDGEENDCOL, EDGEID, PROGID, EDGECONDITIONALINFO, RESOURCETYPE, RESOURCEID, BREAD ) SELECT * FROM( SELECT QIMA.SOURCEID AS SOURCEIDNODE, QIMA.TARGETID AS TARGETIDNODE, QIMA.EDGETYPE, PTH.PATHSTR AS EDGEFILENAME, OS.STARTROW AS EDGESTARTROW, OS.ENDROW AS EDGEENDROW, OS.STARTCOL AS EDGESTARTCOL, OS.ENDCOL AS EDGEENDCOL, CAST(NULL AS INTEGER) AS EDGEID, OS.PROGID, QIMA.EDGECONDITIONALINFO, QIMA.TARGETTYPE, QIMA.RESOURCEID, QIMA.BREAD FROM PATHS PTH INNER JOIN OCCURRENCESSTMT OS ON PTH.PATHID = OS.PATHID INNER JOIN QINNMINIMIZEDADABASFILEEDGES QIMA ON OS.OCCURID = QIMA.EDGEID UNION SELECT QIMA.SOURCEID AS SOURCEIDNODE, QIMA.TARGETID AS TARGETIDNODE, QIMA.EDGETYPE, PTH.PATHSTR AS EDGEFILENAME, OS.STARTROW AS EDGESTARTROW, OS.ENDROW AS EDGEENDROW, OS.STARTCOL AS EDGESTARTCOL, OS.ENDCOL AS EDGEENDCOL, CAST(NULL AS INTEGER) AS EDGEID, OS.PROGID, QIMA.EDGECONDITIONALINFO, QIMA.TARGETTYPE, QIMA.RESOURCEID, QIMA.BREAD FROM PATHS PTH INNER JOIN OCCURRENCESSTMT OS ON PTH.PATHID = OS.PATHID INNER JOIN QINNMINIMIZEDADABASFILEEDGES QIMA ON OS.OCCURID = QIMA.EDGEID )SRC; END@
CREATE OR REPLACE PROCEDURE QREMOVEADABASDATABASESFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM ADABASDATABASES WHERE ADABASDBID IN ( SELECT AD.ADABASDBID FROM ADABASDATABASES AD LEFT JOIN STATEMENTREFERENCE SR ON AD.ADABASDBID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 194 ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEADABASFILESFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM ADABASFILES WHERE FILEID IN ( SELECT AF.FILEID FROM ADABASFILES AF LEFT JOIN STATEMENTREFERENCE SR ON AF.FILEID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 56 ); END@
CREATE OR REPLACE PROCEDURE QREMOVEADABASVIEWFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM ADABASVIEW WHERE VIEWID IN ( SELECT AV.VIEWID FROM ADABASVIEW AV LEFT JOIN STATEMENTREFERENCE SR ON AV.VIEWID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 62 ); END@
CREATE OR REPLACE PROCEDURE QREMOVEBMSFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM BMS WHERE BMSID IN ( SELECT B.BMSID FROM BMS B LEFT JOIN STATEMENTREFERENCE SR ON B.BMSID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 6 AND SR.RESOURCEID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVECOPYBOOKSFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM RESOURCES WHERE RESOURCEID IN ( SELECT RES.RESOURCEID FROM RESOURCES RES LEFT JOIN STATEMENTREFERENCE SR ON RES.RESOURCEID = SR.RESOURCEID WHERE RES.RESOURCETYPE = 13 AND SR.RESOURCETYPE = 13 AND SR.RESOURCEID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVEIDMSORPHANSFROM_IDMSRECORDSTRUCTURE() LANGUAGE SQL BEGIN DELETE FROM IDMSRECORDSTRUCTURE WHERE PARENTID NOT IN ( SELECT ID FROM IDMSRECORDSTRUCTURE ) AND PARENTID <> -1; END@
CREATE OR REPLACE PROCEDURE QREMOVEIDMSFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM IDMS WHERE IDMSTABLEID IN ( SELECT I.IDMSTABLEID FROM IDMS I LEFT JOIN STATEMENTREFERENCE SR ON I.IDMSTABLEID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 63 ); END@
CREATE OR REPLACE PROCEDURE QREMOVEIDMSSCHEMASETSBYSCHEMAPATH ( IN P_FPATH VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_FPATH VARCHAR(256); SET V_FPATH = P_FPATH; DELETE FROM IDMSSCHEMASETS WHERE ID IN ( SELECT ISCS.ID FROM(IDMSSCHEMASETS ISCS RIGHT JOIN IDMSSCHEMA ISC ON ISCS.SCHEMAID = ISC.ID) INNER JOIN(OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID) ON ISC.OCCURID = OCC.OCCURID WHERE PTH.PATHSTR = V_FPATH ); END@
CREATE OR REPLACE PROCEDURE QREMOVEIMSMAPSFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM IMSMAPS WHERE MAPID IN ( SELECT IM.MAPID FROM IMSMAPS IM LEFT JOIN STATEMENTREFERENCE SR ON IM.MAPID = SR.RESOURCEID WHERE SR.RESOURCETYPE = 65 AND SR.RESOURCEID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVENATURALDBVIEWFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM NATURALDBVIEW WHERE VIEWID IN ( SELECT N.VIEWID FROM NATURALDBVIEW N LEFT JOIN STATEMENTREFERENCE SR ON N.VIEWID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 193 ); END@
CREATE OR REPLACE PROCEDURE QREMOVENATURALDDMFILESFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM NATURALDDM WHERE DDM_ID IN ( SELECT N.DDM_ID FROM NATURALDDM N LEFT JOIN STATEMENTREFERENCE SR ON N.DDM_ID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 192 ); END@
CREATE OR REPLACE PROCEDURE QREMOVENATURALINCLUDESFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM RESOURCES WHERE RESOURCEID IN ( SELECT RES.RESOURCEID FROM RESOURCES RES LEFT JOIN STATEMENTREFERENCE SR ON RES.RESOURCEID = SR.RESOURCEID WHERE RES.RESOURCETYPE = 60 AND SR.RESOURCETYPE = 60 AND SR.RESOURCEID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMADABASDATABASESFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN ADABASDATABASES AD ON OCC.RESOURCEID = AD.ADABASDBID WHERE OCC.RESOURCETYPE = 194 AND AD.ADABASDBID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMADABASFILESFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN ADABASFILES AF ON OCC.RESOURCEID = AF.FILEID WHERE OCC.RESOURCETYPE = 56 AND AF.FILEID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMADABASVIEWFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN ADABASVIEW AV ON OCC.RESOURCEID = AV.VIEWID WHERE OCC.RESOURCETYPE = 62 AND AV.VIEWID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMBMSFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN BMS B ON OCC.RESOURCEID = B.BMSID WHERE OCC.RESOURCETYPE = 6 AND B.BMSID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMCOPYBOOKSFROMPROGID( ) LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN RESOURCES RES ON OCC.RESOURCEID = RES.RESOURCEID WHERE OCC.RESOURCETYPE = 13 AND RES.OCCURID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMFILESFROMPROGID( ) LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN FILES F ON OCC.RESOURCEID = F.FILEID WHERE OCC.RESOURCETYPE = 9 AND F.FILEID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMIDMSFROMPROGID ( ) LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN IDMS I ON OCC.RESOURCEID = I.IDMSTABLEID WHERE OCC.RESOURCETYPE = 63 AND I.IDMSTABLEID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMNATURALDBVIEWFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN NATURALDBVIEW N ON OCC.RESOURCEID = N.VIEWID WHERE OCC.RESOURCETYPE = 193 AND N.VIEWID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMNATURALDDMFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN NATURALDDM N ON OCC.RESOURCEID = N.DDM_ID WHERE OCC.RESOURCETYPE = 192 AND N.DDM_ID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMNATURALINCLUDESFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN RESOURCES RES ON OCC.RESOURCEID = RES.RESOURCEID WHERE OCC.RESOURCETYPE = 60 AND RES.OCCURID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMNATURALMAPSFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN NATURALMAPS N ON OCC.RESOURCEID = N.MAPID WHERE OCC.RESOURCETYPE = 61 AND N.MAPID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMSQLTABLESFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN SQLTABLES ST ON OCC.RESOURCEID = ST.SQLTABLEID WHERE OCC.RESOURCETYPE = 1 AND ST.SQLTABLEID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVESQLFIELDSFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM SQLFIELDS WHERE SQLFIELDID IN ( SELECT SF.SQLFIELDID FROM SQLFIELDS SF LEFT JOIN SQLTABLES ST ON SF.SQLTABLEID = ST.SQLTABLEID WHERE ST.SQLTABLEID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVESQLTABLESFROMPROGID() LANGUAGE SQL BEGIN DELETE FROM SQLTABLES WHERE SQLTABLEID IN ( SELECT ST.SQLTABLEID FROM SQLTABLES ST LEFT JOIN STATEMENTREFERENCE SR ON ST.SQLTABLEID = SR.RESOURCEID WHERE SR.RESOURCEID IS NULL AND SR.RESOURCETYPE = 1 ) ; END@
CREATE OR REPLACE PROCEDURE QREMOVESTMTREFSEXFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM STATEMENTREFERENCEEX WHERE OCCURID IN ( SELECT SR.OCCURID FROM OCCURRENCESSTMT OS RIGHT JOIN STATEMENTREFERENCEEX SR ON OS.OCCURID = SR.OCCURID WHERE OS.OCCURID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVESTMTREFSFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM STATEMENTREFERENCE WHERE OCCURID IN ( SELECT SR.OCCURID FROM OCCURRENCESSTMT OS RIGHT JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID WHERE OS.OCCURID IS NULL ); END@
CREATE OR REPLACE PROCEDURE QREMOVEVARSFROMCOPYBOOKSFROMPROGID () LANGUAGE SQL BEGIN DELETE FROM VARIABLES WHERE VARID IN ( SELECT V.VARID FROM VARIABLES V LEFT JOIN RESOURCES RES ON V.PROGIDREFERENCE = RES.RESOURCEID WHERE RES.RESOURCEID IS NULL AND V.ISCOPY = 1 AND RES.RESOURCETYPE = 13 ); END@
CREATE OR REPLACE PROCEDURE QRESETOCCURIDFROMDBDRESOURCEFORDBD ( IN P_DBDPATH VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_DBDPATH VARCHAR(256); SET V_DBDPATH = P_DBDPATH; UPDATE RESOURCES R SET R.OCCURID = -1 WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 207 AND OCC.OCCURID = R.OCCURID AND PTH.PATHSTR = V_DBDPATH ); END@
CREATE OR REPLACE PROCEDURE RECORDDECLREPORT() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT PGM.PROGRAMNAME, V.VARNAME, V.VARSIZE, V.PIC, V.ILEVEL, V.REDEFINES, V.VARID, V.FATHER, V.ANCESTOR FROM PROGRAMS PGM INNER JOIN VARIABLES V ON PGM.PROGRAMID = V.PROGIDREFERENCE INNER JOIN INNUNIONEDGES IUE ON V.VARID = IUE.EDGETYPE WHERE V.ILEVEL = 1 UNION SELECT PGM.PROGRAMNAME, V.VARNAME, V.VARSIZE, V.PIC, V.ILEVEL, V.REDEFINES, V.VARID, V.FATHER, V.ANCESTOR FROM PROGRAMS PGM INNER JOIN VARIABLES V ON PGM.PROGRAMID = V.PROGIDREFERENCE INNER JOIN UNIONDESTNODES UDN ON V.ANCESTOR = UDN.RESOURCETYPE WHERE V.ILEVEL <> 1 )SRC ORDER BY SRC.VARID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE RECORDSTRUCTREPORT() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT PGM.PROGRAMNAME AS NAME, V.VARNAME, V.NUMOFCHILDS, V.VARSIZE, V.ILEVEL, V.VARID, V.FATHER, V.ANCESTOR FROM VARIABLES V INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = V.PROGIDREFERENCE WHERE V.ISCOPY = 0 AND V.ILEVEL = 1 AND V.VARID IN ( SELECT EDGETYPE FROM INNUNIONEDGES ) UNION SELECT PGM.PROGRAMNAME AS NAME, V.VARNAME, V.NUMOFCHILDS, V.VARSIZE, V.ILEVEL, V.VARID, V.FATHER, V.ANCESTOR FROM VARIABLES V INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = V.PROGIDREFERENCE WHERE V.ISCOPY = 0 AND V.ILEVEL <> 1 AND V.ANCESTOR IN ( SELECT RESOURCETYPE FROM UNIONDESTNODES) UNION SELECT RES.NAME AS NAME, V.VARNAME, V.NUMOFCHILDS, V.VARSIZE, V.ILEVEL, V.VARID, V.FATHER, V.ANCESTOR FROM VARIABLES V INNER JOIN RESOURCES RES ON V.PROGIDREFERENCE = RES.RESOURCEID WHERE V.ISCOPY = 1 AND V.ILEVEL = 1 AND V.VARID IN ( SELECT EDGETYPE FROM INNUNIONEDGES ) UNION SELECT RES.NAME AS NAME, V.VARNAME, V.NUMOFCHILDS, V.VARSIZE, V.ILEVEL, V.VARID, V.FATHER, V.ANCESTOR FROM VARIABLES V INNER JOIN RESOURCES RES ON V.PROGIDREFERENCE = RES.RESOURCEID WHERE V.ISCOPY = 1 AND V.ILEVEL <> 1 AND V.ANCESTOR IN ( SELECT RESOURCETYPE FROM UNIONDESTNODES) )SRC ORDER BY SRC.VARID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE REPORTS_APPRES() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM ( SELECT 'Program' AS RESOURCETYPE, PGM.PROGRAMNAME AS NAME FROM PROGRAMS PGM WHERE PGM.OCCURID <> 0 UNION SELECT 'Copy' AS RESOURCETYPE, RES.NAME FROM RESOURCES RES WHERE RES.OCCURID <> 0 AND RES.RESOURCETYPE = 13 UNION SELECT 'BMS' AS RESOURCETYPE, B.BMSNAME AS NAME FROM BMS B WHERE B.OCCURID <> 0 AND B.ISMAPSET = 0 UNION SELECT 'File' AS RESOURCETYPE, F.LOGICALNAME AS NAME FROM FILES F WHERE F.OCCURID <> 0 UNION SELECT 'RDBMS Table' AS RESOURCETYPE, ST.TABLENAME AS NAME FROM SQLTABLES ST WHERE ST.NUMOFFIELDS > 0 AND ST.OCCURID <> 0 )SRC ORDER BY SRC.RESOURCETYPE, SRC.NAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE REPORTS_PARAPROGS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PGM.PROGRAMNAME, PAR.PARANAME, PAR.ALTERPARA, PAR.ISEMPTY, PAR.ISPROGEXIT, PAR.REFERENCECOUNT, PAR.UNREACHABLEPARA, PAR.PARAFALLTHROUGHTYPE, PAR.NUMOFSTATEMENTS, PAR.NUMOFLINES FROM PROGRAMS PGM INNER JOIN PARAGRAPHS PAR ON PGM.PROGRAMID = PAR.PROGRAMID WHERE PGM.OCCURID <> 0 ORDER BY PGM.PROGRAMNAME, PAR.PARANAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE REPORTS_VARFILTER() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT V.VARID AS VAR_ID, V.VARNAME AS VARIABLE_NAME, VV.VARID AS RECORD_ID, VV.VARNAME AS RECORD_NAME, P.PROGRAMNAME AS PROGRAM_NAME, V.ILEVEL AS VAR_LEVEL, V.PIC AS VAR_FORMAT, V.VARSIZE AS VAR_SIZE, V.FATHER AS VAR_FATHER, V.NUMOFCHILDS AS VAR_CHILDREN FROM PROGRAMS AS P INNER JOIN VARIABLES AS V ON P.PROGRAMID = V.PROGIDREFERENCE INNER JOIN VARIABLES AS VV ON VV.VARID = V.ANCESTOR ; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SCLINNERGRAPH_FILTEROUTSTANDARDSCLPROCEDURES() LANGUAGE SQL BEGIN DELETE FROM UNIONDESTNODES WHERE RESOURCEID IN ( SELECT UDN.RESOURCEID FROM PROGRAMS PGM INNER JOIN SCLSTANDARDPROCEDURES SSP ON PGM.PROGRAMNAME = SSP.NAME INNER JOIN UNIONDESTNODES UDN ON UDN.RESOURCENAME = PGM.ANCESTOR || ':' || PGM.PROGRAMNAME WHERE UDN.RESOURCETYPE = 5 AND PGM.PROGRAMTYPEID = 19 AND UDN.PROGRAMTYPEID = 19 ); END@
CREATE OR REPLACE PROCEDURE SCLOUTERGRAPH_FILTEROUTSTANDARDSCLPROCEDURES() LANGUAGE SQL BEGIN DELETE FROM NPROGS WHERE PROGRAMID IN ( SELECT DISTINCT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN SCLSTANDARDPROCEDURES SSP ON PGM.PROGRAMNAME = SSP.NAME WHERE PGM.PROGRAMTYPEID = 19 ); END@
CREATE OR REPLACE PROCEDURE SELECTCATALOGEDDATASETS ( IN P_VARDATASETNAME VARCHAR(255), IN P_VARVOLSER VARCHAR(255), IN P_VARDEVICETYPE INTEGER, IN P_VARPOSONTAPE INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARDATASETNAME, V_VARVOLSER VARCHAR(255); DECLARE V_VARDEVICETYPE, V_VARPOSONTAPE INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT DATASETID FROM JCLPHYSICALDATASET WHERE ISCATALOGED = 1 AND V_VARDATASETNAME = DATASETNAME AND (V_VARVOLSER = '' OR VOLUMESERIAL = '' OR V_VARVOLSER = VOLUMESERIAL) AND (V_VARDEVICETYPE = 0 OR DEVICETYPE = 0 OR V_VARDEVICETYPE = DEVICETYPE) AND (V_VARPOSONTAPE = 0 OR POSITIONONTAPEVOL = 0 OR V_VARPOSONTAPE = POSITIONONTAPEVOL); SET V_VARDATASETNAME = P_VARDATASETNAME; SET V_VARVOLSER = P_VARVOLSER; SET V_VARDEVICETYPE = P_VARDEVICETYPE; SET V_VARPOSONTAPE = P_VARPOSONTAPE; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTNONCATALOGEDDATASET ( IN P_VARDATASETNAME VARCHAR(255), IN P_VARVOLSER VARCHAR(255), IN P_VARDEVICETYPE INTEGER, IN P_VARPOSONTAPE INTEGER, IN P_VARJOBID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARDATASETNAME, V_VARVOLSER VARCHAR(255); DECLARE V_VARDEVICETYPE, V_VARPOSONTAPE, V_VARJOBID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT DATASETID FROM JCLPHYSICALDATASET WHERE ISCATALOGED = 0 AND V_VARDATASETNAME = DATASETNAME AND V_VARVOLSER = VOLUMESERIAL AND V_VARDEVICETYPE = DEVICETYPE AND V_VARPOSONTAPE = POSITIONONTAPEVOL AND V_VARJOBID = TEMPDSJOBID; SET V_VARDATASETNAME = P_VARDATASETNAME; SET V_VARVOLSER = P_VARVOLSER; SET V_VARDEVICETYPE = P_VARDEVICETYPE; SET V_VARPOSONTAPE = P_VARPOSONTAPE; SET V_VARJOBID = P_VARJOBID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTINCLUDECONN ( IN P_VARINCLUDEID INTEGER, IN P_VARJOBID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARINCLUDEID, V_VARJOBID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT CONNID FROM JCLINCLUDECONN WHERE JOBID = V_VARJOBID AND INCLUDEID = V_VARINCLUDEID; SET V_VARINCLUDEID = P_VARINCLUDEID; SET V_VARJOBID = P_VARJOBID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTINCLUDEGROUP ( IN P_MEMBER VARCHAR(256), IN P_PDS VARCHAR(256) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_MEMBER, V_PDS VARCHAR(256); DECLARE CRS CURSOR WITH RETURN FOR SELECT INCLUDEID FROM JCLINCLUDEGROUP WHERE MEMBERNAME = V_MEMBER AND PDSNAME = V_PDS; SET V_MEMBER = P_MEMBER; SET V_PDS = P_PDS; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTPGM ( IN P_VARPGMNAME VARCHAR(256), IN P_VARPDSNAME VARCHAR(256), IN P_VARDATASETID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARPGMNAME, V_VARPDSNAME VARCHAR(256); DECLARE V_VARDATASETID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT PGMID FROM JCLPGM WHERE V_VARPGMNAME = PGMNAME AND V_VARPDSNAME = PDSNAME AND V_VARDATASETID = DATASETID; SET V_VARPGMNAME = P_VARPGMNAME; SET V_VARPDSNAME = P_VARPDSNAME; SET V_VARDATASETID = P_VARDATASETID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTPROC ( IN P_VARPROCNAME VARCHAR(256), IN P_VARPDSNAME VARCHAR(256), IN P_VARJOBID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARPROCNAME, V_VARPDSNAME VARCHAR(256); DECLARE V_VARJOBID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT PROCID FROM JCLPROC WHERE PROCNAME = V_VARPROCNAME AND PDSNAME = V_VARPDSNAME AND JOBID = V_VARJOBID; SET V_VARPROCNAME = P_VARPROCNAME; SET V_VARPDSNAME = P_VARPDSNAME; SET V_VARJOBID = P_VARJOBID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTSLICE ( IN P_VARSLICENAME VARCHAR(256) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARSLICENAME VARCHAR(256); DECLARE CRS CURSOR WITH RETURN FOR SELECT SLICEID FROM SLICE WHERE SLICENAME = V_VARSLICENAME; SET V_VARSLICENAME = P_VARSLICENAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SELECTSPOOLDATASET ( IN P_VARCLASS VARCHAR(256), IN P_VARSPOOLTYPE INTEGER, IN P_VARJOBID INTEGER, IN P_VAROUTPUTID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_VARCLASS VARCHAR(256); DECLARE V_VARSPOOLTYPE, V_VARJOBID, V_VAROUTPUTID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT SPOOLID FROM JCLSPOOLDATASET WHERE CLASS = V_VARCLASS AND SPOOLTYPE = V_VARSPOOLTYPE AND JOBID = V_VARJOBID AND OUTPUTID = V_VAROUTPUTID; SET V_VARCLASS = P_VARCLASS; SET V_VARSPOOLTYPE = P_VARSPOOLTYPE; SET V_VARJOBID = P_VARJOBID; SET V_VAROUTPUTID = P_VAROUTPUTID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE SETDATAAREATS ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE DATAAREACORESP SET ETIMESTAMP = V_TS WHERE DATAAREAPATH = V_PATHSTRPARAM; END@
CREATE OR REPLACE PROCEDURE SETTS_AAUTODSFLAGREPORT ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE AAUTODSFLAGTONETWORKS A SET A.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 206 AND A.OCCURID = OCC.OCCURID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTS_AAUTOSCHEDULINGFILES ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE AAUTONETWORKS A SET A.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 5000 AND A.OCCURID = OCC.OCCURID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
