CREATE OR REPLACE PROCEDURE SETTS_NATURALMAPS ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE NATURALMAPS N SET N.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 61 AND N.MAPID = OCC.RESOURCEID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTS_SMARTBATCHPROCESSES ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_FILEPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_FILEPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_FILEPARAM = P_FILEPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE BATCHPROCESSES B SET B.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM PATHS PTH WHERE B.PATHID = PTH.PATHID AND PTH.PATHSTR = V_FILEPARAM ); END@
