CREATE OR REPLACE PROCEDURE SETTS_SMARTSCREENS ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE SCREENDDS S SET S.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 69 AND S.ID = OCC.RESOURCEID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTSBMS ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE BMS B SET B.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 6 AND B.BMSID = OCC.RESOURCEID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTSINCLGROUP ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE JCLINCLUDEGROUP J SET J.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM JCLPOSITION P WHERE P.RESOURCETYPE = 33 AND P.POSITIONID = J.POSITIONID AND P.RESOURCEFILEPATH = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTSJOB ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE JCLJOB J SET J.ETIMESTAMP = V_TS WHERE J.BUILDSTATUS = 1 AND EXISTS ( SELECT 1 FROM JCLPOSITION P WHERE P.RESOURCETYPE = 22 AND P.POSITIONID = J.POSITIONID AND P.RESOURCEFILEPATH = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTSPROC ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE JCLPROC J SET J.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM JCLPOSITION P WHERE P.RESOURCETYPE = 25 AND P.POSITIONID = J.POSITIONID AND P.RESOURCEFILEPATH = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SETTSPROG ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE PROGRAMS P SET P.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 5 AND P.OCCURID = OCC.OCCURID AND PTH.PATHSTR = V_PATHSTRPARAM ); COMMIT; END@
CREATE OR REPLACE PROCEDURE SETTSRES ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE RESOURCES R SET R.ETIMESTAMP = V_TS WHERE R.RESOURCEID IN ( SELECT RR.RESOURCEID FROM RESOURCES RR INNER JOIN OCCURRENCES OCC ON RR.RESOURCEID = OCC.RESOURCEID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE IN (13, 60, 67, 94, 99) AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE SPNS_REMOVECOMPONENTREFERENCES ( IN P_LPARID INTEGER, IN P_LIBRARYNAME VARCHAR(255), IN P_JOBSKELETONMEMBERNAME VARCHAR(255) ) LANGUAGE SQL BEGIN DECLARE V_LPARID, V_RID INTEGER; DECLARE V_LIBRARYNAME, V_JOBSKELETONMEMBERNAME VARCHAR(255); SET V_LPARID = P_LPARID; SET V_LIBRARYNAME = P_LIBRARYNAME; SET V_JOBSKELETONMEMBERNAME = P_JOBSKELETONMEMBERNAME; SET V_RID = ( SELECT ROOTID FROM SPNS_SAPIENSROOT WHERE LPARID = V_LPARID AND LIBRARYNAME = V_LIBRARYNAME AND JOBSKELETONMEMBERNAME = V_JOBSKELETONMEMBERNAME ); BEGIN DELETE FROM SPNS_BLOCKINFORMDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_CALLINGRULESETANDRULE WHERE ROOTID = V_RID; DELETE FROM SPNS_CLASSDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_CLASSINCOMPOSITE WHERE ROOTID = V_RID; DELETE FROM SPNS_COMPOSITEDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_DATESTAMP WHERE ROOTID = V_RID; DELETE FROM SPNS_EDITTRIGGERRULESETFOROPERATION WHERE ROOTID = V_RID; DELETE FROM SPNS_FIELDDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_FIELDINOPERATION WHERE ROOTID = V_RID; DELETE FROM SPNS_FIELDINPROGRAMDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_FIELDUSEDINCLASS WHERE ROOTID = V_RID; DELETE FROM SPNS_FIELDUSEDINQUERY WHERE ROOTID = V_RID; DELETE FROM SPNS_FIELDUSEDINRULES WHERE ROOTID = V_RID; DELETE FROM SPNS_FORMCALLINGFORM WHERE ROOTID = V_RID; DELETE FROM SPNS_FORMDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_FORMSCALLINGQUERY WHERE ROOTID = V_RID; DELETE FROM SPNS_ISSUETRIGGERRULESETFOROPERATION WHERE ROOTID = V_RID; DELETE FROM SPNS_MENUOPTIONINFORM WHERE ROOTID = V_RID; DELETE FROM SPNS_OPERATIONDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_PFACTIONSFORFORM WHERE ROOTID = V_RID; DELETE FROM SPNS_PROGRAMDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_QUERYDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_QUERYSOURCE WHERE ROOTID = V_RID; DELETE FROM SPNS_RECORDCOUNT WHERE ROOTID = V_RID; DELETE FROM SPNS_RULESETDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_RULEWITHINRULESETDEFINITION WHERE ROOTID = V_RID; DELETE FROM SPNS_RULEWITHINRULESETSOURCE WHERE ROOTID = V_RID; DELETE FROM SPNS_SQLNAMEOFFIELDINCLASSINCOMPSITE WHERE ROOTID = V_RID; DELETE FROM SPNS_TARGETOFOPERATION WHERE ROOTID = V_RID; DELETE FROM SPNS_TRIGGEREDRULESETFORBLOCKINFORM WHERE ROOTID = V_RID; DELETE FROM SPNS_TRIGGEREDRULESETSFORPROGRAM WHERE ROOTID = V_RID; DELETE FROM SPNS_TRIGGEREDRULESETSFORQUERY WHERE ROOTID = V_RID; DELETE FROM SPNS_TRIGGEREDRULESETSINCLASS WHERE ROOTID = V_RID; DELETE FROM SPNS_SAPIENSROOT WHERE ROOTID = V_RID; END; END@
CREATE OR REPLACE PROCEDURE SMARTSCREENSVSPROGREPORT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT SD.SCREENNAME AS NAME, PGM.PROGRAMNAME AS S_NAME FROM STATEMENTREFERENCE SR INNER JOIN SCREENDDS SD ON SR.RESOURCEID = SD.ID INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID INNER JOIN PROGRAMS PGM ON OS.PROGID = PGM.PROGRAMID INNER JOIN INNUNIONEDGES IUE ON SD.SCREENNAME = IUE.EDGEFILENAME WHERE SR.RESOURCETYPE = 69 AND PGM.OCCURID <> 0 ORDER BY SD.SCREENNAME, PGM.PROGRAMNAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE STMT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT * FROM STATEMENTS; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE TABLEDECLREPORT( ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT ST.TABLENAME, SF.FIELDNAME, SF.TYPE, SF.ISIZE, SF.BUNIQUE, SF.BPRIMARYKEY, SF.FOREIGNKEY, SF.TABLEREFERENCE, SF.ISINDEX, SF.BNOTNULL, SF.SZDEFAULT FROM SQLTABLES ST INNER JOIN SQLFIELDS SF ON ST.SQLTABLEID = SF.SQLTABLEID INNER JOIN INNUNIONEDGES IUE ON ST.TABLENAME = IUE.EDGEFILENAME ORDER BY ST.TABLENAME, SF.FIELDNAME; OPEN CRS; END@
