CREATE OR REPLACE PROCEDURE TRUNC_VARIABLEPOS ( ) LANGUAGE SQL BEGIN COMMIT; TRUNCATE TABLE VARIABLEPOS IMMEDIATE; END@
CREATE OR REPLACE PROCEDURE TRUNC_VARIABLES ( ) LANGUAGE SQL BEGIN COMMIT; TRUNCATE TABLE VARIABLES IMMEDIATE; END@
CREATE OR REPLACE PROCEDURE TRUNC_VC_CONTAINERVSRESOURCES ( ) LANGUAGE SQL BEGIN COMMIT; TRUNCATE TABLE VC_CONTAINERVSRESOURCES IMMEDIATE; END@
CREATE OR REPLACE PROCEDURE UCMDB_RECOVERASSOCIATEDJCLJOBS () LANGUAGE SQL BEGIN UPDATE COMPONENTS C SET C.RESOURCEID = ( SELECT U.JOBID FROM UCMDB_GETASSOCIATEDJCLJOBS U WHERE U.COMPONENTID = C.COMPONENTID FETCH FIRST ROWS ONLY ) WHERE EXISTS ( SELECT 1 FROM UCMDB_GETASSOCIATEDJCLJOBS U WHERE U.COMPONENTID = C.COMPONENTID ); END@
CREATE OR REPLACE PROCEDURE UCMDB_RECOVERASSOCIATEDPROGRAMS() LANGUAGE SQL BEGIN UPDATE COMPONENTS C SET C.RESOURCEID = ( SELECT U.PROGRAMID FROM UCMDB_GETASSOCIATEDPROGRAMS U WHERE U.COMPONENTID = C.COMPONENTID FETCH FIRST ROWS ONLY ) WHERE EXISTS ( SELECT 1 FROM UCMDB_GETASSOCIATEDPROGRAMS U WHERE U.COMPONENTID = C.COMPONENTID ); END@
CREATE OR REPLACE PROCEDURE UCMDB_FILTERPROGSNOTINAPP ( IN P_PROGRAMID1 INTEGER ) LANGUAGE SQL BEGIN DECLARE V_PROGRAMID1 INTEGER; SET V_PROGRAMID1 = P_PROGRAMID1; DELETE FROM OCCURRENCESSTMT WHERE PROGID IN (SELECT RESOURCEID FROM TMPRESOURCEID ) AND PROGID <> V_PROGRAMID1; DELETE FROM JCLSTEP WHERE CALLEDPGMID IN ( SELECT JP.PGMID FROM PROGRAMS PGM INNER JOIN TMPRESOURCEID T ON PGM.PROGRAMID = T.RESOURCEID INNER JOIN JCLPGM JP ON PGM.PROGRAMNAME = JP.PGMNAME WHERE PGM.PROGRAMNAME IS NOT NULL AND PGM.PROGRAMNAME <> '' AND PGM.PROGRAMID <> V_PROGRAMID1 ); END@
CREATE OR REPLACE PROCEDURE UCMDB_GETCOMPONENTSINTHESAMEAPP ( IN P_PROGID INTEGER, IN P_PROGTYPE INTEGER, IN P_APP_ID INTEGER ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_PROGID, V_PROGTYPE, V_APP_ID INTEGER; DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT COMPONENTS_1.RESOURCEID AS RESOURCEID, COMPONENTS_1.RESOURCETYPE AS RESOURCETYPE FROM APPTOCOMPONENTS AC INNER JOIN COMPONENTS COMP ON AC.COMPONENTID = COMP.COMPONENTID INNER JOIN APPTOCOMPONENTS APPTOCOMPONENTS_1 ON AC.APPLICATIONID = APPTOCOMPONENTS_1.APPLICATIONID INNER JOIN COMPONENTS COMPONENTS_1 ON APPTOCOMPONENTS_1.COMPONENTID = COMPONENTS_1.COMPONENTID WHERE COMP.RESOURCEID = V_PROGID AND COMP.RESOURCETYPE = V_PROGTYPE AND APPTOCOMPONENTS_1.APPLICATIONID = V_APP_ID; SET V_PROGID = P_PROGID; SET V_PROGTYPE = P_PROGTYPE; SET V_APP_ID = P_APP_ID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE UCMDB_GETMQQUEUE_APPLICATIONS ( IN P_QUEUE_NAME VARCHAR(255), IN P_QMANAGER_NAME VARCHAR(255) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_QUEUE_NAME, V_QMANAGER_NAME VARCHAR(255); DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT AP.APPLICATIONNAME FROM APPLICATIONS AP INNER JOIN APPTOCOMPONENTS ATC ON AP.APPLICATIONID = ATC.APPLICATIONID INNER JOIN COMPONENTS COMP ON ATC.COMPONENTID = COMP.COMPONENTID INNER JOIN PROGRAMS PGM ON COMP.RESOURCEID = PGM.PROGRAMID INNER JOIN OCCURRENCESSTMT OS ON PGM.PROGRAMID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON SR.OCCURID = OS.OCCURID INNER JOIN MQQUEUES MQ ON SR.RESOURCEID = MQ.QUEUEID INNER JOIN MQQUEUEMANAGERS MQM ON MQ.QUEUEMANAGERID = MQM.QUEUEMANAGERID WHERE COMP.RESOURCETYPE = 5 AND SR.RESOURCETYPE = 81 AND MQ.QUEUENAME = V_QUEUE_NAME AND (V_QMANAGER_NAME = '' OR MQM.QUEUEMANAGERNAME = V_QMANAGER_NAME); SET V_QUEUE_NAME = P_QUEUE_NAME; SET V_QMANAGER_NAME = P_QMANAGER_NAME; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE EMAKERSPECIFICSTOREDPROC ( IN P_NAMESTRPARAM VARCHAR(50) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_NAMESTRPARAM VARCHAR(50); SET V_NAMESTRPARAM = P_NAMESTRPARAM; BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT CSPN.NAMESTR, CSPN.ISSELECTTYPE, CSPN.HASPARAMS, SSPN.ISRELATEDTOGRAPHTYPE FROM SYMBOLICVSCALLEDSTOREDPROCRELATION SCSPR INNER JOIN SYMBOLICSTOREDPROCNAMES SSPN ON SCSPR.SYMBOLICNAMEID = SSPN.NAMEID INNER JOIN CALLEDSTOREDPROCNAMES CSPN ON SCSPR.CALLEDNAMEID = CSPN.NAMEID WHERE SSPN.NAMESTR = V_NAMESTRPARAM ORDER BY SCSPR.ORDINALNUM; OPEN CRS; END; END@
CREATE OR REPLACE PROCEDURE DEL_PCBVSIMSSEGMENTSFORPROG ( IN P_PROGPATH VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_PROGPATH VARCHAR(256); SET V_PROGPATH = P_PROGPATH; DELETE FROM PCBVSIMSSEGMENTS WHERE PCBID IN ( SELECT PCB.PSBID FROM PCBINFO PCB INNER JOIN PSBINFO PSB ON PCB.PSBID = PSB.PSBID INNER JOIN PROGRAMS P ON PSB.PROGID = P.PROGRAMID INNER JOIN OCCURRENCES OCC ON P.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON PTH.PATHID = OCC.PATHID WHERE PTH.PATHSTR = V_PROGPATH ); END@
CREATE OR REPLACE PROCEDURE DEL_UNRESOLVEDIMSCALLS ( IN P_PROGPATH VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_PROGPATH VARCHAR(256); SET V_PROGPATH = P_PROGPATH; DELETE FROM UNRESOLVEDIMSCALLS WHERE OCCURSTMTID IN ( SELECT UNRESOLVEDIMSCALL.OCCURSTMTID FROM UNRESOLVEDIMSCALLS UNRESOLVEDIMSCALL INNER JOIN OCCURRENCESSTMT OCC ON UNRESOLVEDIMSCALL.OCCURSTMTID = OCC.OCCURID INNER JOIN PATHS PTH ON PTH.PATHID = OCC.PATHID WHERE PTH.PATHSTR = V_PROGPATH ); END@
CREATE OR REPLACE PROCEDURE RESOLVECALLVARIDS ( IN DEPTHLEVEL SMALLINT ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE LEVEL SMALLINT DEFAULT 0; DECLARE MAXDEPTHLEVEL INT DEFAULT 20; DECLARE V_RC INT DEFAULT 1; DECLARE GLOBAL TEMPORARY TABLE SESSION.SR5 (OCCURID INTEGER, RESOURCEID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX NCIDX_SR5 ON SESSION.SR5 (OCCURID); DECLARE GLOBAL TEMPORARY TABLE SESSION.SR96 (OCCURID INTEGER, RESOURCEID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX NCIDX_SR96 ON SESSION.SR96 (OCCURID); INSERT INTO SESSION.SR5 (OCCURID, RESOURCEID) SELECT OCCURID, RESOURCEID FROM STATEMENTREFERENCE WHERE RESOURCETYPE = 5 GROUP BY OCCURID, RESOURCEID; INSERT INTO SESSION.SR96 (OCCURID, RESOURCEID) SELECT OCCURID, RESOURCEID FROM STATEMENTREFERENCE WHERE RESOURCETYPE = 96 GROUP BY OCCURID, RESOURCEID; IF (0 < DEPTHLEVEL AND DEPTHLEVEL < MAXDEPTHLEVEL) THEN SET MAXDEPTHLEVEL = DEPTHLEVEL; END IF; WHILE V_RC > 0 AND LEVEL < MAXDEPTHLEVEL DO INSERT INTO SESSION.TEMP_UNRESOLVEDVARS SELECT TT1.STMTOCCURID, CP.VARIABLEID AS SRCVARID, PA.PROGID FROM SESSION.SR5 SR INNER JOIN SESSION.SR96 SR1 ON SR.OCCURID = SR1.OCCURID INNER JOIN CALLPARAMETERS CP ON SR1.RESOURCEID = CP.ID INNER JOIN PROGRAMARGUMENTS PA ON CP.ORDINALPOSITION = PA.ORDINALPOSITION AND SR.RESOURCEID = PA.PROGID INNER JOIN SESSION.TEMP_UNRESOLVEDVARS TT1 ON PA.VARIABLEID = TT1.VARID LEFT OUTER JOIN SESSION.TEMP_UNRESOLVEDVARS TT2 ON TT2.VARID = CP.VARIABLEID AND TT2.STMTOCCURID = TT1.STMTOCCURID WHERE TT2.VARID IS NULL UNION SELECT TT3.STMTOCCURID, PCP.RESOURCEID, PA.PROGID FROM PROCEDUREARGUMENTS PA INNER JOIN SESSION.TEMP_UNRESOLVEDVARS TT3 ON PA.VARIABLEID = TT3.VARID INNER JOIN PROCEDURECALLPARAMETERS PCP ON PA.ARGUMENTID = PCP.PROCEDUREARGUMENTID LEFT OUTER JOIN SESSION.TEMP_UNRESOLVEDVARS TT4 ON TT4.VARID = PCP.RESOURCEID AND TT4.STMTOCCURID = TT3.STMTOCCURID WHERE PCP.RESOURCETYPE = 4 AND TT4.VARID IS NULL ; GET DIAGNOSTICS V_RC = ROW_COUNT; SET LEVEL = LEVEL + 1; END WHILE; END@
CREATE OR REPLACE PROCEDURE SETTSPSB ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE PSBINFO PSB SET PSB.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 217 AND PSB.PSBID = OCC.RESOURCEID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE QREMOVEOCCURSFROMPSBFILESFROMPROGID( ) LANGUAGE SQL BEGIN DELETE FROM OCCURRENCES WHERE OCCURID IN ( SELECT OCC.OCCURID FROM OCCURRENCES OCC LEFT JOIN PSBINFO F ON OCC.RESOURCEID = F.PSBID WHERE OCC.RESOURCETYPE = 217 AND F.PSBID IS NULL ) ; END@
CREATE OR REPLACE PROCEDURE SETTSAPIDEPENDENCYDEF ( IN P_YEARPARAM		VARCHAR(10), IN P_MONTHPARAM		VARCHAR(10), IN P_DAYPARAM		VARCHAR(10), IN P_HOURPARAM		VARCHAR(10), IN P_MINPARAM		VARCHAR(10), IN P_SECPARAM		VARCHAR(10), IN P_PATHSTRPARAM	VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE APIDEPENDENCYDEF APIDEP SET APIDEP.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE ( (APIDEP.OCCURID = OCC.OCCURID) AND (PTH.PATHSTR = V_PATHSTRPARAM) AND (OCC.RESOURCETYPE=218) ) ) ; END@
CREATE OR REPLACE PROCEDURE RESOLVECALLLITERALARGIDS () DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.SR5 (OCCURID INTEGER, RESOURCEID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX NCIDX_SR5 ON SESSION.SR5 (OCCURID); DECLARE GLOBAL TEMPORARY TABLE SESSION.SR100 (OCCURID INTEGER, RESOURCEID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX NCIDX_SR100 ON SESSION.SR100 (OCCURID); INSERT INTO SESSION.SR5 (OCCURID, RESOURCEID) SELECT OCCURID, RESOURCEID FROM STATEMENTREFERENCE WHERE RESOURCETYPE = 5 GROUP BY OCCURID, RESOURCEID; INSERT INTO SESSION.SR100 (OCCURID, RESOURCEID) SELECT OCCURID, RESOURCEID FROM STATEMENTREFERENCE WHERE RESOURCETYPE = 100 GROUP BY OCCURID, RESOURCEID; INSERT INTO SESSION.TEMP_UNRESOLVEDVARS2 SELECT DISTINCT UR.OCCURSTMTID, CLP.IDELEM, PA.PROGID FROM SESSION.SR5 SR INNER JOIN SESSION.SR100 AS SR_1 ON SR.OCCURID = SR_1.OCCURID INNER JOIN CALLLITERALPARAMETERS CLP ON SR_1.RESOURCEID = CLP.IDELEM INNER JOIN PROGRAMARGUMENTS PA ON CLP.ORDINALPOSITION = PA.ORDINALPOSITION AND SR.RESOURCEID = PA.PROGID INNER JOIN UNRESOLVEDIMSCALLS UR ON PA.VARIABLEID = UR.VARIABLEID ; END@
CREATE OR REPLACE PROCEDURE EZVIEWER_GETCALLINGPROGRAMID ( IN P_PROGRAMID INTEGER, IN P_FORWARDORBACKWARD SMALLINT ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE SQLSTATE CHAR(5) DEFAULT '00000'; DECLARE SQLCODE INTEGER DEFAULT 0; DECLARE V_ERRORMSG VARCHAR(4000) DEFAULT ''; BEGIN DECLARE V_PROGRAMID ,V_RC ,V_I ,V_J INTEGER; DECLARE V_FORWARDORBACKWARD SMALLINT DEFAULT -1; DECLARE REAL_ISSUE CONDITION FOR SQLSTATE '80010'; DECLARE EXIT HANDLER FOR SQLEXCEPTION RESIGNAL; DECLARE GLOBAL TEMPORARY TABLE SESSION.X ( FROMPROGRAMID INTEGER ,TOPROGRAMID INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.FIN ( FROMPROGRAMID INTEGER ,TOPROGRAMID INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; SET V_PROGRAMID = COALESCE(P_PROGRAMID, 0); SET V_FORWARDORBACKWARD = COALESCE(P_FORWARDORBACKWARD, 1 ); IF(V_FORWARDORBACKWARD NOT IN (1, -1)) THEN SET V_ERRORMSG = 'Please use corect ForwardOrBackward: 1 -> FORWARD or -1 -> BACKWARD' ; SIGNAL REAL_ISSUE SET MESSAGE_TEXT = V_ERRORMSG; RETURN ; END IF; INSERT INTO SESSION.X (FROMPROGRAMID, TOPROGRAMID) SELECT OS.PROGID, SR.RESOURCEID FROM STATEMENTREFERENCE SR INNER JOIN OCCURRENCESSTMT OS ON SR.OCCURID = OS.OCCURID WHERE SR.RESOURCETYPE = 5 GROUP BY OS.PROGID, SR.RESOURCEID ; CREATE INDEX UNQIDX1 ON SESSION.X (FROMPROGRAMID, TOPROGRAMID); CREATE INDEX UNQIDX2 ON SESSION.X (TOPROGRAMID ,FROMPROGRAMID); INSERT INTO SESSION.FIN (FROMPROGRAMID, TOPROGRAMID ) SELECT X.FROMPROGRAMID, X.TOPROGRAMID FROM SESSION.X X WHERE V_PROGRAMID = CASE V_FORWARDORBACKWARD WHEN 1 THEN X.FROMPROGRAMID ELSE X.TOPROGRAMID END ; SET V_I = 1 ; SET V_J = 2001 ; WHILE ( V_I < V_J ) DO SET V_RC = 0 ; IF (V_FORWARDORBACKWARD = 1) THEN INSERT INTO SESSION.FIN(FROMPROGRAMID ,TOPROGRAMID ) SELECT F1.FROMPROGRAMID, X.TOPROGRAMID FROM SESSION.X X INNER JOIN SESSION.FIN F1 ON F1.TOPROGRAMID = X.FROMPROGRAMID LEFT OUTER JOIN SESSION.FIN F2 ON F1.FROMPROGRAMID = F2.FROMPROGRAMID AND X.TOPROGRAMID = F2.TOPROGRAMID WHERE F2.FROMPROGRAMID IS NULL ; GET DIAGNOSTICS V_RC = ROW_COUNT; ELSE INSERT INTO SESSION.FIN(FROMPROGRAMID ,TOPROGRAMID ) SELECT X.FROMPROGRAMID, F1.TOPROGRAMID FROM SESSION.X X INNER JOIN SESSION.FIN F1 ON X.TOPROGRAMID = F1.FROMPROGRAMID LEFT OUTER JOIN SESSION.FIN F2 ON F1.TOPROGRAMID = F2.TOPROGRAMID AND X.FROMPROGRAMID = F2.FROMPROGRAMID WHERE F2.TOPROGRAMID IS NULL ; GET DIAGNOSTICS V_RC = ROW_COUNT; END IF; IF COALESCE(V_RC, 0) = 0 THEN SET V_I = V_J ; ELSE SET V_I = V_I + 1 ; END IF; END WHILE ; BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT F.PROGRAMSOURCEID AS PROGRAMID, F.PROGRAMTARGETID AS CALLEDORCALLINGPROGRAMID, P.PROGRAMNAME AS CALLEDORCALLINGPROGRAMNAME FROM ( SELECT FROMPROGRAMID AS PROGRAMSOURCEID ,TOPROGRAMID AS PROGRAMTARGETID FROM SESSION.FIN WHERE V_FORWARDORBACKWARD = 1 UNION SELECT TOPROGRAMID AS PROGRAMSOURCEID ,FROMPROGRAMID AS PROGRAMTARGETID FROM SESSION.FIN WHERE V_FORWARDORBACKWARD = -1 ) F INNER JOIN ( SELECT PGM.PROGRAMID ,COALESCE(PA.ALIASNAME, PGM.PROGRAMNAME) AS PROGRAMNAME FROM PROGRAMS PGM LEFT OUTER JOIN PROGRAMALIASES PA ON PGM.PROGRAMID = PA.PROGRAMID AND PA.ALIASTYPE = 0 ) P ON F.PROGRAMTARGETID = P.PROGRAMID ORDER BY F.PROGRAMTARGETID ; OPEN CRS; END; END; END @
CREATE OR REPLACE PROCEDURE SETTS_IMSDB ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE ARTEFACTSTIMESTAMPS TMSTMP SET TMSTMP.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM IMSDBINFO IMSDB INNER JOIN OCCURRENCES OCC ON IMSDB.OCCURID = OCC.OCCURID INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE ( PTH.PATHSTR = V_PATHSTRPARAM AND IMSDB.DBID = TMSTMP.RESID AND TMSTMP.RESTYPE = 18 AND OCC.RESOURCETYPE = 18 ) ); END@
CREATE OR REPLACE PROCEDURE SETTS_CTRLM ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE CTM_XMLDATASOURCES CTMXML SET CTMXML.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 224 AND CTMXML.OCCURID = OCC.OCCURID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE CTM_PREPARECACHE ( IN P_DATASOURCETYPEID SMALLINT ) DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE SQLSTATE, V_SQLSTATE_TEST CHAR(5) DEFAULT '00000'; DECLARE SQLCODE, V_SQLCODE_TEST , V_RETURNVAL INTEGER DEFAULT 0; DECLARE V_DATASOURCETYPENAME VARCHAR(100); DECLARE V_DATASOURCETYPEID INTEGER; SET V_DATASOURCETYPEID = COALESCE(P_DATASOURCETYPEID ,1); SET V_DATASOURCETYPENAME = COALESCE((SELECT TRIM(DATASOURCETYPENAME) FROM CTM_DATASOURCETYPES WHERE DATASOURCETYPEID = V_DATASOURCETYPEID) , '') ; BEGIN DECLARE IN_PARAM_NOTOKAY CONDITION FOR SQLSTATE '42615'; DECLARE EXIT HANDLER FOR SQLEXCEPTION RESIGNAL; IF (NULLIF(V_DATASOURCETYPENAME ,'') IS NULL) THEN SET V_RETURNVAL = -1; SIGNAL IN_PARAM_NOTOKAY SET MESSAGE_TEXT = 'Inappropriate DataSourceType!!! Please provide a valid value (1->XML 2->MF)'; RETURN V_RETURNVAL; END IF ; END; BEGIN DECLARE V_CTMPROCESSTYPEID SMALLINT DEFAULT 1; DECLARE V_TOTALVALUE ,V_PARTIALVALUE ,V_MAXCONDITIONGENERALID ,V_MAXJOBGENERALID INTEGER DEFAULT 0; DECLARE V_CTMID ,V_PROJVERSION INTEGER DEFAULT NULL; DECLARE V_NRJOBS ,V_TOTALNRJOBS INTEGER DEFAULT 0; DECLARE V_PROJGUID ,V_PROJECTNAME VARCHAR(255) DEFAULT NULL; DECLARE V_RC ,V_RC_F ,V_RC_B ,V_I ,V_J ,V_K INTEGER; DECLARE V_MSG VARCHAR(2000) DEFAULT ''; DECLARE V_DATASOURCEFAKEID INTEGER DEFAULT 1; DECLARE V_DATE TIMESTAMP; DECLARE EXIT HANDLER FOR SQLEXCEPTION RESIGNAL; DECLARE GLOBAL TEMPORARY TABLE SESSION.NEW_CTMDATASOURCEINFO ( DATASOURCEID INTEGER NOT NULL , DATASOURCENAME VARCHAR(255) NOT NULL , DATASOURCETYPEID SMALLINT NOT NULL , DSPOPULATIONTIMESTAMP TIMESTAMP NOT NULL , DATASOURCENUMBEROFJOBS INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX UIDX_NCDSI ON SESSION.NEW_CTMDATASOURCEINFO (DATASOURCEID); DECLARE GLOBAL TEMPORARY TABLE SESSION.EQ_CTMDATASOURCEINFO ( DATASOURCEID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX UIDX_ECDSI ON SESSION.EQ_CTMDATASOURCEINFO (DATASOURCEID); DECLARE GLOBAL TEMPORARY TABLE SESSION.TODO_CTMDATASOURCEINFO ( DATASOURCEID INTEGER NOT NULL ,PROCESSORREMOVE SMALLINT NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.JOBGENERALIDTODROP ( JOBGENERALID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX UIDX_JGIDT ON SESSION.JOBGENERALIDTODROP (JOBGENERALID); DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBINFO ( JOBGENERALID INTEGER NOT NULL , JOBID INTEGER NOT NULL , JOBNAME VARCHAR(255) NOT NULL , JOBMEMBERNAME VARCHAR(255) , JOBAPPLICATION VARCHAR(255) , JOBSUBAPPLICATION VARCHAR(255) , JOBFOLDERNAME VARCHAR(255) , JOBDESCRIPTION VARCHAR(255) , DATASOURCEID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX NCIDX_CJI ON SESSION.CTMJOBINFO (DATASOURCEID ,JOBID ,JOBGENERALID); DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMCONDITIONS ( CONDITIONGENERALID INTEGER NOT NULL ,DATASOURCEID INTEGER NOT NULL ,CONDITIONNAME VARCHAR(255) NOT NULL ,CONDITIONNAMEHASH VARCHAR(32) FOR BIT DATA NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX NCIDX_CC ON SESSION.CTMCONDITIONS (DATASOURCEID ,CONDITIONNAMEHASH ,CONDITIONGENERALID ,CONDITIONNAME); DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBOUTCONDITIONS ( JOBGENERALID INTEGER ,CONDITIONGENERALID INTEGER ,CONDITIONNAME VARCHAR(255) ,CONDITIONODATE VARCHAR(5) ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBINCONDITIONS ( JOBGENERALID INTEGER ,CONDITIONGENERALID INTEGER ,CONDITIONNAME VARCHAR(255) ,CONDITIONANDOR VARCHAR(5) ,CONDITIONODATE VARCHAR(5) ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBBASERELATIONS ( JOBFROMGENERALID INTEGER , JOBTOGENERALID INTEGER , CONDITIONGENERALID INTEGER , CONDITIONNAME VARCHAR(255) , CONDITIONANDOR VARCHAR(5) , CONDITIONODATE VARCHAR(5) ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBRELATIONS ( JOBFROMGENERALID INTEGER , JOBTOGENERALID INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBCHAININGF ( JOBROOTGENERALID INTEGER , JOBTOGENERALID INTEGER , LVL INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.CTMJOBCHAININGB ( JOBROOTGENERALID INTEGER , JOBTOGENERALID INTEGER , LVL INTEGER ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; SET V_DATE = CURRENT_TIMESTAMP; SET V_PROJVERSION = (SELECT VERSION FROM VC_VERSION); SET V_PROJGUID = (SELECT PROPVALUE FROM PJ_PROJECTPROP WHERE ID_PROPTYPE = 64); SET V_PROJECTNAME = (SELECT PROPVALUE FROM PJ_PROJECTPROP WHERE ID_PROPTYPE = 65); SET V_MSG = ''; INSERT INTO CTM_STATUS(PROJECTNAME, PROJECTGUID, PROJECTVERSION, CTMDATASOURCETYPEID, CTMPROCESSSTATUSTYPEID, NOTES) VALUES( V_PROJECTNAME, V_PROJGUID, V_PROJVERSION, V_DATASOURCETYPEID, 0, V_MSG || '##0 - ' || CAST(V_DATE AS VARCHAR(23)) || '##' ); VALUES IDENTITY_VAL_LOCAL() INTO V_CTMID; COMMIT; BEGIN DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN SELECT SQLSTATE, SQLCODE INTO V_SQLSTATE_TEST ,V_SQLCODE_TEST FROM SYSIBM.SYSDUMMY1; SET V_DATE = CURRENT_TIMESTAMP; UPDATE CTM_STATUS SET 	CTMPROCESSSTATUSTYPEID = 3, CTMPROCESSTYPE = CASE V_CTMPROCESSTYPEID WHEN 0 THEN 'FULL' ELSE 'PARTIAL' END, CTMJOBTOTALCOUNT = V_TOTALNRJOBS, NOTES = 'NrJobsProcessed=' || CAST((COALESCE(v_NrJobs, 0)) AS VARCHAR(10)) || ' ' || COALESCE(Notes, '') || v_Msg || '##3 - '|| CAST(v_date AS VARCHAR(23)) ||' SQLSTATE='|| COALESCE(v_sqlstate_test, '') || ' SQLCODE='|| COALESCE(CAST(v_sqlcode_test AS VARCHAR(30)), '') ||'##' WHERE CTMID = v_CTMID; COMMIT; SET v_returnval = -1; RESIGNAL; RETURN v_returnval; END; IF (v_DataSourceTypeName = 'XML') THEN INSERT INTO SESSION.New_CTMDataSourceInfo(DataSourceID ,DataSourceName ,DataSourceTypeID ,DSPopulationTimeStamp ,DataSourceNumberOfJobs) SELECT x.DataSourceID ,x.DataSourceName ,v_DataSourceTypeID AS DataSourceTypeID ,x.PopulationTimeStamp AS DSPopulationTimeStamp ,COALESCE(c. DataSourceNumberOfJobs , 0) AS DataSourceNumberOfJobs FROM CTM_XMLDataSources x LEFT OUTER JOIN ( SELECT DataSourceID, COUNT(JobID) AS DataSourceNumberOfJobs FROM CTM_XMLDSJobs GROUP BY DataSourceID ) c ON x.DataSourceID = c.DataSourceID; COMMIT; INSERT INTO SESSION.EQ_CTMDataSourceInfo (DataSourceID) SELECT DISTINCT DataSourceID FROM ( SELECT DataSourceID ,DataSourceName ,DataSourceTypeID ,DSPopulationTimeStamp ,DataSourceNumberOfJobs FROM SESSION.New_CTMDataSourceInfo INTERSECT SELECT UsedDataSourceID AS DataSourceID ,UsedDataSourceName AS DataSourceName ,UsedDataSourceTypeID AS DataSourceTypeID ,UDSPopulationTimeStamp AS DSPopulationTimeStamp ,UsedDataSourceNumberOfJobs AS DataSourceNumberOfJobs FROM CTM_UsedDataSources )i; COMMIT; INSERT INTO SESSION.TODO_CTMDataSourceInfo (DataSourceID ,ProcessOrRemove) SELECT DataSourceID ,ProcessOrRemove FROM ( SELECT n.DataSourceID ,1 AS ProcessOrRemove FROM SESSION.New_CTMDataSourceInfo n WHERE NOT EXISTS (SELECT 1 FROM SESSION.EQ_CTMDataSourceInfo f WHERE f.DataSourceID = n.DataSourceID) UNION SELECT o.UsedDataSourceID AS DataSourceID ,2 AS ProcessOrRemove FROM CTM_UsedDataSources o WHERE NOT EXISTS (SELECT 1 FROM SESSION.EQ_CTMDataSourceInfo f WHERE f.DataSourceID = o.UsedDataSourceID) )x ; COMMIT; SET v_TotalValue = COALESCE( (SELECT SUM(DataSourceNumberOfJobs) FROM SESSION.New_CTMDataSourceInfo) ,0 ); SET v_PartialValue = COALESCE( (SELECT SUM(n.DataSourceNumberOfJobs) FROM SESSION.New_CTMDataSourceInfo n WHERE NOT EXISTS (SELECT 1 FROM SESSION.EQ_CTMDataSourceInfo f WHERE f.DataSourceID = n.DataSourceID)) ,0 ); IF ( (REAL(REAL(COALESCE(v_PartialValue, 0)) / COALESCE(NULLIF(v_TotalValue, 0), 1) )) > (REAL(REAL(1) / 2)) ) THEN SET v_CTMProcessTypeID = 0; ELSE SET v_MaxConditionGeneralID = COALESCE((SELECT MAX(ConditionGeneralID) FROM CTM_ConditionDetails) ,0); SET v_MaxJobGeneralID = COALESCE((SELECT MAX(JobGeneralID) FROM CTM_JobDetails ) ,0); END IF; INSERT INTO SESSION.CTMJobInfo (JobGeneralID ,JobID ,JobName ,JobMemberName ,JobApplication ,JobSubApplication ,JobFolderName ,JobDescription ,DataSourceID) SELECT (v_MaxJobGeneralID + JobGeneralID) AS JobGeneralID ,JobID ,JobName ,JobMemberName ,JobApplication ,JobSubApplication ,JobFolderName ,JobDescription ,DataSourceID FROM ( SELECT ROW_NUMBER() OVER(ORDER BY j.DataSourceID ,j.JobID) AS JobGeneralID ,j.JobID ,COALESCE(NULLIF(j.J_JobName, '') ,j.J_MemName) AS JobName ,TRIM(j.J_MemName) AS JobMemberName ,j.J_Application AS JobApplication ,j.J_Sub_Application AS JobSubApplication ,j.F_Folder_Name AS JobFolderName ,j.J_Description AS JobDescription ,j.DataSourceID FROM CTM_XMLDSJobs j WHERE ( v_CTMProcessTypeID = 0 OR EXISTS (SELECT 1 FROM SESSION.TODO_CTMDataSourceInfo f WHERE f.ProcessOrRemove = 1 AND f.DataSourceID = j.DataSourceID) ) )src; GET DIAGNOSTICS v_NrJobs = ROW_COUNT; COMMIT; INSERT INTO SESSION.CTMConditions(ConditionGeneralID, DataSourceID ,ConditionName ,ConditionNameHash) SELECT (v_MaxConditionGeneralID + ROW_NUMBER() OVER(ORDER BY src.DataSourceID ,src.ConditionName)) AS ConditionGeneralID ,src.DataSourceID ,src.ConditionName ,CAST(src.ConditionNameHash AS VARCHAR(32) FOR BIT DATA) AS ConditionNameHash FROM ( SELECT a1.DataSourceID ,a1.J_CI_Name AS ConditionName ,HASH(a1.J_CI_Name, 0) AS ConditionNameHash FROM CTM_XMLDSJobInConditions a1 WHERE ( v_CTMProcessTypeID = 0 OR EXISTS (SELECT 1 FROM SESSION.TODO_CTMDataSourceInfo f WHERE f.ProcessOrRemove = 1 AND f.DataSourceID = a1.DataSourceID) ) UNION SELECT a2.DataSourceID ,a2.J_CO_Name AS ConditionName ,HASH(a2.J_CO_Name, 0) AS ConditionNameHash FROM CTM_XMLDSJobOutConditions a2 WHERE a2.J_CO_Sign IN ('+', 'ADD') AND ( v_CTMProcessTypeID = 0 OR EXISTS (SELECT 1 FROM SESSION.TODO_CTMDataSourceInfo f WHERE f.ProcessOrRemove = 1 AND f.DataSourceID = a2.DataSourceID) ) )src ; COMMIT; INSERT INTO SESSION.CTMJobOutConditions (JobGeneralID ,ConditionGeneralID ,ConditionName ,ConditionOdate) SELECT j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,o.ConditionOdate FROM ( SELECT a2.DataSourceID ,a2.JobID ,CAST(HASH(a2.J_CO_Name, 0) AS VARCHAR(32) FOR BIT DATA) AS ConditionNameHash ,a2.J_CO_Odate AS ConditionOdate FROM CTM_XMLDSJobOutConditions a2 WHERE a2.J_CO_Sign IN ('+', 'ADD') AND ( v_CTMProcessTypeID = 0 OR EXISTS (SELECT 1 FROM SESSION.TODO_CTMDataSourceInfo f WHERE f.ProcessOrRemove = 1 AND f.DataSourceID = a2.DataSourceID) ) ) o INNER JOIN SESSION.CTMConditions c ON o.DataSourceID = c.DataSourceID AND o.ConditionNameHash = c.ConditionNameHash INNER JOIN SESSION.CTMJobInfo j ON o.DataSourceID = j.DataSourceID AND o.JobID = j.JobID GROUP BY j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,o.ConditionOdate; COMMIT; INSERT INTO SESSION.CTMJobInConditions (JobGeneralID ,ConditionGeneralID ,ConditionName ,ConditionAndOr ,ConditionOdate) SELECT j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,i.ConditionAndOr ,i.ConditionOdate FROM ( SELECT a1.DataSourceID ,a1.JobID ,CAST(HASH(a1.J_CI_Name, 0) AS VARCHAR(32) FOR BIT DATA) AS ConditionNameHash ,a1.J_CI_And_Or AS ConditionAndOr ,a1.J_CI_Odate AS ConditionOdate FROM CTM_XMLDSJobInConditions a1 WHERE ( v_CTMProcessTypeID = 0 OR EXISTS (SELECT 1 FROM SESSION.TODO_CTMDataSourceInfo f WHERE f.ProcessOrRemove = 1 AND f.DataSourceID = a1.DataSourceID) ) )i INNER JOIN SESSION.CTMConditions c ON i.DataSourceID = c.DataSourceID AND i.ConditionNameHash = c.ConditionNameHash INNER JOIN SESSION.CTMJobInfo j ON i.DataSourceID = j.DataSourceID AND i.JobID = j.JobID GROUP BY j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,i.ConditionAndOr ,i.ConditionOdate; COMMIT; END IF; IF (v_DataSourceTypeName = 'MAINFRAME AGENTS') THEN SET v_CTMProcessTypeID = 0; INSERT INTO SESSION.New_CTMDataSourceInfo(DataSourceID ,DataSourceName ,DataSourceTypeID ,DSPopulationTimeStamp ,DataSourceNumberOfJobs) SELECT v_DataSourceFakeID AS DataSourceID ,'MAINFRAME' AS DataSourceName ,v_DataSourceTypeID AS DataSourceTypeID ,CURRENT_TIMESTAMP AS DSPopulationTimeStamp ,COALESCE((SELECT COUNT(JobID) FROM MFCTMJobMembers) ,0) AS DataSourceNumberOfJobs FROM SYSIBM.SYSDUMMY1; COMMIT; INSERT INTO SESSION.CTMJobInfo (JobGeneralID ,JobID ,JobName ,JobMemberName ,JobApplication ,JobSubApplication ,JobFolderName ,JobDescription ,DataSourceID) SELECT ROW_NUMBER() OVER(ORDER BY JobID) AS JobGeneralID ,JobID ,JobName ,JobMemberName ,JobApplication ,JobSubApplication ,JobFolderName ,JobDescription ,v_DataSourceFakeID AS DataSourceID FROM ( SELECT m.JobID ,m.MemberName AS JobName ,TRIM(m.MemberName) AS JobMemberName ,m.Application AS JobApplication ,CAST(NULL AS VARCHAR(255)) AS JobSubApplication ,CAST(NULL AS VARCHAR(255)) AS JobFolderName ,m.JobDescription FROM MFCTMJobMembers m )src; GET DIAGNOSTICS v_NrJobs = ROW_COUNT; COMMIT; INSERT INTO SESSION.CTMConditions(ConditionGeneralID, DataSourceID, ConditionName ,ConditionNameHash) SELECT ROW_NUMBER() OVER(ORDER BY src.ConditionName) AS ConditionGeneralID ,v_DataSourceFakeID AS DataSourceID, src.ConditionName ,CAST(src.ConditionNameHash AS VARCHAR(32) FOR BIT DATA) AS ConditionNameHash FROM ( SELECT ConditionName AS ConditionName ,HASH(ConditionName, 0) AS ConditionNameHash FROM MFCTMInConditionVariable UNION SELECT ConditonName AS ConditionName ,HASH(ConditonName, 0) AS ConditionNameHash FROM MFCTMOutConditionVariable WHERE OutOption IN ('+', 'ADD') )src ; COMMIT; INSERT INTO SESSION.CTMJobOutConditions (JobGeneralID ,ConditionGeneralID ,ConditionName ,ConditionOdate) SELECT j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,o.ConditionOdate FROM ( SELECT o1.JobID ,CAST(HASH(o1.ConditonName, 0) AS VARCHAR(32) FOR BIT DATA) AS ConditionNameHash ,o1.DateReference AS ConditionOdate FROM MFCTMOutConditionVariable o1 WHERE o1.OutOption IN ('+', 'ADD') ) o INNER JOIN SESSION.CTMConditions c ON v_DataSourceFakeID = c.DataSourceID AND o.ConditionNameHash = c.ConditionNameHash INNER JOIN SESSION.CTMJobInfo j ON v_DataSourceFakeID = j.DataSourceID AND o.JobID = j.JobID GROUP BY j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,o.ConditionOdate; COMMIT; INSERT INTO SESSION.CTMJobInConditions (JobGeneralID ,ConditionGeneralID , ConditionName ,ConditionAndOr ,ConditionOdate) SELECT j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,CAST(NULL AS VARCHAR(5)) AS ConditionAndOr ,i.DateReference AS ConditionOdate FROM ( SELECT JobID ,CAST(HASH(ConditionName, 0) AS VARCHAR(32) FOR BIT DATA) AS ConditionNameHash ,DateReference FROM MFCTMInConditionVariable )i INNER JOIN SESSION.CTMConditions c ON v_DataSourceFakeID = c.DataSourceID AND i.ConditionNameHash = c.ConditionNameHash INNER JOIN SESSION.CTMJobInfo j ON v_DataSourceFakeID = j.DataSourceID AND i.JobID = j.JobID GROUP BY j.JobGeneralID ,c.ConditionGeneralID ,c.ConditionName ,i.DateReference; COMMIT; END IF; INSERT INTO SESSION.CTMJobBaseRelations (JobFromGeneralID ,JobToGeneralID ,ConditionGeneralID ,ConditionName ,ConditionAndOr ,ConditionOdate) SELECT DISTINCT s1.JobGeneralID AS JobFromGeneralID ,s2.JobGeneralID AS JobToGeneralID ,COALESCE(s1.ConditionGeneralID, s2.ConditionGeneralID) AS ConditionGeneralID ,COALESCE(s1.ConditionName, s2.ConditionName) AS ConditionName ,s2.ConditionAndOr ,s2.ConditionOdate FROM SESSION.CTMJobOutConditions s1 INNER JOIN SESSION.CTMJobInConditions s2 ON s1.ConditionGeneralID = s2.ConditionGeneralID ; COMMIT ; INSERT INTO SESSION.CTMJobRelations (JobFromGeneralID ,JobToGeneralID) SELECT JobFromGeneralID ,JobToGeneralID FROM ( SELECT JobFromGeneralID ,JobToGeneralID FROM SESSION.CTMJobBaseRelations WHERE JobFromGeneralID IS NOT NULL AND JobToGeneralID IS NOT NULL GROUP BY JobFromGeneralID ,JobToGeneralID )s1 ORDER BY JobFromGeneralID ,JobToGeneralID ; COMMIT; INSERT INTO SESSION.CTMJobChainingF (JobRootGeneralID ,JobToGeneralID ,Lvl) SELECT s.JobGeneralID AS JobRootGeneralID, s.JobGeneralID AS JobToGeneralID, 0 AS Lvl FROM SESSION.CTMJobInfo s ; COMMIT ; INSERT INTO SESSION.CTMJobChainingB (JobRootGeneralID ,JobToGeneralID ,Lvl) SELECT s.JobGeneralID AS JobRootGeneralID, s.JobGeneralID AS JobToGeneralID, 0 AS Lvl FROM SESSION.CTMJobInfo s ; COMMIT ; SET v_date = CURRENT_TIMESTAMP; VALUES(0, 0, 1, 2001, 0) INTO v_rc ,v_rc_f ,v_i ,v_j ,v_k; WHILE (v_i < v_j) DO INSERT INTO SESSION.CTMJobChainingF (JobRootGeneralID ,JobToGeneralID ,Lvl) SELECT DISTINCT f1.JobRootGeneralID ,x.JobToGeneralID ,v_i AS Lvl FROM ( SELECT DISTINCT JobRootGeneralID ,JobToGeneralID FROM SESSION.CTMJobChainingF WHERE Lvl = (v_i - 1) )f1 INNER JOIN SESSION.CTMJobRelations x ON f1.JobToGeneralID = x.JobFromGeneralID AND NOT EXISTS (SELECT 1 FROM SESSION.CTMJobChainingF f2 WHERE f2.JobRootGeneralID = f1.JobRootGeneralID AND f2.JobToGeneralID = x.JobToGeneralID); GET DIAGNOSTICS v_rc_f = ROW_COUNT; SET v_rc = v_rc + v_rc_f; SET v_k = v_i; IF (v_rc_f = 0) THEN SET v_i = v_j; ELSE SET v_i = v_i + 1; END IF; END WHILE; COMMIT; SET v_Msg = '##00 F i=' || CAST(V_K AS VARCHAR(10)) || ' r=' || CAST((COALESCE(V_NRJOBS, 0) + COALESCE(V_RC ,0)) AS VARCHAR(10)) || ' start=' || CAST(V_DATE AS VARCHAR(23)) || ' end=' || CAST(CURRENT_TIMESTAMP AS VARCHAR(23)) || '##' ; SET V_DATE = CURRENT_TIMESTAMP; VALUES(0, 0, 1, 2001, 0) INTO V_RC ,V_RC_B ,V_I ,V_J ,V_K; WHILE (V_I < V_J) DO INSERT INTO SESSION.CTMJOBCHAININGB(JOBROOTGENERALID ,JOBTOGENERALID ,LVL) SELECT DISTINCT F1.JOBROOTGENERALID ,X.JOBFROMGENERALID ,V_I AS LVL FROM ( SELECT DISTINCT JOBROOTGENERALID ,JOBTOGENERALID FROM SESSION.CTMJOBCHAININGB WHERE LVL = (V_I - 1) )F1 INNER JOIN SESSION.CTMJOBRELATIONS X ON F1.JOBTOGENERALID = X.JOBTOGENERALID AND NOT EXISTS (SELECT 1 FROM SESSION.CTMJOBCHAININGB F2 WHERE F2.JOBROOTGENERALID = F1.JOBROOTGENERALID AND F2.JOBTOGENERALID = X.JOBFROMGENERALID ); GET DIAGNOSTICS V_RC_B = ROW_COUNT; SET V_RC = V_RC + V_RC_B; SET V_K = V_I; IF (V_RC_B = 0) THEN SET V_I = V_J; ELSE SET V_I = V_I + 1; END IF; END WHILE; COMMIT; SET V_MSG = COALESCE(V_MSG, '') || '##00 B i=' || CAST(V_K AS VARCHAR(10)) || ' r=' || CAST((COALESCE(V_NRJOBS, 0) + COALESCE(V_RC ,0)) AS VARCHAR(10)) || ' start=' || CAST(V_DATE AS VARCHAR(23)) || ' end=' || CAST(CURRENT_TIMESTAMP AS VARCHAR(23)) || '##' ; BEGIN DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK WORK TO SAVEPOINT CTMSVPOINT; SET V_RETURNVAL = -1; RESIGNAL; RETURN V_RETURNVAL; END; SAVEPOINT CTMSVPOINT ON ROLLBACK RETAIN CURSORS; SET V_DATE = CURRENT_TIMESTAMP; UPDATE CTM_STATUS SET 	CTMPROCESSSTATUSTYPEID = 1, NOTES = COALESCE(NOTES, '') || V_MSG || '##1 - ' || CAST(V_DATE AS VARCHAR(23)) || '##' WHERE CTMID = V_CTMID; IF (V_CTMPROCESSTYPEID = 1) THEN INSERT INTO SESSION.JOBGENERALIDTODROP (JOBGENERALID) SELECT JOBGENERALID FROM CTM_JOBDETAILS WHERE DATASOURCEID IN (SELECT DATASOURCEID FROM SESSION.TODO_CTMDATASOURCEINFO); DELETE FROM CTM_JOBDETAILS WHERE DATASOURCEID IN (SELECT DATASOURCEID FROM SESSION.TODO_CTMDATASOURCEINFO); DELETE FROM CTM_CONDITIONDETAILS T WHERE EXISTS (SELECT 1 FROM SESSION.TODO_CTMDATASOURCEINFO F WHERE F.DATASOURCEID = T.DATASOURCEID); DELETE FROM CTM_JOBTOCONDITIONS T WHERE EXISTS (SELECT 1 FROM SESSION.JOBGENERALIDTODROP F WHERE F.JOBGENERALID = T.JOBGENERALID); DELETE FROM CTM_JOBTOCTMJOBRELATIONS T WHERE EXISTS (SELECT 1 FROM SESSION.JOBGENERALIDTODROP F WHERE F.JOBGENERALID = T.JOBFROMGENERALID) OR EXISTS (SELECT 1 FROM SESSION.JOBGENERALIDTODROP F WHERE F.JOBGENERALID = T.JOBTOGENERALID); DELETE FROM CTM_JOBTOJCLJOBRELATIONS T WHERE EXISTS (SELECT 1 FROM SESSION.JOBGENERALIDTODROP F WHERE F.JOBGENERALID = T.JOBGENERALID); DELETE FROM CTM_JOBCHAININGSB T WHERE EXISTS (SELECT 1 FROM SESSION.JOBGENERALIDTODROP F WHERE F.JOBGENERALID = T.JOBROOTGENERALID); DELETE FROM CTM_JOBCHAININGSF T WHERE EXISTS (SELECT 1 FROM SESSION.JOBGENERALIDTODROP F WHERE F.JOBGENERALID = T.JOBROOTGENERALID); DELETE FROM CTM_USEDDATASOURCES WHERE 1 = 1; ELSE DELETE FROM CTM_CONDITIONDETAILS WHERE 1 = 1 ; DELETE FROM CTM_JOBDETAILS WHERE 1 = 1 ; DELETE FROM CTM_JOBTOCONDITIONS WHERE 1 = 1 ; DELETE FROM CTM_JOBTOCTMJOBRELATIONS WHERE 1 = 1 ; DELETE FROM CTM_JOBTOJCLJOBRELATIONS WHERE 1 = 1 ; DELETE FROM CTM_JOBCHAININGSB WHERE 1 = 1 ; DELETE FROM CTM_JOBCHAININGSF WHERE 1 = 1 ; DELETE FROM CTM_USEDDATASOURCES WHERE 1 = 1 ; END IF; INSERT INTO CTM_USEDDATASOURCES (USEDDATASOURCEID ,USEDDATASOURCENAME ,USEDDATASOURCETYPEID ,UDSPOPULATIONTIMESTAMP ,USEDDATASOURCENUMBEROFJOBS ,ISNEWORCHANGED ,CTMID) SELECT N.DATASOURCEID ,N.DATASOURCENAME ,N.DATASOURCETYPEID ,N.DSPOPULATIONTIMESTAMP ,N.DATASOURCENUMBEROFJOBS ,CASE WHEN V_CTMPROCESSTYPEID = 0 THEN 1 WHEN E.DATASOURCEID IS NULL THEN 1 ELSE 0 END ISNEWORCHANGED ,V_CTMID AS CTMID FROM SESSION.NEW_CTMDATASOURCEINFO N LEFT OUTER JOIN SESSION.EQ_CTMDATASOURCEINFO E ON N.DATASOURCEID = E.DATASOURCEID ; INSERT INTO CTM_CONDITIONDETAILS (CONDITIONGENERALID ,CONDITIONNAME ,DATASOURCEID ,CTMID) SELECT CONDITIONGENERALID ,CONDITIONNAME ,DATASOURCEID ,V_CTMID AS CTMID FROM SESSION.CTMCONDITIONS; INSERT INTO CTM_JOBDETAILS (JOBGENERALID ,JOBORIGINALID ,JOBNAME ,JOBMEMBERNAME ,JOBAPPLICATION ,JOBSUBAPPLICATION ,JOBFOLDERNAME ,JOBDESCRIPTION ,ISOLATIONLEVEL ,DATASOURCEID ,DATASOURCENAME ,DATASOURCETYPEID ,CTMID) SELECT M.JOBGENERALID ,M.JOBID ,M.JOBNAME ,M.JOBMEMBERNAME ,M.JOBAPPLICATION ,M.JOBSUBAPPLICATION ,M.JOBFOLDERNAME ,M.JOBDESCRIPTION ,(0 + COALESCE(I.FLAG ,0) + COALESCE(O.FLAG ,0)) AS ISOLATIONLEVEL ,M.DATASOURCEID ,S.DATASOURCENAME ,V_DATASOURCETYPEID AS DATASOURCETYPEID ,V_CTMID AS CTMID FROM SESSION.CTMJOBINFO M INNER JOIN SESSION.NEW_CTMDATASOURCEINFO S ON M.DATASOURCEID = S.DATASOURCEID LEFT OUTER JOIN (SELECT 1 FLAG ,JOBGENERALID FROM SESSION.CTMJOBINCONDITIONS GROUP BY JOBGENERALID ) I ON M.JOBGENERALID = I.JOBGENERALID LEFT OUTER JOIN (SELECT 2 FLAG ,JOBGENERALID FROM SESSION.CTMJOBOUTCONDITIONS GROUP BY JOBGENERALID ) O ON M.JOBGENERALID = O.JOBGENERALID ; SET V_TOTALNRJOBS = COALESCE((SELECT COUNT(*) FROM CTM_JOBDETAILS) ,0); INSERT INTO CTM_JOBTOCONDITIONS (JOBGENERALID ,CONDITIONGENERALID ,CONDITIONNAME ,ISINCONDITION ,CONDITIONANDOR ,CONDITIONODATE ,ISORPHANCONDITION ,CTMID) SELECT JOBGENERALID ,CONDITIONGENERALID ,CONDITIONNAME ,ISINCONDITION ,CONDITIONANDOR ,CONDITIONODATE ,ISORPHANCONDITION ,V_CTMID AS CTMID FROM ( SELECT M.JOBGENERALID ,M.CONDITIONGENERALID ,M.CONDITIONNAME ,0 AS ISINCONDITION ,CAST(NULL AS VARCHAR(5)) AS CONDITIONANDOR ,M.CONDITIONODATE ,COALESCE(F.ISORPHANCONDITION, 1) AS ISORPHANCONDITION FROM SESSION.CTMJOBOUTCONDITIONS M LEFT OUTER JOIN (SELECT CONDITIONGENERALID, 0 AS ISORPHANCONDITION FROM SESSION.CTMJOBINCONDITIONS GROUP BY CONDITIONGENERALID) F ON M.CONDITIONGENERALID = F.CONDITIONGENERALID UNION ALL SELECT M.JOBGENERALID ,M.CONDITIONGENERALID ,M.CONDITIONNAME ,1 AS ISINCONDITION ,M.CONDITIONANDOR AS CONDITIONANDOR ,M.CONDITIONODATE ,COALESCE(F.ISORPHANCONDITION, 1) AS ISORPHANCONDITION FROM SESSION.CTMJOBINCONDITIONS M LEFT OUTER JOIN (SELECT CONDITIONGENERALID, 0 AS ISORPHANCONDITION FROM SESSION.CTMJOBOUTCONDITIONS GROUP BY CONDITIONGENERALID) F ON M.CONDITIONGENERALID = F.CONDITIONGENERALID )S ; INSERT INTO CTM_JOBTOCTMJOBRELATIONS (JOBFROMGENERALID ,JOBTOGENERALID ,CONDITIONGENERALID ,CONDITIONNAME ,CONDITIONANDOR ,CONDITIONODATE ,CTMID) SELECT JOBFROMGENERALID ,JOBTOGENERALID ,CONDITIONGENERALID ,CONDITIONNAME ,CONDITIONANDOR ,CONDITIONODATE ,V_CTMID AS CTMID FROM SESSION.CTMJOBBASERELATIONS ; INSERT INTO CTM_JOBTOJCLJOBRELATIONS ( JOBGENERALID ,JCLJOBID ,JCLJOBNAME ,JCLPOSITIONSTARTROW ,JCLPOSITIONSTARTCOL ,JCLPOSITIONENDROW ,JCLPOSITIONENDCOL ,JCLPOSITIONRESOURCEFILEPATH ,CTMID) SELECT CJD.JOBGENERALID ,SRC1.JCLJOBID ,SRC1.JCLJOBNAME ,SRC1.JCLPOSITIONSTARTROW ,SRC1.JCLPOSITIONSTARTCOL ,SRC1.JCLPOSITIONENDROW ,SRC1.JCLPOSITIONENDCOL ,SRC1.JCLPOSITIONRESOURCEFILEPATH ,V_CTMID AS CTMID FROM ( SELECT JJ.JOBID AS JCLJOBID ,JJ.JOBNAME AS JCLJOBNAME ,TRIM(JJ.MEMBERNAME) AS JCLMEMBERNAME ,JP.STARTROW AS JCLPOSITIONSTARTROW ,JP.STARTCOL AS JCLPOSITIONSTARTCOL ,JP.ENDROW AS JCLPOSITIONENDROW ,JP.ENDCOL AS JCLPOSITIONENDCOL ,JP.RESOURCEFILEPATH AS JCLPOSITIONRESOURCEFILEPATH ,ROW_NUMBER() OVER(PARTITION BY TRIM(JJ.MEMBERNAME) ORDER BY JJ.JOBID ) AS RN FROM JCLJOB JJ INNER JOIN JCLPOSITION JP ON JP.POSITIONID = JJ.POSITIONID WHERE JJ.BUILDSTATUS = 1 ) SRC1 INNER JOIN SESSION.CTMJOBINFO CJD ON SRC1.RN = 1 AND SRC1.JCLMEMBERNAME = CJD.JOBMEMBERNAME; INSERT INTO CTM_JOBCHAININGSF (JOBROOTGENERALID ,JOBTOGENERALID ,LVL ,CTMID) SELECT JOBROOTGENERALID ,JOBTOGENERALID ,LVL ,V_CTMID AS CTMID FROM SESSION.CTMJOBCHAININGF ; INSERT INTO CTM_JOBCHAININGSB (JOBROOTGENERALID ,JOBTOGENERALID ,LVL ,CTMID) SELECT JOBROOTGENERALID ,JOBTOGENERALID ,LVL ,V_CTMID AS CTMID FROM SESSION.CTMJOBCHAININGB ; SET V_DATE = CURRENT_TIMESTAMP; UPDATE CTM_STATUS SET CTMPROCESSSTATUSTYPEID = 2, CTMPROCESSTYPE = CASE V_CTMPROCESSTYPEID WHEN 0 THEN 'FULL' ELSE 'PARTIAL' END, CTMJOBTOTALCOUNT = V_TOTALNRJOBS, NOTES = 'NrJobsProcessed=' || CAST((COALESCE(V_NRJOBS, 0)) AS VARCHAR(10)) || ' ' || COALESCE(NOTES, '') || '##2 - '|| CAST(V_DATE AS VARCHAR(23)) || '##' WHERE CTMID = V_CTMID; RELEASE SAVEPOINT CTMSVPOINT; COMMIT; END; END; END; END @
CREATE OR REPLACE PROCEDURE SETTS_CSDCONFIGFILES ( IN P_YEARPARAM VARCHAR(10), IN P_MONTHPARAM VARCHAR(10), IN P_DAYPARAM VARCHAR(10), IN P_HOURPARAM VARCHAR(10), IN P_MINPARAM VARCHAR(10), IN P_SECPARAM VARCHAR(10), IN P_PATHSTRPARAM VARCHAR(250) ) LANGUAGE SQL SS: BEGIN DECLARE V_YEARPARAM, V_MONTHPARAM, V_DAYPARAM, V_HOURPARAM, V_MINPARAM, V_SECPARAM VARCHAR(10); DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE V_TS TIMESTAMP; SET V_YEARPARAM = P_YEARPARAM; SET V_MONTHPARAM = P_MONTHPARAM; SET V_DAYPARAM = P_DAYPARAM; SET V_HOURPARAM = P_HOURPARAM; SET V_MINPARAM = P_MINPARAM; SET V_SECPARAM = P_SECPARAM; SET V_PATHSTRPARAM = P_PATHSTRPARAM; SET V_TS = ( SELECT TIMESTAMP_FORMAT( V_YEARPARAM || '-' || V_MONTHPARAM || '-' || V_DAYPARAM || ' ' || V_HOURPARAM || ':' || V_MINPARAM || ':' || V_SECPARAM, 'YYYY-MM-DD HH24:MI:SS') FROM SYSIBM.SYSDUMMY1 ); UPDATE MFCICSLIST MFCL SET MFCL.ETIMESTAMP = V_TS WHERE EXISTS ( SELECT 1 FROM OCCURRENCES OCC INNER JOIN PATHS PTH ON OCC.PATHID = PTH.PATHID WHERE OCC.RESOURCETYPE = 216 AND MFCL.OCCURID = OCC.OCCURID AND PTH.PATHSTR = V_PATHSTRPARAM ); END@
CREATE OR REPLACE PROCEDURE GETPSBPATHS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PATHS.PATHSTR FROM PSBINFO INNER JOIN OCCURRENCES ON PSBINFO.OCCURID = OCCURRENCES.OCCURID INNER JOIN PATHS ON OCCURRENCES.PATHID = PATHS.PATHID; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETPROGFILEPERPSB ( IN PATHSTRPARAM VARCHAR(250) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_PATHSTRPARAM VARCHAR(250); DECLARE CRS CURSOR WITH RETURN FOR SELECT PATHS.PATHSTR FROM PSBINFO INNER JOIN PROGRAMS ON PSBINFO.PROGID = PROGRAMS.PROGRAMID INNER JOIN OCCURRENCES ON PROGRAMS.OCCURID = OCCURRENCES.OCCURID INNER JOIN PATHS ON OCCURRENCES.PATHID = PATHS.PATHID INNER JOIN OCCURRENCES AS OCCURRENCES_1 ON PSBINFO.OCCURID = OCCURRENCES_1.OCCURID INNER JOIN PATHS AS PATHS_1 ON OCCURRENCES_1.PATHID = PATHS_1.PATHID WHERE PATHS_1.PATHSTR = V_PATHSTRPARAM; SET V_PATHSTRPARAM = PATHSTRPARAM; OPEN CRS; END@
CREATE OR REPLACE PROCEDURE GETJCLINCLUDEGROUPPATHS() DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT JP.RESOURCEFILEPATH FROM JCLPOSITION JP INNER JOIN JCLINCLUDEGROUP JG ON JP.POSITIONID = JG.POSITIONID WHERE JP.RESOURCETYPE = 33; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE GETJCLJOBFILESPERJCLINCLUDEGROUPFILE ( P_RESOURCEFILEPATHPARAM VARCHAR(250) ) DYNAMIC RESULT SETS 1 LANGUAGE SQL BEGIN DECLARE V_RESOURCEFILEPATHPARAM VARCHAR(250); DECLARE CRS CURSOR WITH RETURN FOR SELECT DISTINCT JPOS1.RESOURCEFILEPATH FROM JCLPOSITION JPOS1 INNER JOIN JCLJOB JJ ON JPOS1.POSITIONID = JJ.POSITIONID INNER JOIN JCLINCLUDECONN JIC ON JJ.JOBID = JIC.JOBID INNER JOIN JCLINCLUDEGROUP JIG ON JIG.INCLUDEID = JIC.INCLUDEID INNER JOIN JCLPOSITION JPOS2 ON JPOS2.POSITIONID = JIG.POSITIONID WHERE JPOS2.RESOURCEFILEPATH = V_RESOURCEFILEPATHPARAM AND JPOS2.RESOURCETYPE = 33 AND JPOS1.RESOURCETYPE = 22; SET V_RESOURCEFILEPATHPARAM = P_RESOURCEFILEPATHPARAM; OPEN CRS; END @
CREATE OR REPLACE PROCEDURE REBIND_ONLINE() DYNAMIC RESULT SETS 0 LANGUAGE SQL BEGIN DECLARE PKG_NAME VARCHAR(200); DECLARE SQLSTATE CHAR(5) DEFAULT '00000'; DECLARE R_ERROR INT DEFAULT 0; DECLARE SQLCODE INT DEFAULT 0; DECLARE CONTINUE HANDLER FOR SQLSTATE '38000' BEGIN SET R_ERROR = SQLCODE; END; BEGIN DECLARE CRS CURSOR FOR SELECT SPECIFICNAME FROM SYSCAT.ROUTINES WHERE ROUTINESCHEMA = 'EZSCH' AND ROUTINETYPE = 'P' AND ROUTINENAME != 'REBIND_ONLINE' ORDER BY ROUTINENAME; OPEN CRS; FETCH FROM CRS INTO PKG_NAME; WHILE(SQLSTATE = '00000') DO CALL SYSPROC.REBIND_ROUTINE_PACKAGE('SP','EZSCH'||'.'||PKG_NAME,'CONSERVATIVE'); FETCH FROM CRS INTO PKG_NAME; END WHILE; CLOSE CRS; END; END @
