CREATE OR REPLACE PROCEDURE DEL_AAUTONETWORKS_BYPATH_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.OCCURID FROM OCCURRENCES OCC WHERE OCC.RESOURCETYPE = 5000 AND OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.OCCURID; DELETE FROM AAUTONETWORKS A WHERE A.OCCURID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_AAUTO_DSFLAGTONETWORKS_BYPATH_LIST LANGUAGE SQL BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.OCCURID FROM OCCURRENCES OCC WHERE OCC.RESOURCETYPE = 206 AND OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.OCCURID; DELETE FROM AAUTODSFLAGTONETWORKS A WHERE A.OCCURID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END@
CREATE OR REPLACE PROCEDURE DEL_ADSMAPSOCCURIDBYPATH_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.OCCURID FROM OCCURRENCES OCC WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.OCCURID; UPDATE ADSMAPS SET ADSMAPS.OCCURID = 0 WHERE ADSMAPS.OCCURID IN (SELECT D.SEMANTICID FROM SESSION.DELTBL D); END; END@
CREATE OR REPLACE PROCEDURE DEL_APICALLFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM APICALL A WHERE A.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
