CREATE OR REPLACE PROCEDURE DEL_IMSIOFORMATOCCURBYPATH_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.OCCURID FROM OCCURRENCES OCC WHERE OCC.RESOURCEID <> 1 AND OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.OCCURID; DELETE FROM IMSMAPIOFORMAT I WHERE I.OCCURID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
