CREATE OR REPLACE PROCEDURE DEL_PARAGRAPHARGUMENTSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM PARAGRAPHARGUMENTS P WHERE P.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
