CREATE OR REPLACE PROCEDURE DEL_PCBVSIMSFIELDSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PCB.PSBID FROM PCBINFO PCB INNER JOIN PSBINFO PSB ON PCB.PSBID = PSB.PSBID INNER JOIN PROGRAMS PGM ON PSB.PROGID = PGM.PROGRAMID INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) AND PCB.PSBID IS NOT NULL GROUP BY PCB.PSBID; DELETE FROM PCBVSIMSFIELDS P WHERE P.PCBID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
