CREATE OR REPLACE PROCEDURE QREMOVEPROGRAMONPROGID_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.OCCURID FROM OCCURRENCES OCC WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.OCCURID; UPDATE PROGRAMS PRG SET PRG.OCCURID = 0 WHERE PRG.OCCURID IN (SELECT D.SEMANTICID FROM SESSION.DELTBL D); END; END@
CREATE OR REPLACE PROCEDURE QREMOVEPROGSEMANTICUIDFROMPROGID_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM OCCURRENCES OCC INNER JOIN PROGRAMS PGM ON OCC.OCCURID = PGM.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM SEMANTICUIDCONTAINER SC WHERE SC.RESOURCETYPE = 5 AND SC.RESOURCEID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVEREPLACESTATEMENTFROMPROGID_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON OCC.OCCURID=PGM.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM REPLACESTATEMENT RS WHERE RS.PROGRAMID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
