CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_ASMINCLUDE_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.PATHID FROM OCCURRENCES OCC1 INNER JOIN OCCURRENCESSTMT OS ON OCC1.PROGID = OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN RESOURCES RES ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN OCCURRENCES OCC ON RES.OCCURID = OCC.OCCURID WHERE OS.STATEMENTTYPE = 1669 AND SR.RESOURCETYPE = 99 AND OCC1.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.PATHID; DELETE FROM STATISTICSLINES S WHERE S.SCOPEID = 8 AND S.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_ASMMACRO_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.PATHID FROM ASSEMBLERMACROS AM INNER JOIN STATEMENTREFERENCE SR ON AM.ID = SR.RESOURCEID INNER JOIN OCCURRENCESSTMT OS ON OS.OCCURID = SR.OCCURID INNER JOIN OCCURRENCES OCC1 ON OS.PROGID = OCC1.PROGID INNER JOIN OCCURRENCES OCC ON AM.OCCURID = OCC.OCCURID WHERE OS.STATEMENTTYPE = 819 AND SR.RESOURCETYPE = 98 AND OCC.OCCURID > 0 AND OCC1.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.PATHID; DELETE FROM STATISTICSLINES S WHERE S.SCOPEID = 9 AND S.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
