CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_COBOLINCLUDE_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.PATHID FROM OCCURRENCES OCC1 INNER JOIN OCCURRENCESSTMT OS ON OCC1.PROGID =OS.PROGID INNER JOIN STATEMENTREFERENCE SR ON OS.OCCURID = SR.OCCURID INNER JOIN RESOURCES RES ON SR.RESOURCEID = RES.RESOURCEID INNER JOIN OCCURRENCES OCC ON RES.OCCURID = OCC.OCCURID WHERE OS.STATEMENTTYPE = 44 AND SR.RESOURCETYPE = 13 AND OCC1.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.PATHID; DELETE FROM STATISTICSLINES S WHERE S.SCOPEID = 3 AND S.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_COBOLPGM_LIST LANGUAGE SQL BEGIN DELETE FROM STATISTICSLINES SL WHERE SL.SCOPEID IN (1,2,13,14) AND SL.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS); END@
CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_JCLCTRL_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PTH.PATHID FROM JCLJOB JJ INNER JOIN JCLINCLUDECONN JIC ON JJ.JOBID = JIC.JOBID INNER JOIN JCLINCLUDEGROUP JIG ON JIC.INCLUDEID = JIG.INCLUDEID INNER JOIN JCLPOSITION JPOS ON JJ.POSITIONID = JPOS.POSITIONID INNER JOIN JCLPOSITION JPOS1 ON JIG.POSITIONID = JPOS1.POSITIONID INNER JOIN PATHS PTH ON JPOS1.RESOURCEFILEPATH = PTH.PATHSTR WHERE JPOS1.POSITIONID > 0 AND JIC.POSITIONID = 0 AND JPOS.POSITIONID IN (SELECT POSITIONID FROM SESSION.TEMP_INPUT_PARAM_JCLPOSITIONS) GROUP BY PTH.PATHID; DELETE FROM STATISTICSLINES S WHERE S.SCOPEID = 12 AND S.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_JCLINCLUDE_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PTH.PATHID FROM JCLDD JCD INNER JOIN JCLJOB ON JCD.JOBID = JCLJOB.JOBID INNER JOIN JCLPOSITION JCP ON JCP.POSITIONID = JCLJOB.POSITIONID INNER JOIN JCLPOSITION AS JCLPOSITION_1 ON JCD.POSITIONID = JCLPOSITION_1.POSITIONID AND JCP.RESOURCEFILEPATH <> JCLPOSITION_1.RESOURCEFILEPATH INNER JOIN PATHS PTH ON JCLPOSITION_1.RESOURCEFILEPATH = PTH.PATHSTR WHERE JCD.PROCID = 0 AND JCLPOSITION_1.RESOURCEFILEPATH <> '' AND JCP.POSITIONID IN (SELECT POSITIONID FROM SESSION.TEMP_INPUT_PARAM_JCLPOSITIONS) GROUP BY PTH.PATHID; DELETE FROM STATISTICSLINES S WHERE S.SCOPEID = 11 AND S.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
