CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_JCLPROC_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PTH.PATHID FROM JCLPOSITION JPOS INNER JOIN JCLJOB JJ ON JPOS.POSITIONID = JJ.POSITIONID INNER JOIN JCLSTEP JS ON JJ.JOBID = JS.JOBID INNER JOIN JCLPROC JPROC ON JS.CALLEDPROCID = JPROC.PROCID INNER JOIN JCLPOSITION JPOS1 ON JPROC.POSITIONID = JPOS1.POSITIONID INNER JOIN PATHS PTH ON JPOS1.RESOURCEFILEPATH = PTH.PATHSTR WHERE JPOS1.RESOURCETYPE = 25 AND JPOS.RESOURCETYPE = 22 AND JPOS.POSITIONID IN (SELECT POSITIONID FROM SESSION.TEMP_INPUT_PARAM_JCLPOSITIONS) GROUP BY PTH.PATHID; DELETE FROM STATISTICSLINES S WHERE S.SCOPEID = 10 AND S.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVESTATISTICSLINES_PL1INCLUDE_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.PATHID FROM OCCURRENCES OCC1 INNER JOIN OCCURRENCESSTMT OCCST ON OCC1.PROGID = OCCST.PROGID INNER JOIN STATEMENTREFERENCE STREF ON OCCST.OCCURID = STREF.OCCURID INNER JOIN RESOURCES RES ON STREF.RESOURCEID = RES.RESOURCEID INNER JOIN OCCURRENCES OCC ON RES.OCCURID = OCC.OCCURID WHERE OCCST.STATEMENTTYPE = 413 AND STREF.RESOURCETYPE = 67 AND OCC1.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.PATHID; DELETE FROM STATISTICSLINES SL WHERE SCOPEID = 21 AND SL.PATHID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
