CREATE OR REPLACE PROCEDURE QRESETOCCURIDFROMNATURALDBVIEWFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCC.OCCURID FROM OCCURRENCES OCC WHERE OCC.RESOURCETYPE = 193 AND OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCC.OCCURID; UPDATE NATURALDBVIEW SET NATURALDBVIEW.OCCURID = -1 WHERE NATURALDBVIEW.OCCURID IN (SELECT D.SEMANTICID FROM SESSION.DELTBL D); END; END@
