CREATE OR REPLACE PROCEDURE QUPDATEIDMSSUBSCHEMARECORDS_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT ISUBSCHEMAREC.OCCURID FROM IDMSSUBSCHEMA ISUBSCHEMA INNER JOIN OCCURRENCES OCC ON ISUBSCHEMA.OCCURID = OCC.OCCURID INNER JOIN IDMSSUBSCHEMARECORDS ISUBSCHEMAREC ON ISUBSCHEMA.ID = ISUBSCHEMAREC.SUBSCHEMAID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY ISUBSCHEMAREC.OCCURID; UPDATE IDMSSUBSCHEMARECORDS SET IDMSSUBSCHEMARECORDS.OCCURID=0 WHERE IDMSSUBSCHEMARECORDS.OCCURID IN (SELECT D.SEMANTICID FROM SESSION.DELTBL D); END; END@
CREATE OR REPLACE PROCEDURE QUPDATEIDMSSUBSCHEMASETS_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT ISUBSCHEMASET.OCCURID FROM IDMSSUBSCHEMA ISUBSCHEMA INNER JOIN OCCURRENCES OCC ON ISUBSCHEMA.OCCURID = OCC.OCCURID INNER JOIN IDMSSUBSCHEMASETS ISUBSCHEMASET ON ISUBSCHEMA.ID = ISUBSCHEMASET.SUBSCHEMAID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY ISUBSCHEMASET.OCCURID; UPDATE IDMSSUBSCHEMASETS SET IDMSSUBSCHEMASETS.OCCURID=0 WHERE IDMSSUBSCHEMASETS.OCCURID IN (SELECT D.SEMANTICID FROM SESSION.DELTBL D); END; END@
CREATE OR REPLACE PROCEDURE QUPDATEIDMSSUBSCHEMA_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT ISUBSCHEMA.OCCURID FROM (IDMSSUBSCHEMA ISUBSCHEMA INNER JOIN OCCURRENCES OCC ON ISUBSCHEMA.OCCURID = OCC.OCCURID) WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY ISUBSCHEMA.OCCURID; UPDATE IDMSSUBSCHEMA SET IDMSSUBSCHEMA.OCCURID = 0 WHERE IDMSSUBSCHEMA.OCCURID IN (SELECT D.SEMANTICID FROM SESSION.DELTBL D); END; END@
CREATE OR REPLACE PROCEDURE QREMOVE_DECISIONFILESBYDNAME ( IN P_DNAME VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_DNAME VARCHAR(256); SET V_DNAME = P_DNAME; DELETE FROM DECISIONFILES WHERE DECISIONID IN ( SELECT DECISIONID FROM DECISIONS WHERE NAME = V_DNAME ) ; END@
