CREATE OR REPLACE PROCEDURE QREMOVE_DECISIONSBYDNAME ( IN P_DNAME VARCHAR(256) ) LANGUAGE SQL BEGIN DECLARE V_DNAME VARCHAR(256); SET V_DNAME = P_DNAME; DELETE FROM DECISIONS WHERE NAME = V_DNAME; END@
