CREATE OR REPLACE PROCEDURE DEL_GENERICAPICALLFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM GENERICAPICALL A WHERE A.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVENATURALPROGRAMALIASESFROMPROGID_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS	NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE PGM.PROGRAMTYPEID=3 AND OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM PROGRAMALIASES PA WHERE PA.PROGRAMID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_PGMPARAMETERSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM PGMPARAMETERS P WHERE P.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_PGMCALLARGUMENTSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM PGMCALLARGUMENTS P WHERE P.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_PGMRETURNRESOURCESFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM PGMRETURNRESOURCES P WHERE P.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE QREMOVESCOPEINFOID_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT OCS.OCCURID FROM OCCURRENCESSTMT OCS INNER JOIN OCCURRENCES OCC ON OCC.PROGID = OCS.PROGID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY OCS.OCCURID; DELETE FROM SCOPEINFO E WHERE E.OCCURRENCESSTMTID IN (SELECT SEMANTICID  FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_EXPRESSIONSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM EXPRESSIONS E WHERE E.PROGID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_EXPRESSIONELEMENTSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT EE.EXPRELEMID FROM EXPRESSIONELEMENTS EE INNER JOIN EXPRESSIONS E ON EE.EXPRID = E.EXPRID INNER JOIN PROGRAMS PGM ON E.PROGID = PGM.PROGRAMID INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY EE.EXPRELEMID; DELETE FROM EXPRESSIONELEMENTS EE WHERE EE.EXPRELEMID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE DEL_STATEMENTREFERENCELINKSFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT STL.STMTREFLINKID FROM STATEMENTREFERENCELINKS STL INNER JOIN OCCURRENCESSTMT OS ON STL.STMTOCCURID = OS.OCCURID INNER JOIN PROGRAMS PGM ON PGM.PROGRAMID = OS.PROGID INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY STL.STMTREFLINKID; DELETE FROM STATEMENTREFERENCELINKS STL WHERE STL.STMTREFLINKID IN (SELECT SEMANTICID FROM SESSION.DELTBL); END; END@
CREATE OR REPLACE PROCEDURE GET_PROGCALLCHAINRECURSIVE(IN PROGPATH VARCHAR(256)) DYNAMIC RESULT SETS 1 CALLED ON NULL INPUT LANGUAGE SQL BEGIN DECLARE PROGID INTEGER DEFAULT 0; DECLARE LEVEL INTEGER DEFAULT 0; DECLARE RC INTEGER DEFAULT 1; DECLARE MAXDEPTHLEVEL INTEGER DEFAULT 20; DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMP_CALLCHAIN(CALLINGPROGID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMP_CURRENTCALLEDPROGS(PROGID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; DECLARE GLOBAL TEMPORARY TABLE SESSION.TEMP_PROGS(PROGID INTEGER) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED; CREATE INDEX CURRENTCALLEDPROGINDEX ON SESSION.TEMP_CURRENTCALLEDPROGS(PROGID); INSERT INTO SESSION.TEMP_CURRENTCALLEDPROGS SELECT PROGID FROM PROGRAMS JOIN OCCURRENCES ON PROGRAMS.OCCURID = OCCURRENCES.OCCURID JOIN PATHS ON PATHS.PATHID = OCCURRENCES.PATHID WHERE PATHS.PATHSTR = PROGPATH; INSERT INTO SESSION.TEMP_CURRENTCALLEDPROGS VALUES(PROGID); WHILE (RC > 0 AND LEVEL < MAXDEPTHLEVEL) DO BEGIN INSERT INTO SESSION.TEMP_PROGS SELECT OCCURRENCESSTMT.PROGID FROM OCCURRENCESSTMT JOIN STATEMENTREFERENCE ON OCCURRENCESSTMT.OCCURID = STATEMENTREFERENCE.OCCURID JOIN SESSION.TEMP_CURRENTCALLEDPROGS ON STATEMENTREFERENCE.RESOURCEID = SESSION.TEMP_CURRENTCALLEDPROGS.PROGID WHERE STATEMENTREFERENCE.RESOURCETYPE = 5 AND OCCURRENCESSTMT.STATEMENTTYPE = 10 AND OCCURRENCESSTMT.PROGID NOT IN (SELECT CALLINGPROGID FROM SESSION.TEMP_CALLCHAIN); DELETE FROM SESSION.TEMP_CURRENTCALLEDPROGS; INSERT INTO SESSION.TEMP_CURRENTCALLEDPROGS SELECT PROGID FROM SESSION.TEMP_PROGS; INSERT INTO SESSION.TEMP_CALLCHAIN SELECT PROGID FROM SESSION.TEMP_PROGS; DELETE FROM SESSION.TEMP_PROGS; GET DIAGNOSTICS RC = ROW_COUNT; SET LEVEL = LEVEL + 1; COMMIT; END; END WHILE; BEGIN DECLARE CRS CURSOR WITH RETURN FOR SELECT PATHS.PATHSTR FROM PATHS JOIN OCCURRENCES ON PATHS.PATHID = OCCURRENCES.PATHID JOIN PROGRAMS ON PROGRAMS.OCCURID = OCCURRENCES.OCCURID WHERE PROGRAMS.PROGRAMID IN ( SELECT * FROM SESSION.TEMP_CALLCHAIN); OPEN CRS; END; END@
CREATE OR REPLACE PROCEDURE DEL_PROGRAMPROPFORPROG_LIST LANGUAGE SQL BEGIN BEGIN DECLARE GLOBAL TEMPORARY TABLE SESSION.DELTBL( SEMANTICID INTEGER NOT NULL ) WITH REPLACE ON COMMIT PRESERVE ROWS NOT LOGGED ; CREATE UNIQUE INDEX UNQIDX_DELTBL ON SESSION.DELTBL (SEMANTICID); INSERT INTO SESSION.DELTBL (SEMANTICID) SELECT PGM.PROGRAMID FROM PROGRAMS PGM INNER JOIN OCCURRENCES OCC ON PGM.OCCURID = OCC.OCCURID WHERE OCC.PATHID IN (SELECT PATHID FROM SESSION.TEMP_INPUT_PARAM_PATHS) GROUP BY PGM.PROGRAMID; DELETE FROM PROGRAMPROP P WHERE EXISTS (SELECT 1 FROM SESSION.DELTBL D WHERE D.SEMANTICID = P.PROGID); END; END@ 
